quests[9977] = { id = 9977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ring des Blutes: die letzte Herausforderung", description = "<Gurgthock zählt seinen riesigen Berg Gold.>\n\nIhr habt viel Geld eingebracht, <Kleiner/Kleine>. Wenn Ihr Mogor besiegt, verspreche ich, dass es sich für euch lohnen wird. Die ganzen Schmerzen, die Ihr im Ring des Blutes aushalten musstet, werden sich bezahlt machen.\n\nJetzt geht da rein und zeigt diesen Ogern, was in Euch steckt!", sourceObjective = "Besiegt Mogor, Held der Totschläger. Wenn Ihr gewinnen solltet, sprecht mit Wodin dem Trolldiener um Eure Belohnung zu erhalten.", progress = "Der Kampf ist vorüber, wenn Ihr oder Euer Gegner tot zu Boden geht.", completion = "Gurgthock hat doch gesagt, dass es sich bezahlt machen wird, Kleiner. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[9978] = { id = 9978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit allen Mitteln", description = "Ich bin mir nicht sicher, was das zu bedeuten hat, aber ich weiß, wie wir an weitere Hinweise kommen können.\n\nEmpoor ist ein Händler der Zerschlagenen, der mit allen Arten von Waren und Informationen handelt. Wenn wir ihn zum Reden bringen könnten, bin ich mir sicher, dass er etwas Interessantes zu sagen hätte.\n\nEr reist auf der Straße zwischen Tuurem und Shattrath hin und her. Seid aber vorsichtig, er hat einen Leibwächter.", sourceObjective = "Findet Empoor. Er hält sich auf der Straße zwischen Tuurem und Shattrath in den Wäldern von Terokkar auf. Bringt ihn dazu, Euch zu erzählen, was Ihr wissen wollt.", completion = "Gut, gut... Ich sage Euch, was ich weiß, aber viel ist das nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9979] = { id = 9979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windhändler Lathrai", description = "Ich wurde gebeten, ein paar Kästen mit Waren bei einem Astralen in Shattrath abzuholen und auszuliefern.\n\nAls ich ihn das letzte Mal gesehen habe, stand er außerhalb der Taverne Weltenend im Unteren Viertel. Sein Name ist Windhändler Lathrai, mehr weiß ich nicht!\n\nWenn Ihr mehr wissen wollt, dann fragt ihn selbst!", sourceObjective = "Sprecht mit Windhändler Lathrai in der Nähe der Taverne Weltenend im unteren Viertel in Shattrath.", completion = "Ja? Wie kann ich Euch diesmal helfen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9980] = { id = 9980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Deirom!", description = "Macht Euch so schnell Ihr könnt ins Shalasversteck auf, {name}! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Deirom wegzubringen oder gar zu töten!\n\nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Deirom gefunden habt, kehrt zu Allerias Feste zurück und benachrichtigt Thander.", sourceObjective = "Begebt Euch ins Shalasversteck, tötet Lunga und befreit Deirom. Meldet Euch bei Lady Dana Kennedy in Allerias Feste, wenn Ihr Euren Auftrag erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9981] = { id = 9981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Dugar!", description = "Macht Euch so schnell Ihr könnt ins Shalasversteck auf, {name}! Zeit ist von äußerster Wichtigkeit. Wenn die Arakkoa bemerken, was Ihr mit ihrer Verteidigung angestellt habt, werden sie wahrscheinlich versuchen, Dugar wegzubringen oder gar zu töten!\n\nNehmt ein oder zwei Freunde mit, wenn Ihr könnt. Es wird wahrscheinlich hart werden. Die Vogelwesen haben alles getan, um ihren Gefangenen unter Verschluss zu halten, und sie werden ihn sicher nicht so leicht aufgeben. Wenn Ihr Dugar gefunden habt, kehrt zur Steinbrecherfeste zurück und benachrichtigt Rokag.", sourceObjective = "Begebt Euch ins Shalasversteck, tötet Lunga und befreit Dugar. Meldet Euch bei Rokag in der Steinbrecherfeste, wenn Ihr Euren Auftrag erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9982] = { id = 9982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9983] = { id = 9983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er nannte sich Altruis...", description = "Ende letzter Woche kam ein Wesen auf einem Netherdrachen ins Dorf. Er stellte sich als Altruis vor und stellte uns ein paar Fragen über Nagrand.\n\nEr sagte, er würde die Legion jagen. Das so etwas Wahnsinniges tatsächlich sein Job wäre. Könnt Ihr Euch das vorstellen? Eine Person, die freiwillig Dämonen jagt?\n\nVor seiner Abreise bat er uns noch, angehende Helden wissen zu lassen, dass er eine Weile im Westen Nagrands bleiben würde, falls sie auf der Suche nach einer Aufgabe wären.", sourceObjective = "Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand.", completion = "Überrascht Euch mein Aussehen? Wisst Ihr, was ich bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[9984] = { id = 9984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Deirom gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Thander erwähnt hat, dass Andarl die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Andarl in Allerias Feste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9985] = { id = 9985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der versteckten Stadt", description = "Auch wenn Ihr die merkwürdige Schrift auf der Rolle nicht lesen könnt, deutet das verzierte Siegel am Ende des Dokuments darauf hin, dass es von einem Arakkoa von höherem Rang geschrieben wurde. Luanga mag vielleicht hinter der Gefangennahme und dem Verhör von Dugar gesteckt haben, aber es scheint, als hätte er die Befehle einer anderen Person ausgeführt.\n\nIch erinnert Euch, dass Rokag erwähnt hat, dass Kurgatok die Arakkoa studiert hat. Vielleicht kann er den Inhalt der Schriftrolle entziffern.", sourceObjective = "Bringt Luangas Befehle zu Kurgatok in der Steinbrecherfeste in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9986] = { id = 9986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Thander in Allerias Feste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9987] = { id = 9987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arakkoa hindern", description = "Wir müssen den Arakkoa zeigen, dass sie unsere Leute nicht ungestraft angreifen können. Wenn wir sie jetzt nicht aufhalten, werden unsere Straßen für die Händler, Kuriere oder Soldaten nicht mehr sicher sein.\n\nMeine Späher haben die Anführer der größeren Arakkoasiedlungen in der Gegend ermittelt. Sucht Ashkaz, Ayit und Urdak im Reskkversteck, im Shienorversteck und im Skithversteck und tötet sie.", sourceObjective = "Tötet Ashkaz im Reskkversteck, Ayit im Shienorversteck und Urdak im Skithversteck und kehrt dann zu Rokag in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {name}. Wir haben schon genug Sorgen, wir können uns nicht erlauben, dass die Arakkoa unsere Händler und Boten erneut angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9988] = { id = 9988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund eines Gecken", description = "Lasst Euch von Thander und seinem Gefolge nicht täuschen. Sie sehen vielleicht aus wie eine Gruppe von Furcht einflößenden Kriegern, aber sie sind nichts als eine Bande von Gecken!\n\nUnd sie lassen sich in der Öffentlichkeit nicht ohne ihre Hüte sehen. Das sind ganz schicke Teile aus Filz und Fell, mit den ausgefallensten Federn, die Ihr je gesehen habt.\n\nDie begehrtesten Federn stammen natürlich von den Arakkoa, und mein Vorrat geht langsam zur Neige. Ich würde Euch bezahlen, wenn Ihr sie für mich sammelt.", sourceObjective = "Bringt 30 Arakkoafedern zu Ros'eleth in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9989] = { id = 9989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Geister", description = "Als ich in die Scherbenwelt kam und meine Ohren den Stimmen seiner Geister geöffnet habe, war ich erstaunt, was ich zu hören bekam. Nach einiger Zeit fand ich auch heraus, welche Geister ich nicht hören konnte.\n\nTrotz all meiner Versuche habe ich niemals mit den Geistern der Arakkoaahnen Kontakt aufnehmen können. Ihre Magie unterscheidet sich grundlegend von unserer, aber ich bin mir nicht sicher, ob ihre Geister außerhalb meiner Reichweite liegen.\n\nBringt mir die Federn vieler Arakkoa. Vielleicht kann ein Zeichen ihres Volks die nötige Verbindung herstellen.", sourceObjective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[9990] = { id = 9990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung von Tuurem", description = "Wisst Ihr, jetzt, da Ihr es sagt, erinnere ich mich daran, dass ich Empoor vor etwa einem Monat mehrere Kästen mit merkwürdigen und fremdartigen Bauteilen verkauft habe. Ich weiß nicht, wozu sie gut sind, aber ich weiß, dass sie nach Tuurem geliefert werden sollten.\n\nVielleicht sind dort ja noch ein paar Kästen davon?", sourceObjective = "Findet den versiegelten Kasten und bringt ihn zu Erdbinder Tavgren beim Cenariusdickicht in den Wäldern von Terokkar.", progress = "Welche Neuigkeiten bringt Ihr, {name}?", completion = "Astrale? Waren nach Tuurem? Fremdartige Bauteile? Und ein Blutelf, der den letzten Kasten zum Posten der Feuerschwingen bringen wollte?\n\nWas soll das alles bedeuten?! Was hat das mit dem Schicksal der Druiden im Cenariusdickicht zu tun?\n\nIch glaube, wir sollten einmal einen Blick in den Kasten werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9991] = { id = 9991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspektion des Lagers", description = "Wenn Ihr meine Augen sein wollt, müsst Ihr sehr sorgfältig sein. Nethrandamus wird Euch durch die Lager der Legion führen, aber Ihr müsst alles, was Ihr seht, katalogisieren. Selbst das kleinste Detail, und wenn Euch noch so unwichtig erscheint, kann für unsere Zwecke hilfreich sein.\n\nZuerst möchte ich, dass Ihr notiert, welchen Aufbau das Lager hat und wie seine Verteidigungsmaßnahmen aussehen.\n\nNethrandamus ist bereit, wenn Ihr es seid, {name}. Habt keine Angst, er wird Euch beschützen.", sourceObjective = "Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist.", progress = "Noch nie auf einem Netherdrachen geflogen, was?", completion = "Ausgezeichnete Arbeit, {name}! Jetzt haben wir einen Ausgangspunkt um unseren Gegenangriff zu planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9992] = { id = 9992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembasamen", description = "Sind die Bäume des Waldes nicht wunderschön? Ich habe mich schon oft gefragt, ob sie wohl auch in Azeroth wachsen würden.\n\nIch scheue mich jedoch davor, Keimlinge zurückzuschicken. Es ist ein anstrengender Weg und sie sind viel schwieriger zu transportieren als ein Sack mit Samen. Die Samenkörner wachsen in harten Zapfen, die von den Ästen der Bäume fallen, wenn sie reif sind.\n\nWenn Ihr auf Euren Reisen ein paar dieser Zapfen findet, könntet Ihr mir dann ein paar Samenkörner bringen?", sourceObjective = "Sammelt 30 Olembasamenkörner und kehrt dann zu Ros'eleth in Allerias Feste zurück.", progress = "Ich habe eine Samenkornsammlung angefangen, aber ich werde Hilfe brauchen, bis ich genügend zusammen habe, um sie nach Sturmwind zu schicken.", completion = "Vielen Dank für diese Samenkörner. Ich habe schon fast genügend zusammen, um eine erste Ladung zurückzuschicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[9993] = { id = 9993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olembaöl", description = "Die öligen Samen der Olembabäume könnten sich als sehr wertvoll erweisen. Ich würde gern eine größere Menge davon sammeln und schauen, was ich daraus machen kann.\n\nStellt Euch nur vor, da steht ein ganzer Wald mit Bäumen, die so viele Samen produzieren, die alle ungenutzt bleiben. Mir ist egal, ob ich nur Salatöl, Waffenöl oder Lampenöl daraus herstellen kann, ich werde ihre Verschwendung nicht dulden!\n\nBringt mir alle Samen, die Ihr von den Olembazapfen sammeln könnt. Sie liegen hier überall.", sourceObjective = "Bringt 30 Olembasamenkörner zu Rakoria in der Steinbrecherfeste.", progress = "Habt Ihr ein paar Samenkörner für mich?", completion = "Das ist ein guter Anfang, aber wir werden noch mehr davon brauchen, wenn wir eine angemessene Menge Öl herstellen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[9994] = { id = 9994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste im Südosten bringen. Vielleicht hat sie ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.\n\nJa, wie ich befürchtet habe. Ich glaube, das sind Bombenteile. Unsere Augen und Ohren in Shattrath haben uns informiert, dass einige Astrale verbotene Waren aus anderen Dimensionen, mit denen sie in Kontakt stehen, einführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9995] = { id = 9995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das?", description = "Ich weiß nicht, wie es Euch geht, aber ich habe keine Ahnung, was das ist. Ich weiß nur eins: sie sehen gefährlich aus!\n\n{name}, ich glaube, Ihr solltet diesen Kasten mit Ersatzteilen zu Tooki in die Steinbrecherfeste im Südosten bringen. Vielleicht hat er ja eine Ahnung, was das ist.", sourceObjective = "Bringt den Kasten mit Ersatzteilen zu Tooki in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Ihr seht besorgt aus. Was ist los, {class}?", completion = "Oh nein! Das sind furchtbare Nachrichten! Ich kann nicht glauben, dass alle bis auf zwei unserer Cenariusfreunde tot sind!\n\nIn Ordnung, lasst mich die Teile einmal anschauen. Ich hoffe nur, dass sie nicht das sind, was ich vermute.", sourceObjectiveStatus = "unverified-source-field" }
quests[9996] = { id = 9996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Norden und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Leutnant Meridian bei Allerias Posten in den Wäldern von Terokkar zurück.", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9997] = { id = 9997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Posten der Feuerschwingen", description = "Wir wissen, dass die Blutelfen der Feuerschwingen für Illidan arbeiten. Und nach dem, was Ihr mir erzählt habt, benutzen sie die Zerschlagenen von Tuurem als Schmuggler, um eine furchtbare Waffe herzustellen.\n\nWas immer sie vorhaben mögen, das Beste, was wir nun tun können, ist, sie zu dezimieren.\n\nDie Blutelfen der Feuerschwingen müssen vernichtet werden! Begebt Euch zum Posten der Feuerschwingen im Nordosten und kümmert Euch darum!", sourceObjective = "Tötet 10 Verteidiger der Feuerschwingen, 10 Blutwärter der Feuerschwingen und 10 Hexenmeister der Feuerschwingen. Meldet Euch dann bei Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar zurück.", progress = "Berichtet. Was bringt Ihr Neues vom Posten der Feuerschwingen?", completion = "Das ist ein guter Anfang, aber nach dem, was Ihr auf dem Hof beobachtet habt und was mir meine Agenten berichten, haben wir weitaus dringendere Dinge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[9998] = { id = 9998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerspenstige Nachbarn", description = "Thander ist über die Ankunft der Höllenorcs bei den Ruinen vor Kurzem sowohl überrascht als auch besorgt. Sie haben keine Zeit verschwendet und sofort begonnen, Befestigungsanlagen zu bauen und die Gebäude zu reparieren.\n\nDie Bauarbeiten laufen Tag und Nacht, {name}. Ich habe ein paar meiner zuverlässigsten Agenten losgeschickt, um die Situation zu überwachen, aber wir können uns keine Verzögerungen leisten. Geht gegen ihre Arbeiter vor und sucht dann nach Theloria Dämmermantel bei Allerias Posten nördlich der Ruinen der Knochenmalmer. Sie wird Euch weitere Anweisungen geben.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Theloria Dämmermantel bei Allerias Posten.", completion = "<Die Hochelfe nickt.>\n\nEs ist ein guter Anfang, aber Bertelm hatte Recht, Euch zu mir zu schicken. Ich habe eine Entdeckung gemacht, die die Anwesenheit der Höllenorcs hier erklären könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[9999] = { id = 9999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel auf Zeit", description = "Solange die Transporter noch stehen, ist nichts, was wir gegen die Konstruktionslager unternehmen, von Dauer. Wir müssen einen Weg finden, die Gebäude der Legion zu zerstören.\n\nIch brauche Zeit, um einen Angriffsplan auszuarbeiten. Wenn Ihr die Ingenieure und Tüftler eine Weile beschäftigen könntet, würde das ihre Fortschritte verlangsamen, und ich hätte die Zeit, die ich benötige.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo'arg und 8 Tüftler der Gan'arg tötet.", completion = "Wie ich es mir dachte. Es gibt keinen normalen Weg, Teufelsstahl zu zerstören. Es ist aber noch nicht alles verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[10000] = { id = 10000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unangenehme Gesellschaft", description = "Unsere Streitkräfte in Thrallmar dachten, sie hätten die Höllenorcs der Höllenfeuerzitadelle unter Kontrolle, aber die Neuankömmlinge in den Ruinen im Osten sagen etwas anderes.\n\nWir können ihnen nicht erlauben, hier Fuß zu fassen. Rokag hat Schattenpirscher Kaide zu den Ruinen geschickt, um sie zu beobachten, aber wir müssen sie aufhalten, bevor sie es sich zu bequem machen.\n\nGeht zu den Ruinen, dezimiert ihre Peons und haltet bei den Bäumen im Norden nach Kaide Ausschau. Er wird Euch sagen, wo Ihr danach hingehen sollt.", sourceObjective = "Tötet 12 verunstaltete Peons und meldet Euch dann bei Schattenpirscher Kaide.", progress = "Ich wollte gerade einen Bericht zu Rokag schicken und einen Angriff vorschlagen, aber wie ich sehe ist das nicht mehr nötig.", completion = "Um die Höllenorcs aufzuhalten müssen wir schon mehr tun, als ihre Arbeiter zu töten. Ich habe eine Entdeckung gemacht, die vielleicht erklären kann, warum sie hier sind, und die mich in meiner Überzeugung bestätigt, dass wir schnell handeln müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10001] = { id = 10001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterplaner", description = "Alle Konstruktionslager haben einen Meisterplaner. Der Meisterplaner bestimmt, welche Gebäude im Konstruktionslager vorhanden sein müssen, und wie sie platziert werden. Zudem werden diese Informationen auf Blaupausen festgehalten, die der Planer bei sich trägt.\n\nWir brauchen die Blaupausen des Meisterplaners. Mit solch detaillierten Informationen könnten wir einen meiner Bekannten dazu bewegen, uns etwas Unterstützung zu schicken.\n\nSucht den Meisterplaner der Mo'arg und stehlt seine Blaupausen. Er wird sich hinter den Konstruktionen aufhalten.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt.", progress = "Bleibt auf jeden Fall von den Vorarbeitern fern. Sie dürfen nichts von Eurer Anwesenheit mitbekommen. Die Folgen könnten verheerend sein!", completion = "Mein Bekannter kennt hoffentlich einen Weg, die Lager zu zerstören. Er war schließlich mal ein Ingenieur der Legion...", sourceObjectiveStatus = "unverified-source-field" }
quests[10002] = { id = 10002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Theloria Dämmermantel zurück.", completion = "<Theloria nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[10003] = { id = 10003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermittler der Feuerschwingen", description = "In den letzten paar Tagen habe ich beobachtet, wie eine Blutelfenfrau immer wieder zur Höllenorcfeste gegangen ist, um mit dem Anführer der Höllenorcs zu reden. Ihrer Körpersprache nach verteilt sie Befehle. Aber warum? Wessen Befehle überbringt sie?\n\nDie Neugier hat über mich gesiegt, deshalb habe ich sie auf dem Weg zurück vom Höllenorclager beschattet. Sie ging nach Norden, zum Posten der Feuerschwingen. Ich musste mich zurückziehen, bevor ich den Blutelfenposten erreichte.\n\nTötet sie, bevor sie das Höllenorclager wieder verlassen kann.", sourceObjective = "Findet und tötet Lisaile Feuerweber und kehrt dann zu Schattenpirscher Kaide zurück.", completion = "<Kaide nickt Euch zu.>\n\nGut gemacht. Dadurch haben wir uns ein wenig Zeit verschafft. Die Blutelfen werden sich fragen, was ihrer Freundin zugestoßen ist. Hoffentlich wissen wir bis dahin mehr über ihre Pläne.\n\nWenn die Zeit gekommen ist, werde ich Rokag von unseren Fortschritten berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10004] = { id = 10004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld und Verständnis", description = "Nehmt die Blaupausen und reist nach Shattrath in den Wäldern von Terokkar. Wenn Ihr in Shattrath seid, geht ins Untere Viertel sucht nach einem Mo'arg namens Sal'salabim. Er ist wahrscheinlich an der Bar und ertränkt seine Sorgen.\n\nDa fällt mir ein, dass Ihr ihn wahrscheinlich überreden müsst, uns zu helfen. Versucht ihm viel Geduld und Verständnis entgegenzubringen. Wenn das nichts hilft, dann versucht es mit Gewalt.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal'salabim in Shattrath bringt und ihn überredet, euch zu helfen.", progress = "<Sal'salabim kratzt sich am Kopf.>\n\n[Dämonisch] Ik il romath sardon.", completion = "Beruhigt Euch, Schätzchen, Sal'salabim wird helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10005] = { id = 10005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10006] = { id = 10006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbinder Tavgren Bescheid sagen", description = "{name}, ich glaube, Ihr solltet zum Cenariusdickicht zurückgehen und mit Erdbinder Tavgren sprechen.\n\nIch bin mir sicher, dass er wissen möchte, was hier wirklich passiert ist.", sourceObjective = "Sprecht mit Erdbinder Tavgren außerhalb des Cenariusdickichts in den Wäldern von Terokkar.", completion = "Eine Bombe aus reinem Mana, die ganze Städte auslöschen kann! Aber warum? Warum würden die Blutelfen so etwas bauen und gegen uns verwenden? Das Cenariusdickicht sollte ein Ort des Friedens und der Erholung sein.\n\nWas auch immer der Grund sein mag, ich bin sicher, dass Aufseher Baumlas ihn kennt, doch ich habe keine Ahnung, wie ich ihn heilen kann. Vielleicht heilt sein Geist mit der Zeit von alleine?\n\nWie auch immer, ich danke Euch für Eure Hilfe. Ich kann nur hoffen, dass diese Tragödie sich niemals wiederholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10007] = { id = 10007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "So wie ich Thander und Bertelm kenne, werden sie nicht dulden, dass eine feindliche Macht so ein großes Lager direkt vor unserer Haustüre errichtet. Aber sie zu bitten, ein paar Leute ihrer Garnison zu schicken, um das Lager anzugreifen, steht auch nicht zur Debatte. Wir wären dann viel zu leicht angreifbar.\n\nWir müssen uns also selbst darum kümmern, die Bedrohung durch die Bauarbeiten der Höllenorcs zu verringern. Tötet alle von ihnen, die Ihr könnt, und ich sehe mich solange nach Verstärkung um.", sourceObjective = "Tötet 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer und kehrt dann zu Theloria Dämmermantel zurück.", completion = "Langsam sehen die Dinge besser aus. Wenn wir die Höllenorcs daran hindern können, ihre Kumpel hier zu unterstützen, können wir den Posten unter Kontrolle halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10008] = { id = 10008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was in Terokkar geschieht, bleibt in Terokkar", description = "Wenn Thrallmar erfährt, dass sie es nicht geschafft haben, die Höllenorcs unter Kontrolle zu halten, werden wir hier bald viel Gesellschaft haben. Ehrlich gesagt bin ich mir nicht sicher, ob ich so viel Aufmerksamkeit möchte, deswegen behalten wir dieses kleine Problem für uns, verstanden?\n\nWenn wir den Höllenorcs genug Verluste beibringen können, besteht die Möglichkeit, dass niemand außerhalb der Steinbrecherfeste von ihrer Anwesenheit erfährt.\n\nMarschiert da rein, schwingt Eure Waffe, wedelt mit der Hand - oder was auch immer Ihr tut - und tötet die Höllenorcs!", sourceObjective = "Schattenpirscher Kaide möchte, dass Ihr 10 Verwüster der Knochenmalmer und 6 Kreuzbrecher der Knochenmalmer tötet.", progress = "Bitte sagt mir, dass ich nicht den Falschen auf diese Mission geschickt habe...", completion = "Ich weiß, dass Ihr schon weit gereist seid, {name}, aber manche Geschichten sollten das Land niemals verlassen, haben wir uns verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10009] = { id = 10009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schädel spalten", description = "<Sal'salabim lacht.>\n\nDas Sal'salabims Entwurf.\n\n<Sal'salabim zeigt auf die Architektur und die Anordnungen auf den Blaupausen.>\n\nSchaut Türme an. Dämonenjäger kann nicht sehen, oder? Armer, armer Altruis. Er weinen wenn er Augen hätte, oder?\n\nJa, Sal'salabim helfen, aber erst Ihr helfen Sal'salabim.\n\n<Sal'salabim gibt Euch einen Ordner.>\n\nDiese Wesen schulden Sal'salabim Gold. Viel Gold. Gehen für Sal'salabim eintreiben. Sie werden nicht einfach rausrücken Sal'salabims Gold. Müssen kämpfen, aber Ihr stark. Ihr besiegen Sal'salabim!", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch'kuschs Schulden und Floons Schulden eintreibt.", progress = "Ihr ja nicht kommen zurück ohne Sal'salabims Gold!", completion = "Nun, Geschäft sein Geschäft, aber wenn Sal'salabim Euch sagen, Ihr nicht böse werden, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[10010] = { id = 10010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So einfach ist das?", description = "<Sal'salabim zeigt auf die Blaupause.>\n\nSeht Ihr, wo Teufelskanonen sind?\n\n<Sal'salabim zeichnet einen Pfeil, der einen Richtungswechsel anzeigt.>\n\nIhr dreht Teufelskanone um und richtet sie auf Gebäude.\n\nWartet! Nicht durchdrehen! Ihr wisst etwas nicht. Vorarbeiter haben Schlüssel, um Kanonen zu drehen. Ihr braucht erst Schlüssel! Einer von jedem Vorarbeiter!\n\nNicht so leicht, was?\n\nBringt Information zurück zu Altruis.", sourceObjective = "Sal'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt.", completion = "Natürlich! Wir werden sie mit ihren eigenen Waffen schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10011] = { id = 10011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: zerstört", description = "Sammelt Euren Mut, {name}. Ihr werdet ihn brauchen, wenn Ihr einem Vorarbeiter gegenübersteht.\n\nSobald Ihr bereit seid, sucht und tötet die Vorarbeiter in jedem Lager. Nehmt ihre Schlüssel und benutzt sie, um die Kanonen umzudrehen. Schießt damit auf die Lager. Kehrt zu mir zurück, wenn die Lager zerstört sind.", sourceObjective = "Altruis der Leidende im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört.", progress = "Schon fertig?", completion = "Wir haben gesiegt! Das Vorrücken der Legion wurde gebremst!\n\nIch biete Euch eine Auswahl an Belohnungen für Eure heldenhaften Taten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10012] = { id = 10012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenorcpläne", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Bertelm mehr über dieses merkwürdige Bündnis. Ihr beschließt, zu Allerias Feste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Bertelm in Allerias Feste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Bertelm nimmt die Pläne und schaut sie an.>\n\nWenn Ihr mir diese Pläne nicht gebracht hättet, hätte ich behauptet, dass Ihr irre seid, aber hier steht es ganz deutlich. Die Höllenorcs sind nicht nur hier, um den Blutelfen zu dienen, sie haben sogar den Auftrag, uns abzulenken.\n\nDiese Pläne werfen mehr Fragen auf, als sie beantworten, aber nun können wir uns besser vorstellen, womit wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10013] = { id = 10013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungesehene Hand", description = "Die Schrift auf diesen Plänen ist zu fein und genau, um von einem Höllenorc zu stammen. Ihr könnt nicht verstehen, was der Text bedeutet, aber die Zeichen sind eindeutig: die Höllenorcs erhalten Befehle von den Blutelfen im Posten der Feuerschwingen.\n\nWarum arbeiten die beiden Fraktionen zusammen? Vielleicht weiß Rokag mehr über dieses merkwürdige Bündnis. Ihr beschließt, zur Steinbrecherfeste zurückzukehren und ihm die Pläne zu zeigen.", sourceObjective = "Bringt die Höllenorcpläne zu Rokag in der Steinbrecherfeste in den Wäldern von Terokkar.", progress = "Was habt Ihr da, {name}?", completion = "<Rokag nimmt die Pläne und schaut sie an.>\n\nKaide hatte also Recht! Diese Höllenorcs führen etwas im Schilde. Ich hätte jedoch nie gedacht, dass sie mit den Blutelfen zusammenarbeiten.\n\nLaut diesen Plänen sollen die Höllenorcs uns beschäftigen... aber warum? Das sind beunruhigende Nachrichten, {name}. Gut, dass Ihr mir die Pläne gleich gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10014] = { id = 10014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen Allerias Feste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Meridian in Allerias Posten in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10015] = { id = 10015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Projekt des Postens der Feuerschwingen", description = "Wie ich bereits erwähnt habe, haben wir einige weitere Informationen erhalten, die besagen, dass wir ein weitaus größeres Problem haben.\n\nDie Blutelfen sind im Posten der Feuerschwingen mit dem Bau einer weiteren Manabombe beschäftigt. Ich kann nicht genug betonen, dass sie eindeutig vorhaben, diese Bombe gegen die Steinbrecherfeste einzusetzen!\n\nMeine Späher berichten mir, dass sie die Codes für die Waffe in vier kleineren Gebäuden um den mittleren Hof herum aufbewahren. Geht dorthin und besorgt die Codes, bevor es zu spät ist!", sourceObjective = "Stehlt die vier Codetabellen der Manabombe und bringt sie zu Unteroffizier Chawni im Steinbrecherlager in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10016] = { id = 10016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldworgschwänze", description = "Seid Ihr auf Euren Reisen den Waldworgs begegnet? Ich hatte die Gelegenheit, sie zu beobachten, als ich einige der nördlichen Regionen des Waldes kartografiert habe. Ich würde Euch nicht empfehlen, zu nahe an sie heranzugehen, es sei denn, Ihr seid bereit für einen Kampf.\n\nSie haben keine Angst und scheuen vor nichts zurück, um ihr Territorium zu verteidigen.\n\nEs ist nicht verwunderlich, dass diese Kreaturen solch wundervolle Schwänze haben. Ich habe versucht, ein paar von ihnen zu sammeln, um einen neuen Mantel zu schneidern, aber die Worgs entkommen meinen Fallen dauernd. Wollt Ihr mir helfen?", sourceObjective = "Bertelm in Allerias Feste möchte, dass Ihr ihm 12 Waldworgschwänze bringt. Die Schwänze können von Waldworgs oder Waldworgalphas stammen.", progress = "Wie ich sehe habt Ihr die Gefahren des Waldes überlebt. Habt Ihr ein paar Schwänze für meinen Umhang?", completion = "Ah, gut gemacht, Freund. Sie sind noch feiner, als ich gedacht habe. Sie werden sicher einen schönen Umhang abgeben.\n\n<Bertelm schaut zum Gasthaus hinüber.>\n\nJa, das wird ein schöner Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10017] = { id = 10017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Vorräte", description = "Immer mehr Flüchtlinge kommen Tag für Tag durch die Tore von Shattrath. Viele sind so schwer verwundet, dass es an ein Wunder grenzt, dass sie es überhaupt hierher geschafft haben.\n\nAls Heiler der Aldor kann ich die meisten gewöhnlichen Wunden verarzten. Vergiftete Wunden sind jedoch problematischer, da mir langsam die Vorräte an Gegengift ausgehen.\n\nBringt mir ein paar Schreckensgiftbeutel von den Schreckensspinnen hier in der Gegend, damit ich mehr davon herstellen kann. Ihr findet eine Gruppe von diesen Spinnen im Südosten von Terokkar.", sourceObjective = "Bringt 8 Schreckensgiftbeutel zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Giftbeutel, {name}? Diese Flüchtlinge können nicht mehr lange warten.", completion = "Ihr habt meinen Dank, {name}. Die Aldor werden von Euren Taten erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10018] = { id = 10018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Wolfgeistes", description = "Vor Generationen, als die Orcs die Wälder von Terokkar noch ihr Zuhause nannten, spielte der Wolfgeist eine große Rolle in ihrem Leben. Als die Orcs fortgingen, brauchten sie den Wolfgeist nicht mehr und haben ihn zurückgelassen.\n\nMit der Zeit wurde der Geist einsam und verließ die Wälder ebenfalls.\n\nIch glaube, dass ich den Wolfgeist zu seinem ursprünglichen Heim zurückbringen kann, wie auch wir Orcs zurückgekehrt sind. Das Ritual erfordert, dass ich ein Gewand aus den Pelzen der Wölfe der Wälder schneidere, um den Wolfgeist zu seinem Zuhause zurück zu geleiten.", sourceObjective = "Bringt 12 Waldworgpelze zu Malukaz in der Steinbrecherfeste.", progress = "Konntet Ihr alle Pelze, die ich benötige, finden?", completion = "Die Pelze sind perfekt, {name}! Ich hätte keine besseren bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10019] = { id = 10019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Giftbeutel", progress = "Viele Flüchtlinge brauchen immer noch Heilung für ihre vergifteten Wunden. Habt Ihr mir noch mehr Giftbeutel gebracht, {name}?", completion = "Ihr habt meinen Dank, {name}. Die Naaru haben diese unglücklichen Seelen unter ihren Schutz gestellt. Es wäre sehr schade, wenn sie es bis Shattrath geschafft hätten, um dort an ihren Wunden zu verenden." }
quests[10020] = { id = 10020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heilmittel für Zahlia", description = "Die Frau rechts von mir hat eine schwere Kopfverletzung erlitten. Sie hat zwar überlebt, aber ihr Augenlicht verloren.\n\nEin traditionelles Heilmittel meines Volkes verlangt das Blut eines sehr alten Basilisken.\n\nUnglücklicherweise leben die Basilisken von Terokkar wegen der Wilderei verschiedener Lager in der Regel nicht sehr lange.\n\nEs gibt jedoch einen Basilisken, dessen Name ich schon als Kind kannte. Er ist als Steinstarrer bekannt und soll östlich von hier leben, in der Nähe der Landesgrenze.\n\nBringt mir sein Blut, damit Zahlia wieder sehen kann.", sourceObjective = "Bringt Steinstarrers Blut zu Sha'nir in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr das Blut bekommen, {name}? Ohne das Blut wird Zahlia ihrem Sohn nie wieder in die Augen schauen können.", completion = "Vielen Dank, {name}. Sich um die Notleidenden zu kümmern ist eine schwierige Aufgabe, aber sie wird auf ihre ganz eigene Weise belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10021] = { id = 10021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht wiederherstellen", description = "Vor langer Zeit war ein Großteil dieses Gebiets von den Draenei bewohnt. Wir, die Aldor, hatten den Auftrag, unsere heiligen Stätten und Altäre zu beschützen. Doch seitdem wurden viele davon zerstört oder von unseren Feinden eingenommen.\n\nÖstlich von hier gibt es einen Außenposten der Arakkoa. Sie haben ihn mit voller Absicht auf dem Gebiet errichtet, auf dem drei unserer heiligen Altäre stehen. Die Arakkoa haben ihre üble Magie benutzt, um die ureigene Macht unserer Schreine zu verändern und zu schänden.\n\nBringt dies zum Arakkoaaußenposten und reinigt die drei Altäre.", sourceObjective = "Ishanah möchte, dass Ihr zum Arakkoaaußenposten östlich von Shattrath geht. Benutzt die gesegnete Phiole, um den östlichen Altar, den westlichen Altar und den nördlichen Altar zu reinigen.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr habt meinen Dank, {name}. Wir sind die Hüter des Lichts und können unsere Pflichten nicht vernachlässigen. Nicht einmal in den schwersten Zeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10022] = { id = 10022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwer zu fassende Eisenkiefer", description = "Jetzt, da ich das Fell habe, das ich für mein Gewand benötige, dachte ich, dass der Pelz eines ganz bestimmten Wolfs eine schöne Kapuze für meinen Umhang abgeben würde. Stellt Euch nur vor, wie es wäre, Euren Feind im Pelz des gerissensten Raubtiers der Wälder zu sehen!\n\nIch habe bisher vergeblich versucht, Eisenkiefer zu fangen. Ich habe versucht ihn in die Enge zu treiben, ihn zu überlisten und ihn zu locken. Nichts hat geklappt.\n\nEr streunt in den nordöstlichen Gebieten des Waldes herum, und ich würde Euch angemessen belohnen, wenn Ihr schafft, was mir nie gelang.", sourceObjective = "Bringt Eisenkiefers Pelz zu Bertelm in Allerias Feste.", progress = "Hat der alte Eisenkiefer Euch übers Ohr gehauen? Oder konntet Ihr den alten Gesellen überlisten?", completion = "Ich verneige mich vor Eurem Geschick, {name}. Ihr habt Euch als herausragender Jäger bewiesen.\n\nIch werde Eure Hilfe bei der Herstellung dieses Umhangs nie vergessen. Er ist ein einzigartiges Gewand, das ich voller Stolz tragen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10023] = { id = 10023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patriarch Eisenkiefer", description = "Ihr habt gute Arbeit beim Sammeln der ersten Pelze geleistet.\n\nDas letzte Stück der Gewandung erfordert einen ganz besonderen Pelz. Es gibt einen bestimmten Wolf, der alt und gerissen ist, und sich dadurch den Rang des Patriarchen unter den Wölfen des Waldes verdient hat. Er ist unter ihnen als Eisenkiefer, der mächtige Jäger, bekannt.\n\nIn meinen Visionen habe ich ihn im Nordosten der Wälder umherstreifen sehen. Sein Pelz in meiner Gewandung wird sicher den Pfad des Wolfgeistes erhellen.\n\nBeklagt Eisenkiefer nicht. Er wird die ihm gebührende Ehre erhalten.", sourceObjective = "Bringt Eisenkiefers Pelz zu Malukaz in der Steinbrecherfeste.", progress = "Der Geist wartet, {name}. Habt Ihr den Pelz des Patriarchen?", completion = "Der Pelz ist noch vortrefflicher, als ich erhofft hatte! Das ist ein gutes Zeichen, {name}, und die Geister werden Euch wegen Eurem Beitrag zu dieser Zeremonie wohl gesonnen sein.\n\nIch habe Euch aus dem übrigen Pelz einen Helm gemacht, {name}. Er zeichnet Euch als mächtigen Jäger und Verbündeter des großen Wolfgeists der Wälder von Terokkar aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10024] = { id = 10024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voren'thals Visionen", description = "Unser Anführer, Voren'thal der Seher, war einst ein enger Vertrauter von Kael'thas. Seine prophetischen Visionen habe ihn gewarnt, dass Kaels Weg in der Zerstörung unseres Volkes enden würde.\n\nNormalerweise sind diese Visionen nur sehr vage und ungenau, aber unsere Alchemisten haben ein Elixier entwickelt, mit dessen Hilfe seine Visionen deutlicher werden. Unglücklicherweise erfordert das Elixier eine sehr seltene Zutat: Basiliskenaugen. Normalerweise bekomme ich sie von diesem aufgeblasenen Astralen, aber er hat mich enttäuscht.\n\nMacht Euch auf die Suche nach den Dunstschuppenbasilisken im gebirgigen Terokkar und bringt mir ihre Augen.", sourceObjective = "Bringt 8 Augen eines Dunstschuppenbasilisken zu Arkanistin Adyria in Shattrath.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Basiliskenaugen für Voren'thals Elixier?", completion = "Sie sind in tadellosem Zustand, {name}. Macht weiter so, und die Seher werden bald zu Euren Freunden zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10025] = { id = 10025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Basiliskenaugen", progress = "Um auch nur eine kleine Dosis von Voren'thals Elixier herzustellen, braucht man sehr viele Basiliskenaugen. Wenn Ihr mir mehr davon bringt, gewinnt Ihr sicher das Wohlwollen der Seher.", completion = "Ich danke Euch, {name}. Voren'thals Visionen können vielleicht eines Tages das Schicksal unseres Volks entscheiden. Wir tun gut daran, dafür zu sorgen, dass seine Visionen so klar wie möglich sind." }
quests[10026] = { id = 10026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es ist mir ein wenig peinlich, aber mir ist hier in den Wäldern von Terokkar etwas widerfahren, was mir seit meinen Lehrjahren nicht mehr passiert ist.\n\nManchmal scheitern meine Zauber, obwohl ich genau weiß, dass ich alles richtig gemacht habe. Ich bin fast wahnsinnig geworden, als das zum ersten Mal passiert ist.\n\nIch glaube, ich habe den Grund dafür gefunden. Die Wälder sind voller Wesen, die Sphärenjäger genannt werden. Das sind dämonische Kreaturen mit einem Hang zur Magie und zur Störung magischer Ströme. Der beste Weg, um mit ihnen fertig zu werden, ist, sie einfach zu töten.", sourceObjective = "Andarl in Allerias Feste möchte, dass Ihr 10 Sphärenjäger tötet.", completion = "<Andarl wischt sich die Stirn mit dem Ärmel seiner Robe ab.>\n\nZum Glück. Ich habe schon befürchtet, dass die Biester die restlichen Waldbewohner vertrieben haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10027] = { id = 10027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Störungen", description = "Es gibt nichts Ärgerlicheres, als einen Zauber vorzubereiten, und dann von einer unsichtbaren Macht unterbrochen zu werden. Nach dem vierten Mal wusste ich, dass es kein Zufall sein konnte, und habe Keb'ezil losgeschickt, um die Ursache herauszufinden.\n\nIch garantiere Euch, dass Ihr nie einen Wichtel treffen werdet, der widerspenstiger ist als Keb.\n\nWie auch immer, er konnte die Quelle des Problems finden, eine verteufelte Kreatur namens Sphärenjäger. Sie haben die Angewohnheit, überall, wo sie auftauchen, die magischen Energien zu stören. Ich habe genug von ihren Störungen.", sourceObjective = "Tötet 10 Sphärenjäger und kehrt dann zu Kurgatok in der Steinbrecherfeste zurück.", completion = "Keb'ezil ist sehr erleichtert, dass Ihr Euch um das kleine Problem gekümmert habt, nicht wahr Keb?\n\n<Der Wichtel ignoriert seinen Meister und scheint beleidigt zu sein.>\n\nIhr müsst ihm seine schlechten Manieren nachsehen. Ihr wisst ja, wie Dämonen sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[10028] = { id = 10028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefäße der Macht", description = "Zwischen den Ruinen von Tuurem gibt es einige Gefäße mit roher, magischer Energie. Wir können von Glück sagen, dass die Zerschlagenen, die in der Stadt eingefallen sind, keine Ahnung von dieser Machtquelle mitten unter ihnen haben, aber wir dürfen nicht hoffen, dass das so bleibt.\n\nMithilfe dieser Gefäße und ihrer Macht können die verstreuten Überlebenden meines Volkes der Verlockung der dämonischen Magie widerstehen. Jeder Quel'dorei, den wir vor dem Wahnsinn unseres Prinzen retten können, ist einer mehr, der uns beim Wiederaufbau unseres verlorenen Ruhms helfen kann. Bringt mir die Gefäße, {class}.", sourceObjective = "Bringt 8 Draeneigefäße zu Ros'eleth in Allerias Feste.", progress = "Konntet Ihr ein paar unbeschädigte Gefäße finden?", completion = "Ich hoffe, dass dies nicht die einzigen Gefäße in der Stadt sind. Es ist ein guter Anfang, aber ich schätze, wir werden noch viel mehr davon brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10029] = { id = 10029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister rufen", description = "Die Geister der Toten in der Knochenwüste rufen nach mir! Sie leiden!\n\n{class}, Ihr müsst zur Knochenwüste im Süden reisen und meinen Gehilfen Soolaveen bei der Flüchtlingskarawane aufsuchen. Er muss es auch spüren und wird Eure Hilfe dabei brauchen, die Geister dort zur Ruhe zu bringen.\n\nWenn Ihr Euch beeilt, könnt Ihr sie vielleicht noch einholen. Ich weiß, dass sie in Norden der Knochenwüste Rast machen wollten, bevor sie weiter Richtung Süden nach Auchindoun ziehen wollten.", sourceObjective = "Anachoret Lyteera möchte, dass Ihr ihren Gehilfen Soolaveen bei der Flüchtlingskarawane in der Knochenwüste der Wälder von Terokkar findet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[10030] = { id = 10030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen zurückholen", description = "Die Knochen der Draenei, die bei der Explosion von Auchindoun gestorben sind, sind überall in der Knochenwüste verstreut. Viele ihrer Geister sind daher ruhelos und können nicht ins nächste Leben übertreten.\n\n{name}, Ihr müsst mir helfen, ihre Knochen wieder zu besorgen und sie zu ihrer letzten Ruhestätte zu bringen. Nur dann werden sie Frieden finden und den Segen des Lichts erlangen.\n\nSammelt die ruhelosen Knochen mit größter Vorsicht und bringt sie zu Ramdor dem Wahnsinnigen in Auchindoun in der Mitte der Knochenwüste. Trotz seines Namens wird er wissen, wie er sich um sie zu kümmern hat.", sourceObjective = "Sammelt 10 ruhelose Knochen und bringt sie zu Ramdor dem Wahnsinnigen bei der westlichen Seite des Rings der Beobachtung in Auchindoun, das sich in der Mitte der Knochenwüste in den Wäldern von Terokkar befindet.", progress = "Was ist das? Wer seid Ihr?", completion = "Super, genau das, was ich brauche... noch mehr Knochen.\n\n<Ramdor seufzt.>\n\nJa, ja, ich werde mich darum kümmern, dass die Gebeine dieser ehrenwerten Vorfahren ein anständiges Begräbnis bekommen, keine Sorge.\n\nWenn Ihr den Toten wirklich helfen wollt, habe ich noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10031] = { id = 10031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Verirrten den Weg zeigen", description = "Viele Geister der Draenei wurden von der Explosion in Auchindoun verderbt und wandeln nun voller Pein in der Wüste.\n\n{name}, ich flehe Euch an, gebt ihnen ihren Seelenfrieden wieder. Vernichtet die verirrten Geister und die Skelette der Zerschlagenen, die die Knochenwüste hinter den Mauern Auchindouns heimsuchen.\n\nWas? Ihr denkt, es wäre besser, sie in blinder Wut umherstreifen zu lassen?\n\nKehrt danach zu Anachoret Soolaveen bei der Flüchtlingskarawane zurück und berichtet ihm, was Ihr erreicht habt.", sourceObjective = "Tötet 10 verirrte Geister und 10 Skelette eines Zerschlagenen und kehrt dann zu Anachoret Soolaveen bei der Flüchtlingskarawane in der Knochenwüste in den Wäldern von Terokkar zurück.", completion = "Ihr habt getan, was nötig war. Auch wenn es mich traurig macht, dass die Geister meiner Vorfahren zu schrecklichen Untoten verwandelt wurden, hat Euer Handeln sie endlich zur Ruhe gebracht.\n\nVielen Dank, dass Ihr sie befreit habt, {name}. Bitte nehmt dieses bescheidene Zeichen meiner Hochachtung für Euch und Eure Selbstlosigkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte von Tuurem", description = "Ist Euch das Verhalten der Verirrten in Tuurem aufgefallen? Sie streifen in den Ruinen umher und suchen nach allen Überbleibseln der Draenei, die sie in die Finger bekommen können.\n\nIhre zerschlagenen Meister wissen es besser. Sie haben ihr früheres Leben abgestreift und sind zu etwas ganz anderem geworden.\n\nIch glaube, wir können die Gier der Verirrten ausnutzen und alte Draeneirelikte von ihnen sammeln. Warum sollten wir unser Leben im Kampf gegen die Zerschlagenen riskieren, wenn wir unsere Ziele weise auswählen können?", sourceObjective = "Sammelt 6 Artefakte von Tuurem von den Strauchdieben von Tuurem und den Jägern von Tuurem und bringt sie zu Rakoria in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf: Tötet die Knochenpeitscher!", description = "Es wurde ein Kopfgeld auf die Knochenpeitscher der Knochenwüste ausgesetzt. Als Überträger der Pest müssen sie von nun an vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nMeldet Euch bei Taela Immerlauf, um Eure Belohnung einzufordern.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar.", completion = "Ja, ich bin mir sicher, dass Ihr all die Knochenpeitscher getötet habt. Ist ja auch klar, weil der Hauptmann auf dem Anschlag einen Beweis gefordert hat.\n\n<Taela schaut Euch sarkastisch an.>\n\nIch nehme Euch beim Wort. Ich bin mir nicht sicher, wen ich so geärgert habe, dass ich zu diesem Dienst verdonnert wurde, aber vielen Dank für Eure Mühe für die Allianz. Hier habt Ihr eine Entschädigung für Euren Aufwand.", sourceObjectiveStatus = "unverified-source-field" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf: Tötet die Knochenpeitscher!", description = "Die Knochenpeitscher der Knochenwüste haben Mawg gebissen und ihn krank gemacht. Jetzt möchte er, dass sie alle vernichtet werden!\n\nObgleich sie in der gesamten Wüste vertreten sind, ist die größte Ansammlung bekanntermaßen beim Aashügel im Norden anzutreffen.\n\nKehrt zu Mawg Grimmschlag zurück, wenn Ihr die Aufgabe erledigt habt, und er wird Euch gut belohnen.", sourceObjective = "Tötet 20 Knochenpeitscher und meldet Euch dann bei Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Ihr müsst viele von diesen Knochenpeitschern getötet haben! Gut, ich hasse sie! Seit mich einer von ihnen gebissen hat, habe ich dauernd Ohnmachtsanfälle.\n\nWisst Ihr, wie peinlich das ist? Hier, nehmt dies als Dank, dass Ihr meine Rache vollstreckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "In der Knochenwüste gibt es ein Wesen, das so bösartig, so widerlich und so Furcht einflößend ist, dass nur die besten Jäger es wagen, ihm aufzulauern.\n\nIch spreche von Torgos, dem König der Knochenpeitscher, der sich beim Rhazeversteck am westlichen Ende der Weiten herumtreibt.\n\nUnglücklicherweise haben die Arakkoa eine Vogelscheuche aufgestellt, die als 'Torgos' Fluch' bekannt ist und ihn von dort fernhält. Ich wette, dass er trotzdem herauskommen würde, wenn Ihr den Leichnam seines Weibchens Trachela am Fuß dieser Vogelscheuche platziert. Ihr findet sie beim Aashügel im nördlichen Teil der Wüste.\n\nBringt mir eine Schwanzfeder von Torgos.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Taela Immerlauf in Allerias Feste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr die Feder? Muss ich Euch für Eure waghalsige Kühnheit belohnen?", completion = "Ich bin beeindruckt, {class}. Torgos war eines der hartgesottensten Wesen, das ich auf dieser Seite von Nagrand kenne.\n\nNun, ich denke, Ihr habt Euch etwas aus dem Schatz von Allerias Feste verdient. Sucht Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "Ich will Torgos, den König der Knochenpeitscher tot sehen!\n\nVor nicht allzu langer Zeit, als ich beim Rhazeversteck am westlichen Ende der Wüste auf Jagd war, fiel dieses Tier mich an.\n\n<Mawg tippt seine Augenklappe an.>\n\nEr hat mir mein Auge genommen, und nun will ich sein Leben dafür! Bringt mir eine seiner Schwanzfedern als Beweis und ich werde Euch gebührlich belohnen.\n\nIhr werdet den Leichnam seines Weibchens Trachela brauchen, um ihn hervorzulocken, da er Todesangst vor der alten Vogelscheuche der Arakkoa hat, die als Torgos' Fluch bekannt ist.\n\nIhr findet sie beim Aashügel im Norden der Wüste.", sourceObjective = "Benutzt Trachelas Leichnam, um Torgos zu rufen. Besorgt eine Schwanzfeder von Torgos und kehrt dann zu Mawg Grimmschlag in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", progress = "Habt Ihr ihn getötet? Ist Torgos tot?\n\nHabt Ihr den Beweis?", completion = "Ich danke Euch, {name}. Ihr habt meine Rache ausgeübt, und wie versprochen werde ich Euch belohnen.\n\nSucht Euch hiervon etwas aus und benutzt es weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich würd' lieber angeln", description = "Da wir gerade von Seen sprechen, da gibt es einen See im Nordosten, an dem man richtig toll angeln kann. Früher bin ich da immer mit meinen Freunden hin, aber meine Mutter erlaubt es mir nicht mehr.\n\nSie sagt, es sei zu gefährlich, aber ich habe da oben noch nichts außer ein paar Spinnen gesehen. Als ob Spinnen einem irgendwas anhaben könnten...\n\nIch mochte am liebsten die Aale von da oben. Wenn Ihr zum See hoch geht, könntet Ihr mir dann ein paar dieser Aale bringen? Sie sind störrisch, aber wenn man sie einmal gebändigt hat, kann man sie ganz leicht mitnehmen.", sourceObjective = "Bringt 8 makellose Schimmerschuppenaale zu Seth in Shattrath.", progress = "<Seth zieht Euch am Mantel.>\n\nHabt Ihr die Aale? Hä? Hä?", completion = "Danke! Ich kann mich nicht erinnern, wann ich das letzte Mal Aal gegessen habe.\n\nWie soll ich sie bloß kochen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Gefreiter Wöch", description = "Ich habe gerade einen Bericht von einem unserer Späher in der Nähe von Grangol'var erhalten. Er sagt, dass eine schattenhafte Truppe in die Ruinen dort eingezogen ist.\n\n{name}, ich möchte, dass Ihr mit Gefreiter Wöch sprecht und schaut, wie Ihr ihm dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht nach Westen an der Steinbrecherfeste vorbei. Sein letzter Bericht besagt, dass er sich in der Nähe des nördlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Gefreiter Wöch in der Nähe des nördlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Allerias Feste geschickt!\n\nBürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Späherin Neftis", description = "Ich wurde informiert, dass eine unserer Späherinnen in der Nähe von Grangol'var zurzeit eine schattenhafte Truppe beobachtet, die vor Kurzem dorthin gezogen ist.\n\n{name}, ich möchte, dass Ihr mit Späherin Neftis sprecht und schaut, wie Ihr ihr dabei helfen könnt herauszufinden, was diese Unbekannten dort im Schilde führen.\n\nGeht von hier aus nach Süden und dann nach Westen, um den Norden der Knochenwüste herum. Ihr letzter Bericht besagt, dass sie sich in der Nähe des südlichen Eingangs zum Dorf befindet.", sourceObjective = "Sprecht mit Späherin Neftis in der Nähe des südlichen Eingangs von Grangol'var in den Wäldern von Terokkar.", completion = "Es wird auch langsam Zeit, dass Ihr kommt. Ich habe diesen Bericht schon vor über einer Woche zur Steinbrecherfeste geschickt!\n\nBlutelfen und ihre Bürokratie!", sourceObjectiveStatus = "unverified-source-field" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Gefreiter Wöch in Grangol'var in den Wäldern von Terokkar zurück.", progress = "Habt Ihr schon mit ihnen gesprochen? Was hatten sie zu sagen?", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind sie?", description = "Ich weiß nicht, wer sie sind, aber ich weiß, dass sie uns feindlich gesonnen sind!\n\nIch werde Euch eine Verkleidung geben und möchte, dass Ihr da hinein geht und mit den Dreien sprecht, die ich für redselig halte. Sprecht mit dem Initiand, dem Hilfsarbeiter und dem Berater.\n\nSeid aber vorsichtig; es gibt dort ein paar Jäger, die Eure Verkleidung durchschauen können, und sie schauen ganz genau! Und was auch immer Ihr tut, verlasst das Dorf nicht. Die Verkleidung ist etwas dürftig. Wenn Ihr sie verliert, kommt zu mir zurück und ich gebe Euch eine neue.", sourceObjective = "Sprecht mit dem schattenhaften Initianden, dem schattenhaften Hilfsarbeiter und dem schattenhaften Berater. Kehrt dann zu Späherin Neftis in Grangol'var in den Wäldern von Terokkar zurück.", completion = "Gut, Ihr seid endlich zurück! Was habt Ihr herausgefunden? Wer sind sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Leutnant Kieshammer in Allerias Feste.\n\nViel Glück, {class}.", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Leutnant Kieshammer in Allerias Feste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Wöch zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, als Anerkennung für Eure Taten in Grangol'var erlaube ich Euch hiermit, Euch eine dieser wundervollen Belohungen auszusuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Schattenrat!", description = "Was? Diese Kerle gehören zum Schattenrat?!\n\n{name}, Ihr müsst dorthin zurückgehen und sie erledigen! Ich möchte, dass Ihr ihre Anführer und so viele Henker und Beschwörer tötet, wie Ihr nur könnt.\n\nWenn Ihr damit fertig seid, meldet Euch bei Beraterin Faila in der Steinbrecherfeste.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 schattenhafte Henker, 10 schattenhafte Beschwörer und Schattenmeister Gram und kehrt dann zu Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terokkar zurück.", completion = "Das sind schlechte Nachrichten! Aber ich habe die richtige Wahl getroffen, als ich Euch geschickt habe, um Neftis zu helfen. Das letzte, was wir brauchen können, ist, dass der Schattenrat einen starken Posten genau vor unserer Haustür errichtet.\n\n{name}, Ihr habt Euch etwas Nettes verdient. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei der Großmutter", description = "Die Großmutter hat mich gebeten, Euch aufzusuchen und Euch eine Nachricht zu überbringen. Sie möchte unverzüglich mit Euch sprechen.\n\nMein Wille mag vielleicht gebrochen sein, aber macht besser keinen Fehler, {name}. Wenn Ihr die Großmutter verärgert, werde ich Euch mit aller Kraft, die noch in mir steckt, bestrafen. Ihr findet sie in der Haupthalle.\n\n<Garrosh zeigt auf das große Gebäude im Norden.>\n\nHört Euch an, was sie zu sagen hat, und tut, was sie Euch aufträgt.", sourceObjective = "Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat.", progress = "Bitte setzt Euch, mein Kind.", completion = "Wir müssen zuerst Euren Geist erweitern, damit Ihr mit den Ahnen sprechen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten sammeln", description = "Mutter Kashur möchte mit Euch sprechen, {name}. Bevor Ihr das könnt, müsst Ihr jedoch ein paar Kräuter sammeln, um einen Trank zuzubereiten, der Euren Geist erweitert, damit Ihr mit den Geistern sprechen könnt.\n\nIhr müsst Olembawurzeln aus Terokkar, Marschenbeeren aus den Zangarmarschen, Telaarifarn aus Nagrand und Drachenwirbel aus dem Schergrat sammeln. Ich habe die Anleitung zum Anbau dieser Kräuter auf dieses Pergament geschrieben. Kehrt zu mir zurück, wenn Ihr die Zutaten beisammen habt.", sourceObjective = "Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt.", progress = "Hallo, Kind.", completion = "Ihr seid sehr geschickt, {name}. Unsere besten Kräutersammler hätten doppelt so lange gebraucht, um die Kräuter zu sammeln.\n\n\n\nHabt keine Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Vor zwei Wochen haben unsere Späher beobachtet, wie eine schwer bewaffnete Streitmacht der Allianz unter dem Kommando von Feldkommandeur Romus aus der Burg Nethergarde aufgebrochen ist. Mit so vielen Soldaten, Vorräten und einem so erfahrenen Kommandanten können sie nur ein Ziel haben: die Scherbenwelt.\n\nDer Kriegshäuptling hat eine Vorhut durch das Portal geschickt, aber wenn die Allianz glaubt, dass so viele Truppen von Nöten sind, sollten vielleicht auch wir Verstärkung schicken.\n\nReist durch das Dunkle Portal und meldet Euch bei Nazgrel in Thrallmar.", sourceObjective = "Reist durch das Dunkle Portal und sprecht mit Nazgrel in Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Ruhms", description = "Sie haben sie den Pfad des Ruhms genannt, eine Straße, die vom Herzen ihrer grausamen Festung zum Dunklen Portal führt, befestigt mit den Knochen meines Volks.\n\nEs war ihnen nicht genug, uns wie Tiere zu jagen, unsere Städte zu zerstören und die Überlebenden zu quälen. Nein, sie mussten auch noch unsere Knochen als Pflastersteine verwenden, und meinen Brüdern und Schwestern ein anständiges Begräbnis unter dem Licht verweigern.\n\nDiese gequälten Seelen wandeln immer noch durch diese Lande und schreien nach Erlösung. Ich bitte Euch, {name}, helft mir, sie beizusetzen.", sourceObjective = "Reinigt 8 zertrampelte Skelette auf dem Pfad des Ruhms mit dem Weihwasser der Draenei und kehrt dann zu Warpseher Kryv in der Ehrenfeste zurück.", progress = "Die Schreie scheinen irgendwie... schwächer geworden zu sein. Möge das Licht dafür sorgen, dass es nicht nur Wunschdenken ist.", completion = "Ihr habt meinen aufrichtigen Dank für Eure Mühen, {name}. Wenn auch noch viel zu tun ist, macht es mich froh, dass einige nun ihren wohlverdienten Frieden gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10048] = { id = 10048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Magiestaub", description = "Ich brauche Staub, aber nicht irgendeinen Staub.\n\nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Deirom finden.\n\nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.", sourceObjective = "Sammelt 7 Handvoll besänftigender Staub für Andarl in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10049] = { id = 10049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Magiestaub", description = "Ich brauche Staub, aber nicht irgendeinen Staub.\n\nDie königlichen Teromotten, die in den Wäldern in der Nähe leben, tragen magischen Staub auf ihren Flügeln, mit dem sie ihre Jäger betäuben. Diese Eigenschaft könnte ich mir zunutze machen. Die Arakkoaaugen, die Ihr mir gebracht habt, sind sehr widerspenstig. Mithilfe des Staubs werde ich diesen Widerstand lähmen. So kann ich dann endlich Dugar finden.\n\nIch brauche nicht viel davon, vielleicht ein halbes Dutzend oder so.", sourceObjective = "Sammelt 7 Handvoll besänftigenden Staubs für Kurgatok in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerschütterliche Seelen", description = "Am Ende unserer Invasion wurde das Rüstlager im Süden von den heimtückischen Todesrittern der Horde angegriffen. Diese bösartigen Schemen haben die Verteidiger des Rüstlagers verflucht und ihre Seelen zwischen dem Reich der Lebenden und dem der Toten gefangen.\n\nDiese ehrwürdigen Seelen müssen befreit werden! Ich bitte Euch, {name}, beendet das Leid meiner Kameraden, denn ich bringe es nicht selbst übers Herz, sie zu töten.", sourceObjective = "Ehrenwache Wesilow möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberer und 5 unerschütterliche Ritter beim Expeditionsrüstlager tötet.", completion = "Die Söhne sind Euch für Eure Mühen dankbar, auch wenn nur wenige über das Rüstlager sprechen möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit von Allerias Feste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Hauptmann Auric Sonnenjäger in Allerias Feste in den Wäldern von Terokkar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist. Garstige Blutelfen!\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Allerias Feste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch aus dem Posten der Feuerschwingen!", description = "Was für ein Glück, dass Ihr hier seid!\n\n{class}, Ihr müsst mir helfen zu entkommen. Ich habe Informationen, die für die Sicherheit der Steinbrecherfeste und vielleicht der ganzen Scherbenwelt von äußerster Wichtigkeit sind!\n\nIch bin von der Expedition des Cenarius mit einem diplomatischen Auftrag hierher geschickt worden, aber wie Ihr sehen könnt, waren sie mir nicht sehr freundlich gesonnen. Wenn Ihr mir helft in Sicherheit zu gelangen, verspreche ich Euch, dass Ihr ausreichend belohnt werdet!", sourceObjective = "Geleitet Isla Sternenmähne in Sicherheit und meldet Euch dann bei Beraterin Faila in der Steinbrecherfeste in den Wäldern von Terkkokar.", completion = "Isla Sternenmähne ist gerade gegangen, aber sie hat mir einen vollständigen Bericht über die Vorkommnisse im Posten der Feuerschwingen gegeben. Verständlich, dass sie über die Geschehnisse beim Cenariusdickicht sehr bestürzt ist.\n\nSie hat mir gesagt, dass Ihr die entscheidende Rolle bei ihrer Rettung gespielt habt, damit wir diese Informationen erhalten. Die Steinbrecherfeste steht tief in Eurer Schuld.\n\nBitte, nehmt im Namen aller dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10053] = { id = 10053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor bewältigen", description = "Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen. Wenn wir Glück haben, hat die Führung in Zeth'Gor noch nichts von Nekrogg erfahren.\n\nDie Knochenmalmer in Zeth'Gor werden normalerweise von Grillok \"Finsterauge\" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Wir dürfen nicht überrascht werden.", sourceObjective = "Tötet Grillok \"Finsterauge\" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.", sourceObjectiveStatus = "unverified-source-field" }
quests[10054] = { id = 10054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Verdammnis", description = "Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.\n\nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf die Ehrenfeste sind.\n\nEs bleibt keine Zeit, um Leutnant Amadi zu informieren. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!", sourceObjective = "Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Leutnant Amadi im westlichen Turm der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts verkommen lassen!", description = "Verstärkung ist gut, aber ich sehe nicht, dass sie irgendwelche Karren mit Barren oder Holz durch die Gegend ziehen.\n\nSchaut Euch um, Freund. Die Bäume sind knapp und die Minen voller Legionsabschaum.\n\nMir gehen die Vorräte aus. Ich versuche schon, sie, wo ich kann, zu ersetzen. Aber so langsam müssen wir anfangen, alles, was wir bekommen können, wiederzuverwenden.\n\nAm südlichen Ende des Pfads des Ruhms steht ein Haufen alter Belagerungsmaschinen 'rum. Ein paar der Teile kann man immer noch verwenden. Habt Ihr Lust, mir bei einer kleinen Wiederverwertungsaktion zu helfen?", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Dumphry in der Ehrenfeste.", progress = "Habt Ihr ein wenig wiederverwertbares Material unter all dem Staub, der Asche und der Kohle finden können?", completion = "Das hier ist in einem besseren Zustand, als ich befürchtet habe. Sicher, es wird eine Weile dauern bis der ganze Rost und Zunder entfernt ist, aber ich kann mich nicht beklagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10056] = { id = 10056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Blutenden Auges", description = "Die orcischen Ruinen von Zeth'Gor im Südosten dienen als Basislager für die immer weiter steigende Flut von Höllenorcs, die aus der Höllenfeuerzitadelle strömt.\n\nDie Söhne Lothars haben sie eine Zeitlang bekämpft, und ich würde ihre Geschichten nicht glauben, wenn ich diese Höllenorcs nicht mit eigenem Auge gesehen hätte.\n\nEtwas hat sie verändert, sie größer gemacht. Ich habe so etwas noch nie gesehen. Wir müssen alles in unserer Macht Stehende tun, um zu verhindern, dass sie noch stärker werden. Geht nach Zeth'Gor und zerstört sämtliche Vorräte, die Ihr dort finden könnt.", sourceObjective = "Zerstört 6 Stapel Vorräte des Blutenden Auges und meldet Euch dann bei Leutnant Amadi in der Ehrenfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Anführern", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme am Expeditionsrüstlager. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", sourceObjective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Ehrenwache Wesilow im Turm nordwestlich der Ehrenfeste zurück.", completion = "Wir können nur hoffen, dass die Geister der Fußsoldaten mit dem Verschwinden der Geister ihrer Offiziere zur Ruhe kommen. Ich danke Euch ein weiteres Mal für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein altes Geschenk", description = "<Der Blick des Priesters wandert langsam von seiner Tasse zu Euch.>\n\nHabt Ihr nichts Besseres zu tun, als einen Mann von seiner Tasse fernzuhalten?\n\nAch, was soll's. Ich bin der Meinung, dass Neuankömmlinge ein gutes Zeichen sind. Was würde Turalyon davon halten?\n\nIch erinnere mich noch an den Tag unserer Abreise, als ich ihm die Geheimnisse des Lichts gab. Während des Feldzugs und den folgenden Jahren hat er nicht einen einzigen Tag vergessen, seinen Mannen einen Abschnitt daraus vorzulesen.\n\nAls er uns wieder verließ, gab er mir das Buch zurück, damit ich bis zu seiner Rückkehr darauf aufpasse, aber ich Dummkopf dachte, es sei in meinem Quartier in der Waffenkammer sicher...", sourceObjective = "Besorgt die Geheimnisse des Lichts und bringt das Buch zu Vater Malgor Devidicus in der Ehrenfeste zurück.", progress = "Ich dachte, ich hätte Euch gesagt, dass Ihr mich nicht stören sollt. Was gibt's?", completion = "Ist es das? Kaum zu glauben, dass es die Schlacht überlebt hat. Die Gegebenheiten in den Ruinen waren nicht gerade gut für das Buch, aber ich bin dennoch froh, dass ich es wiederhabe.\n\nEs ist das einzige Zeichen, das ich von Turalyon habe.\n\n<Vater Devidicus scheint mit den Tränen zu kämpfen.>\n\nWenn man so lange Zeit Seite an Seite gekämpft hat, steht man sich noch näher als die eigene Familie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10059] = { id = 10059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor bewältigen", description = "Es ist unerlässlich, dass wir den Vorteil, den wir durch Euren Sieg über Nekrogg errungen haben, ausnutzen, {name}. Wenn wir Glück haben, hat die Führung in Zeth'Gor noch nichts von Nekrogg erfahren.\n\nDie Knochenmalmer in Zeth'Gor werden normalerweise von Grillok \"Finsterauge\" in die Schlacht geführt. Findet ihn in seinem Lager, einer Höhle im Felsen unter dem Außenposten, und tötet ihn. Durchsucht die Höhle nach den Schlachtplänen der Höllenorcs, wenn er tot ist. Thrallmar darf nicht überrascht werden.", sourceObjective = "Tötet Grillok \"Finsterauge\" und durchsucht seinen Unterschlupf nach den Angriffsplänen des Blutenden Auges.", sourceObjectiveStatus = "unverified-source-field" }
quests[10060] = { id = 10060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Verdammnis", description = "Eine schnelle Überprüfung der Pläne zeigt, dass der Anführer von Zeth'Gor, Kriegsherr Morkh, das Genie hinter den Angriffen, die von Knochenmagier Warlor geleitet werden, ist. Auf der Karte sind mehr als nur Morkhs Streitkräfte zu sehen.\n\nDie Pläne deuten an, dass die Streitkräfte der Knochenmalmer bewaffnet und zusammen mit den Kräften der Höllenfeuerzitadelle bereit für einen Angriff auf Thrallmar sind. Ihr müsst die Knochenmalmer aufhalten, bevor sie ihren Angriff starten können!", sourceObjective = "Tötet 15 Grunzer des Blutenden Auges, 10 Nekrolyten des Blutenden Auges, 5 Peons des Blutenden Auges und Kriegsherr Morkh. Meldet Euch danach bei Steingardist Ambelan im Rückenbrechergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerschütterlichen", description = "Als die Höllenorcs der Knochenmalmer das Expeditionsrüstlager angegriffen haben, fiel unsere Garnison sehr schnell. Es war eine kurze, blutige und grausame Schlacht. Es gab keine Überlebenden.\n\nObwohl wir die Toten begraben und uns an den Höllenorcs gerächt haben, spuken die Geister der Gefallenen immer noch in den Ruinen. Seit kurzem habe ich Visionen, in denen diese Geister zu einer Gefahr für Thrallmar werden.\n\nEs gibt nur einen Weg, um die Geister zur Ruhe zu bringen - Ihr müsst sie im Kampf besiegen.", sourceObjective = "Grelag möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 10 unerschütterliche Zauberhexer und 5 unerschütterliche Ritter am Expeditionsrüstlager südlich der Ehrenfeste tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10062] = { id = 10062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Anführern", description = "Trotz Eurer Bemühungen haben wir immer noch Probleme bei der Expeditionsrüstkammer. Niemand weiß mit Sicherheit, was dort vor sich geht, was genau die Geister der gefallenen Soldaten an die Ruinen bindet.\n\nVielleicht gehen wir die Sache falsch an. In meiner Vision habe ich gesehen, dass jeder Geist eine Verbindung zu den Ruinen hat, aber was ist, wenn eine Verbindung zu ihren Anführern besteht?\n\nErzmagier Xintor und Feldkommandant Thalvos standen ihren Männern besonders nahe. Vielleicht bringt die Vernichtung ihrer Geister die anderen zur Ruhe.", sourceObjective = "Besiegt die Geister von Erzmagier Xintor und Feldkommandant Thalvos und kehrt dann zu Grelag im Rückenbrechergrat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscherliga, für Gnome geeignet?", description = "Kindermädchen! Glaubt Ihr das?\n\nSie haben mich von einer viel versprechenden Grabung abgezogen und mit Odesyus' Expedition losgeschickt, um das Kindermädchen für diesen kleinen Gnom zu spielen!\n\nIch habe noch nie von einem Gnom gehört, der Ausgrabungsleiter werden wollte, Ihr etwa?\n\nAnscheinend nehmen wir jetzt auch Gnome und dieser ist wohl besonders von Murlocs fasziniert!\n\nNun gut, er ist losgezogen und hat sich in einem alten Schildkrötenpanzer an der nördlichen Küste der Insel eingerichtet. Geht und seht selbst, wenn Ihr mir nicht glaubt!", sourceObjective = "Zieht los und sucht nach Klopper Knacksklug, der sich in einem alten Schildkrötenpanzer an der Küste nördlich der Blutwacht eingerichtet hat.", completion = "Dachte ich's mir doch! Dieser mürrische alte Zwerg sollte mir eigentlich beim Transport meiner Ausrüstung und dem Sammeln von Daten helfen, aber stattdessen sitzt er nur in dem komischen Draeneidorf herum und betrinkt sich sinnlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht zu der Hand", description = "Die Hand von Argus hat bei Verteidigers Ruh' einen Vorposten eingerichtet, allerdings sind sie dort den Blutelfen und auch der Wildnis zahlenmäßig weit unterlegen. Ihrem Posten droht ohne Verstärkung bald der Fall und somit würden wir die Ereignisse bei der Vektorspule nicht länger im Auge behalten können.\n\nErstattet Späherin Jorli bei Verteidigers Ruh' im Nordwesten Bericht und bietet ihr Eure Hilfe an, {name}.", sourceObjective = "Erstattet Späherin Jorli bei Verteidigers Ruh' Bericht.", completion = "Ich habe gehofft, dass die Blutwacht uns Verstärkung schicken würde, sobald man dort weiß, mit wem wir es hier zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schneise schlagen", description = "Während unserer Mission, die Sonnenfalken und ihr Portal auszukundschaften, wurde ich ernsthaft verletzt. Späherin Loryi konnte glücklicherweise die Blutung stillen und sucht gerade nach einem Weg, um mich zur Blutwacht zu bringen.\n\nUnser Problem liegt allerdings darin, dass wir unsere Stellung hier verlassen müssen, um eine sichere Rückkehr garantieren zu können.\n\nSobald wir diesen sicheren Grund verlassen, werden uns Felshetzer anfallen. Wenn Ihr ein paar der wütenden Felshetzer aus dem Weg räumen könntet, würden wir höchstwahrscheinlich sicher an unser Ziel gelangen.", sourceObjective = "Tötet 10 wütende Felshetzer und kehrt zu Späherin Jorli bei Verteidigers Ruh' zurück.", completion = "Es sieht da draußen schon etwas besser aus, ich bin mir jedoch noch immer nicht sicher, ob es besser wäre, hier auf medizinische Versorgung zu warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles im Griff", description = "Wir wagen es nicht, unseren Posten zu verlassen oder uns zu weit von Verteidigers Ruh' zu entfernen, {race}. Die mutierten Kreaturen, die sich in der unmittelbaren Nähe der Vektorspule aufhielten, wurden schwerwiegend von der Energie beeinflusst, die den Kristallen entweicht.\n\nDie mutierten Greifer scheinen bis zu einem gewissen Grad Empfindungen entwickelt zu haben. Sie haben gelernt, tückische Fallen zu erschaffen, aufzustellen und zu verbergen, damit sich selbst die umsichtigsten Kämpfer darin verfangen.\n\nWir werden niemals gegen die Sonnenfalken vorgehen können, wenn wir ständig auf unsere Schritte Acht geben müssen. Packt das Problem bei der Wurzel, {name}.", sourceObjective = "Tötet 8 mutierte Greifer und meldet Euch bei Verteidigerin Corin bei Verteidigers Ruh'.", progress = "Konntet Ihr ein paar mutierte Greifer ausmerzen?", completion = "Gut gemacht, {name}. Ohne die Tücken der Greifer, wird es jetzt wesentlich einfacher sein, Verstärkung von der Blutwacht zu erhalten oder Angriffe gegen die Sonnenfalken zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Wassergeister", description = "Die meisten der Kreaturen, die von der Energie der Kristalle berührt wurden, wurden auf die gleiche Art verdorben: seltsame Male auf ihrer Haut, aggressiveres Verhalten und kleine Kristallsplitter in ihren Körpern. Wie dem auch sei, die besudelten Wassergeister der Blutmythosinsel scheinen sich vollständig in Kristall zu verwandeln.\n\nIch habe bis jetzt noch nichts gesehen, was derart auf die Kristalle reagiert hat. Als wir den Besudelten Teich untersucht haben, haben sie sich als besonders gefährlich herausgestellt. Wir müssen sie loswerden, bevor die Sonnenfalken sie als neue Energiequelle missbrauchen können.", sourceObjective = "Tötet 6 besudelte Wassergeister und kehrt zu Verteidigerin Corin bei Verteidigers Ruh' zurück.", completion = "Gut gemacht, {name}. Es ist besonders wichtig, dass wir keine Möglichkeit außer Acht lassen, die den Sonnenfalken weiterhin ihre Existenz sichern könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Geschosse", description = "Es ist Zeit für Eure erste Lektion in den Arkanen Künsten. Ich möchte Euch einen neuen Zauber, 'Arkane Geschosse', beibringen.\n\nIhr werdet diesen Zauber nicht jederzeit benutzen können, aber jedes Mal, wenn Ihr einen Angriffszauber wirkt, besteht eine Chance, dass Ihr 'Arkane Geschosse' wirken könnt.\n\nBegebt Euch ins Freie, macht eine Trainingsattrappe ausfindig und probiert es aus.", sourceObjective = "Erlernt 'Arkane Geschosse' von Julia Sonnensturm. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt 'Arkane Geschosse' 2 Mal.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wege des Lichts", description = "Es ist an der Zeit, Eure erste Lektion in den Wegen des Lichts zu lernen, {name}. Ich möchte Euch zwei Techniken beibringen, mit denen Ihr Euch selbst und Euren Verbündeten im Kampf helfen könnt.\n\nDie erste ist 'Siegel der Rechtschaffenheit'. Unter dem Einfluss dieses Siegels werden alle Eure Nahkampfangriffe zusätzlichen Heiligschaden verursachen.\n\nWährend Euer Siegel aktiv ist, könnt Ihr regelmäßig 'Richturteil' verwenden, um Eurem Gegner zusätzlichen Schaden zuzufügen. Geht nun und findet eine Trainingsattrappe, um Eure neuen Techniken zu üben.", sourceObjective = "Erlernt 'Richturteil' und 'Siegel der Rechtschaffenheit' von Jesthenis Sonnensturm. Wirkt 'Siegel der Rechtschaffenheit' auf Euch selbst, sucht eine Trainingsattrappe auf und benutzt 'Richturteil'.", progress = "Habt Ihr Eure neuen Fertigkeiten geübt?", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10070] = { id = 10070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Und nun ist es an der Zeit für Eure erste Lektion.\n\nIch werde Euch einen Schuss zeigen, den ich oft benutze. Ich bin sicher, Ihr werdet ihn auch nützlich finden.\n\nSobald unsere Lektion beendet ist, sucht eine der Trainingsattrappen draußen auf und versucht es einmal.", sourceObjective = "Erlernt 'Zuverlässiger Schuss' von Waldläuferin Sallina. Findet eine Trainingsattrappe vor dem Sonnenturm und übt 'Zuverlässiger Schuss' 5 Mal.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10071] = { id = 10071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Ich möchte Euch eine neue Technik beibringen. Sie ist hervorragend geeignet, eine Kombination von Kampfmanövern zu einem kraftvollen Abschluss zu bringen. Probiert sie aus, nachdem Ihr Euren Gegner mit mindestens einem 'Finsteren Stoß' getroffen habt. Je mehr 'Finstere Stöße' Ihr anbringen könnt, desto stärker wird Eure Abschlussattacke sein.\n\nBenutzt eine der Trainingsattrappen draußen, um zu üben.", sourceObjective = "Erlernt 'Ausweiden' von Pfadpirscher Kariel. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt 'Ausweiden' 3 Mal.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10072] = { id = 10072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verwundeten heilen", description = "Die Zeit für Eure erste Lektion in der Kunst der Heilung ist gekommen. Ich möchte Euch einen sehr grundlegenden Zauber beibringen, mit dem Ihr schnell die Wunden eines Verbündeten heilen könnt.\n\nSobald wir unsere Lektion beendet haben, möchte ich, dass Ihr Eure neuen Heilkünste an einigen der verwundeten Kundschafter übt, die im Sonnenturm Zuflucht gefunden haben.", sourceObjective = "Erlernt 'Blitzheilung' von Matrone Arena. Übt 'Blitzheilung', indem Ihr sie 5 Mal auf verwundete Kundschafter wirkt.", completion = "Ah, wie schön, ein {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10073] = { id = 10073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbrand", description = "Mittlerweile habt Ihr die Gerüchte über unsereins, die Hexenmeister, gehört. Schenkt ihnen keine Beachtung; es sind diejenigen, die neidisch auf unsere furchteinflößende Macht sind, die solche Lügen verbreiten.\n\nGestattet mir, Euch einen neuen Zauber zu zeigen, der es Euch erlaubt, einen Feind in Brand zu setzen und ihn eine Zeit lang brennen zu lassen. Sobald unsere Lektion beendet ist, möchte ich, dass Ihr diesen neuen Zauber an den Trainingsattrappen vor dem Sonnenturm ausprobiert.", sourceObjective = "Erlernt 'Feuerbrand' von Beschwörer Teli'Larien. Macht eine Trainingsattrappe vor dem Sonnenturm ausfindig und übt 5 Mal 'Feuerbrand' zu wirken.", progress = "Habt Ihr den Feuerbrand gemeistert?", completion = "Ah, wie schön, eine {class}. Ich habe Euch bereits erwartet.\n\nIch hätte da ein paar Aufgaben zu vergeben, für die Ihr Euch besonders gut eignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, das Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiterin Amereldine in Halaa.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Allianz helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich nehme immer gerne Kristallpulverspenden an, {name}. Ihr werdet für jedes Bündel, das Ihr mir bringt, entlohnt werden." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", description = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", sourceObjective = "Bringt 10 Kristallpulverproben von Oshu'gun zu Forschungsleiter Kartos in Halaa.", progress = "Das Kristallpulver des Bergs ist vom Erdenkern dieser Gegend durchdrungen.", completion = "Wundervoll, {name}. Das wird uns in unserem Kampf gegen den Abschaum der Horde helfen, der sich hier in der Scherbenwelt breitgemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallpulver von Oshu'gun", progress = "Dieser Stützpunkt war die erste Forschungseinrichtung für die Untersuchung von Naarukristallen.\n\nWir haben hier eine wahre Goldgrube an Forschungsunterlagen über die Kristalle des \"diamantenen\" Bergs, Oshu'gun, gefunden. Wie es scheint, ist überall in diesem Gebiet etwas von der übrig gebliebenen Macht der Kristalle von Oshu'gun enthalten. Wenn Ihr während Euren Abenteuern in diesem Gebiet Kristallpulver finden solltet, bringt es zu mir, und ich werde Euch ein Zeichen meiner Wertschätzung geben, dass Ihr bei den Rüstmeistern eintauschen könnt.", completion = "Ich danke Euch für Euren Beitrag, {name}. Wenn Ihr noch mehr finden solltet, wisst Ihr, wo Ihr sie hinbringen könnt." }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unerwünschten zerstören", description = "Jetzt, da unsere Bergungsaktion ins Rollen gekommen ist, ist es an der Zeit, die zweite Phase unseres Plans einzuläuten.\n\nAm Pfad des Ruhms hat die Horde immer noch ihre alten Klingenwerfer postiert. Lasst Euch von Ihrem Alter nicht täuschen, {name}, sie sind immer noch sehr gefährlich. So sehr wir auch versuchen, alles zurückzuerobern, was wir können, können wir nicht erwarten, dass die Horde ihre Waffen einfach so abbaut.\n\nNehmt diese Fackel und zündet ihre übriggebliebene Belagerungsausrüstung an. Ich werde die Sicherheit der Ehrenfeste nicht dem Zufall überlassen.", sourceObjective = "Zündet die Klingenwerfer der Horde mit der flammenden Fackel am Pfad des Ruhms an. Kehrt dann mit der flammenden Fackel zu Dumphry in der Ehrenfeste zurück.", progress = "Ihr scheint guter Laune zu sein. Haben die brennenden Belagerungsmaschinen der Horde Euch erheitert?", completion = "Das nenne ich Einsatz!\n\nIch bin froh, dass wir endlich Unterstützung erhalten haben, aber ich bin nicht so sicher, ob sie die richtige Einstellung gegenüber der Horde haben. Dort, wo ich herkomme, ist jeder, der eine Waffe auf Euch richtet, ein Feind und muss vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt!\n\nSie haben nicht nur meine Arbeiter aus den Tunneln getrieben, sondern hämmern auch noch Tag und Nacht darin herum! Und jetzt sitzt mir auch noch Danath im Rücken! Sagt, er würde mir meine Bierration streichen, wenn ich mich nicht bald darum kümmere!\n\nKeiner der Minenarbeiter will dort hineingehen, und die Wächter sind zu sehr damit beschäftigt, sich vollaufen zu lassen.\n\nIch flehe Euch an, {name}, helft mir! Danath mag mir meinen Stolz nehmen, aber niemals mein Bier!", sourceObjective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Biggums zurück.", completion = "Bei Bronzebarts bronzenem... Bart, Ihr habt es geschafft! Ihr seid ein Held, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10080] = { id = 10080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager der Legion", description = "Ich habe mit Humphry gesprochen. Er hat Euch sicher gesagt, dass die Heimsuchung der Mine ein kleineres Übel ist, aber ich bin der Meinung, dass es sogar ein sehr großes Übel ist.\n\nNordöstlich des Hordenpostens Thrallmar arbeiten die Diener der Legion Tag und Nacht an etwas, aber was?\n\nKeiner der Späher, die ich dorthin geschickt habe, ist je zurückgekommen. Die Zeit der Zurückhaltung ist vorbei, {name}. Begebt Euch in das Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.", sourceObjective = "Tötet 10 Diener der Gan'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutter Kashur treffen", description = "Erschreckt Euch nicht über das, was Ihr sehen werdet, wenn die Wirkung eintritt. Diese Geister sind überall um uns herum - immer. Der Trank erlaubt Euch nur, sie zu verstehen und zu sehen. Ihr werdet seine Wirkung brauchen, wenn Ihr mit Mutter Kashur sprecht.\n\nIhr findet sie ein gutes Stück im Südwesten beim Ahnengrund.", sourceObjective = "Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht.", completion = "Der Trank, den Ihr zu Euch genommen habt, hat keine echte Wirkung. Ihr könnt einen Geist nur sehen, wenn er es zulässt. Der Trank ist nur ein Symbol Eures Glaubens und Eurer Hingabe. Es war ein Test. Und Ihr habt ihn bestanden...", sourceObjectiveStatus = "unverified-source-field" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die aufgebrachten Ahnen", description = "Seht Ihr, wie sie unter uns wandeln? Der Ahnengrund ist normalerweise sehr ruhig und friedlich.\n\nIn letzter Zeit haben sich die Geister der Ahnen jedoch erhoben und sind sehr aufgebracht. Etwas muss sie sehr stören. Wir müssen herausfinden, was das sein könnte, aber zuerst müssen wir die direkte Bedrohung beseitigen.\n\nDie Geister, die Ihr hier seht, sind nicht wirklich unsere Ahnen, sondern ein Abbild ihrer gegenwärtigen Lage. Ihr müsst die aufgebrachten Orcgeister zerstören. Tut dies und kehrt dann zu mir zurück.", sourceObjective = "Mutter Kashur möchte, dass Ihr 8 aufgebrachte Orcgeister tötet.", completion = "Es ergibt keinen Sinn. Sie erheben sich weiter. Es muss etwas Heimtückischeres dahinter stecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10083] = { id = 10083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pläne der Legion", description = "Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.\n\nFeldmarschall Rohamus sprach von einem weiteren Konstruktionslager im Westen, dem Konstruktionslager: Bosheit. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?\n\nWenn die Legion etwas in Massenproduktion herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.", sourceObjective = "Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Feldmarschall Rohamus im Expeditionsposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10084] = { id = 10084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Mageddon", description = "Mit den Fähigkeiten der Ingenieure der Mo'arg und der endlosen Menge an Gan'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Nethergarde Bescheid geben können.\n\nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von der Ehrenfeste für diesen Angriff abziehen, das wäre purer Selbstmord! Die Höllenorcs und die Horde würden uns bei dem kleinsten Anzeichen von Schwäche überrennen.\n\nDie Ehrenfeste steht nun seit 20 Jahren, und wir haben nicht vor, sie jetzt zu verlieren.", sourceObjective = "Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Truppenkommandant Danath Trollbann in der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Ahnen", description = "Ich brauche Euch, um zu den Dörfern unserer Ahnen zu reisen, {name}. Geht zu jedem einzelnen und schaut, ob unsere Vorfahren noch da sind.\n\nGeht zum Sonnenwindposten im Norden, zu den Ruinen des Lachenden Schädels ganz im Norden bei den Bergen, besucht Garadar im Nordosten und zuletzt die Ruinen des Blutenden Auges an der Grenze zwischen Nagrand und den Wäldern von Terokkar im Osten.\n\nBerichtet mir, sobald Ihr die Ahnen in ihrem Zuhause beobachtet habt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht.", completion = "Das ist sehr beunruhigend. Ihr sagt keiner der Ahnen war in seinem Dorf? Sie gehen alle nach Süden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich arbeite... für die Horde!", description = "Könnt Ihr das fassen? Diese Orcs haben mich angeheuert, um ihre beschädigten Befestigungsanlagen abzustützen und Sprengstoff herzustellen. Ist das nicht ein Traumjob? Nur zu schade, dass uns die Materialien ausgehen, aber ein gewitzter Goblin wie ich weiß sich immer zu helfen!\n\nKönntet Ihr mich dabei unterstützen? Ich benötige ein wenig gebrauchtes Holz und Metall von den zerstörten Belagerungsmaschinen entlang des Pfads des Ruhmes. Geht dorthin und sammelt, aber gebt auf diese rothäutigen Orcs Acht!\n\nWenn Ihr fertig seid, kommt zurück und holt Euch eine fette Belohnung ab!", sourceObjective = "Bringt 8 Stück gebrauchtes Metall und 8 Stück gebrauchtes Holz zu Megzeg Knaxknöchel in Thrallmar.", progress = "Wie geht es mit der Sammelaktion voran? Habt Ihr etwas Wiederverwertbares finden können?", completion = "Die Materialien sind ausgezeichnet! Vielleicht ein wenig verbogen oder angesengt, aber ich habe mich noch nie von minderwertigem Material aufhalten lassen, wenn es darum ging, Präzisionssprengstoff herzustellen!\n\nDanke, {name}. Ihr habt wirklich ein Händchen exquisiten Müll!", sourceObjectiveStatus = "unverified-source-field" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zündet es an... für die Horde!", description = "Ich bin ein glücklicher, glücklicher Goblin! Ich darf hier Sprengstoff und Killermaschinen herstellen in der Gewissheit, dass sie sofort bei wichtigen Missionen eingesetzt werden!\n\nWo wir gerade von Missionen sprechen, ich habe einen Befehl aus Thrallmar erhalten: Verbrennt die Kanonen der Allianz entlang des Pfads des Ruhms... die Kanonen, die gefährlich auf die Befestigungsanlagen der Horde gerichtet sind. Nehmt diese Fackel und begebt Euch zu jeder Kanone. Zündet die Fackel an und bestaunt den Funkenflug!", sourceObjective = "Zündet die östliche und die westliche Kanone der Allianz mit der flammenden Fackel an und kehrt danach zu Megzeg Knaxknöchel in Thrallmar zurück.", progress = "Ich habe nach Zeichen von brennenden Kanonen Ausschau gehalten - Rauchschwaden oder den Schreien brennender Höllenorcs...\n\nHattet Ihr Erfolg mit Eurem Auftrag?", completion = "Dachte ich's mir doch! Ich konnte die Zerstörung von hier aus zwar nicht richtig sehen, aber ich kann sie mir redlich vorstellen! Ausgezeichnet!\n\nGut gemacht, {name}. Das oberste Kommando von Thrallmar wird sich freuen, von Eurem Erfolg zu hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[10088] = { id = 10088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.\n\nWenn wir dieses Gan'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Erzen und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?", sourceObjective = "Tötet 12 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10089] = { id = 10089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager der Legion", description = "Thrallmar steht seit seiner Gründung unter Beschuss der Lager der Legion. Bis jetzt haben wir standhalten können, aber die Situation wird von Tag zu Tag schlimmer.\n\nSchattenjäger Ty'jin hat mehrere Versuche unternommen, mehr über die Lager herauszufinden, aber keiner seiner Späher ist je zurückgekehrt.\n\nDie Zeit für Zurückhaltung ist vorbei, {name}. Begebt Euch ins Konstruktionslager: Zorn und findet heraus, was die Legion vorhat.", sourceObjective = "Tötet 10 Diener der Gan'arg, 5 Legionäre des Konstruktionslagers und 5 Schwestern des Leids. Durchsucht danach des Konstruktionslager: Zorn nach einem Hinweis auf die Absichten der Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10090] = { id = 10090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pläne der Legion", description = "Ihr schreibt die leuchtenden Glyphen, die in den Boden geritzt wurden, ab, aber ohne die zweite Hälfte ergibt das Diagramm keinen Sinn.\n\nDie Glyphen verweisen darauf, dass ein weiteres Konstruktionslager im Westen, das Konstruktionslager: Bosheit, an dem Projekt beteiligt ist. Vielleicht bewahrt die Legion dort die zweite Hälfte der Pläne auf?\n\nWenn die Legion etwas wirklich Gewaltiges herstellt, macht es Sinn, dass die Teile in verschiedenen Lagern zusammengebaut werden.", sourceObjective = "Besorgt die Pläne des Konstruktionslagers: Bosheit und bringt sie zu Oberanführer Hun Stümmelfaust im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeleninstrumente", description = "Pah! Sie haben mich gefoltert und versucht, etwas über die Verteidigungsanlagen von Shattrath aus mir herauszuquetschen.\n\nIch habe mich geweigert - da haben sie die anderen Spione an Höllenschlund verfüttert, und ich sollte der Nächste sein. Aber ich habe ihnen nichts verraten!\n\nSie sind wahnsinnig! Sie sind versessen darauf, dämonische Mächte zu beschwören, die sie auf gar keinen Fall kontrollieren können!\n\nSie benutzen besondere Seeleninstrumente, um ihre Seelensplitter herzustellen und ihre Beschwörungen noch mächtiger zu machen. Ihr müsst ihnen diese Instrumente stehlen!\n\nIch würde Euch ja begleiten, aber ich muss nach Shattrath zurück um der Spionagemeisterin des Unteren Viertels zu berichten.", sourceObjective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath.", progress = "Ja? Was kann ich für Euch tun, {class}?", completion = "To'gun hat mir bereits seinen Bericht abgeliefert. Er hätte Euch unterstützen sollen!\n\nIch habe ihn zurückgeschickt, um Grik'tha zu helfen. Ich finde, die beiden sind ein schönes Paar.\n\nDies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Ich finde, sie sehen gefährlich aus. Vielleicht können die Seher sie brauchen?\n\nHier, nehmt einen davon als Belohnung für Euren Kampf gegen den Schattenrat im Labyrinth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10092] = { id = 10092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Mageddon", description = "Mit den Fähigkeiten der Ingenieure der Mo'arg und der endlosen Menge an Gan'argdienern werden sie sicher schneller Teufelshäscher produzieren, als wir in Orgrimmar Bescheid geben können.\n\nWir haben keine andere Wahl als sie so schnell wie möglich anzugreifen. Wir können keine Männer von Thrallmar für diesen Angriff abziehen, dann wären wir zu leicht angreifbar.\n\nEs gibt zu viele, die sich, ungeachtet der Allianz, nur zu gerne auf unseren ungeschützten Außenposten stürzen würden. Versagt nicht, {name}. Es hängt zu viel von Euch ab.", sourceObjective = "Tötet Nachtlord Malphas im Konstruktionslager: Mageddon und meldet Euch dann bei Oberanführer Hun Stümmelfaust im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Telhamat", description = "Zum Glück ist der Pfad des Ruhms nicht das einzige Zeichen meines Volks in diesen Ländereien. Im Westen befinden sich immer noch ein paar unserer geheiligten Stätten, auch wenn einige von ihnen überrannt wurden.\n\nWährend Velen sich auf seine Reise nach Azeroth vorbereitete, haben diejenigen von uns, die hier bleiben sollten, versucht, sich wieder in unseren heiligen Orten niederzulassen.\n\nIm westlichen Teil der Höllenfeuerhalbinsel könnt Ihr beim Tempel von Telhamat eine kleine Gruppe von Draenei finden, die von Amaan dem Weisen angeführt werden. Ich bin mir sicher, dass er Euch gerne kennenlernen würde.", sourceObjective = "Sprecht mit Amaan dem Weisen beim Tempel von Telhamat im Westen der Höllenfeuerhalbinsel.", completion = "Ah, Ihr habt also Seher Kryv getroffen. Er ist ein weiser und begabter Mann, und seine Freunde sind auch meine Freunde.\n\nMacht es Euch gemütlich und stellt Euch den anderen vor, die diesen Tempel ihr Zuhause nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex des Blutes", description = "Es ist nun zwei Jahre her, dass die Beschwörung des Schattenrats dieses einst großartige Mausoleum explodieren und die Knochenwüste entstehen lies.\n\nJetzt befinden sie sich im Krieg mit einer unglaublich mächtigen Kraft im Inneren.\n\n{name}, Ihr müsst in das Schattenlabyrinth eindringen und herausfinden, wogegen sie kämpfen und ob es eine Gefahr für uns sein könnte. Unserer Spione haben berichtet, dass sie ein verbotenes Buch mit unheiligen Beschwörungen verwenden, bekannt als der Kodex des Blutes.\n\nSucht in ihm nach Antworten.", sourceObjective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig falsch!\n\nIhr lest weiter, aber was Ihr lest scheint unglaublich zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Labyrinths", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren! Es hat die Explosion von Auchindoun verursacht und die Knochenwüste erschaffen.\n\nJetzt nur noch als Murmur bekannt, droht es, den Schattenrat zu überrennen und zu entkommen!\n\nNun, da der Großmeister und der Rest der Führung tot sind, seid Ihr die einzige Hoffnung der Scherbenwelt im Kampf gegen dieses Monster!\n\n{name}, tief in Eurem Herzen wisst Ihr, dass Ihr und Eure Freunde nicht versagen dürfen!", sourceObjective = "Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth.", completion = "Murmur ist fast ausgebrochen?! Sie haben das Biest zwei Jahre sicher im Inneren verwahrt... Ich frage mich, was sie wohl falsch gemacht haben, dass sie nach all der Zeit die Kontrolle darüber verlieren.\n\nWas auch immer es sein mag, {name}, Ihr habt uns alle gerettet! Mir wird schwindelig, wenn ich daran denke, was Shattrath und dem Rest der Scherbenwelt zugestoßen wäre, wenn das Ding sich hätte befreien können!\n\nIch bin so froh, dass Ihr die Sache in die Hand genommen und die Bedrohung durch den Schattenrat in Auchindoun beseitigt habt. Wie können wir Euch je dafür belohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Sporloks", description = "Ikeyen hat mir erzählt, was ihm in diesen Höhlen widerfahren ist, und ich finde es einfach nur schrecklich!\n\nWisst Ihr, vielleicht sollten wir diesen armen Sporloks helfen. Ikeyen sagt, dass sie dort in der Funggorhöhle leben, aber die Marschenbestien sind kürzlich dort eingefallen.\n\nWarum geht Ihr nicht dort hin und schaut, dass Ihr ein paar von diesen Marschenbestien erlegt? Die Höhle ist ganz nah im Südwesten.", sourceObjective = "Tötet 10 Marschengräber und 10 Marschenlauerer und kehrt dann zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen zurück.", completion = "Gut! Diese Marschenbiester haben kein Recht, das Zuhause der Sporloks zu überfallen!\n\nEs wäre besser, wenn diese Tiere lernen würden, in Harmonie zu leben, aber wenn das nicht geht, müssen wir uns eben um die Situation kümmern!\n\nHier, bitte nehmt etwas hiervon als Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Die Sethekk haben Skettis mit Fanfaren verlassen, als Auchindoun explodiert ist. Das war sicher ein Vorbote für die Ankunft unseres Meisters.\n\nMein Bruder, Syth, war einer ihrer Anführer und hat uns gesagt, dass es unsere Pflicht wäre, in die Tempelruinen zu gehen und unserem Gott zu begegnen.\n\nNachdem wir unser Lager in den Ruinen aufgeschlagen und sie die Sethekkhallen getauft hatten, kamen mir Zweifel an den Fähigkeiten meines Bruders und seines Verbündeten Ikiss.\n\nNach einiger Zeit hat mich Syth aus den Hallen geworfen und mir verboten, meine Schwester Lakka mitzunehmen. Helft Ihr mir, sie zu retten?", sourceObjective = "Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt.", completion = "Ich kann Euch nicht genug danken, {name}. Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Wenn ich nach Skettis komme, werde ich die Todesriten für ihn vollziehen. Vielleicht kann sein Geist zur Ruhe kommen, wenn er für die Irreführung unseres Volkes gebüßt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Erbe", description = "Mein Volk verehrt einen uralten Helden namens Terokk. Arakkoaküken erfreuen sich an den Geschichten über seine Taten und den Beschreibungen seines prächtigen Federkleids.\n\nEr lebte für hunderte von Jahren unter meinem Volk, doch eines Tages verschwand er urplötzlich, und ließ nur seine Maske, seinen Speer und seine Schriften zurück.\n\nDiese Relikte werden von den Arakkoa hoch verehrt, und es brach ihnen das Herz, als die Sethekk die Gegenstände bei ihrem Aufbruch aus Skettis verschleppten.\n\nIch habe alles, was ich über den Verbleib der Schriftrollen in den Hallen weiß, niedergeschrieben.", sourceObjective = "Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinen Volk zurückgebe.\n\nVielen Dank für Eure Hilfe dabei, {name}. Ihr habt keine Ahnung, welch großartige Tat Ihr heute geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Genie", description = "Diese verfluchten Gan'arg wuseln immer noch in die Mine! Für jeden, den wir umbringen, scheinen zwei oder drei weitere aufzutauchen!\n\nIrgendwas in den Tiefen der Mine muss diese Menge steuern. Ihr scheint das letzte Mal ganz gut klargekommen zu sein, und das Licht weiß, dass Ihr <der/die> Einzige seid, <der/die> mutig genug ist, wieder in die Mine zu gehen. Findet heraus, wer für dieses Ärgernis verantwortlich ist und bestraft ihn dafür!", sourceObjective = "Sucht und tötet Z'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück.", progress = "Ich traue mich fast nicht zu fragen. Euch aus der Mine herauskommen zu sehen kann nur zwei Dinge bedeuten: entweder habt Ihr diesen Bastard umgebracht oder Ihr habt keine Lust mehr. Nun, welches von beiden ist es?", completion = "Ich bin froh, dass Ihr Euch um, um... wie sagtet Ihr hieß er noch gleich? Z'kral?\n\nEurer Beschreibung nach war es wohl mehr ein \"es\" als ein \"er\". Nun ja, was zählt ist, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10100] = { id = 10100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Genie", description = "Versteht mich nicht falsch, {name}, ich bin sehr froh, dass Ihr Euch bereit erklärt habt, uns mit den Minen zu helfen, aber für jeden Pionier, den Ihr getötet habt, sind zwei neue dazugekommen.\n\nIch habe Wachkommandant Krunk schon die Ohren vollgeheult, aber er weigert sich immer noch, mir Hilfe zu schicken. Er murmelt immer irgendwas von Höllenebern. Wenn ich mir nicht so sicher wäre, dass er mich verprügeln würde, würde ich ihm sagen, dass jetzt nicht die Zeit ist, um an Rippchen zu denken!\n\nWie auch immer, es sieht so aus, als ob irgendjemand tief in den Minen die ganze Sache steuert. Findet ihn und tötet ihn!", sourceObjective = "Sucht und tötet Urga'zz in den Minen unter Thrallmar und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Geister sprechen", description = "Oshu'gun, der diamantene Berg, war einst ein heiliger Ort meines Volkes. Dort versammelten sich die Klans jedes Jahr, um das Frühlingsfest zu feiern. Dort kommunizierten unsere Schamanen mit unseren altehrwürdigen Vorfahren. Er bildete das Zentrum unserer Kultur - bis die Schatten uns übernahmen. Als die Klans zu einer Horde wurden, verstummten die Geister von Oshu'gun. Unsere Vorfahren haben sich von uns abgewendet.\n\nDoch nun werden sie in ihrer Ruhe gestört. Reist nach Oshu'gun und findet heraus, was die Geister beunruhigt.", sourceObjective = "Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun.", completion = "<Eine sanfte, melodische Stimme erklingt in Eurem Kopf.>\n\nIch bin K'ure von den Naaru, {name}. Ihr steht hier im Herzen meines alten Schiffs.\n\nOshu'gun, wie die Orcs es genannt haben, ist das Schiff, mit dem die Draenei zuerst auf diese Welt gekommen sind. Obwohl wir schon vor hunderten von Jahren hier vom Himmel gefallen und abgestürzt sind, sind meine Energien immer noch in diesen Trümmern gefangen. Leider bin ich der Grund für die Schmerzen der Orcgeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gelüftetes Geheimnis", description = "Als meine Energien sich über die Jahrhunderte nach und nach verflüchtigten, nahm eine Leere meinen Platz ein und verschlang die Seelen in der Nähe. Hilflos musste ich zusehen, wie ganze Generationen von Orcseelen in den Wirbel hineingezogen wurden. Vor Kurzem bemächtigten meine Feinde sich des Wirbels und benutzten ihn, um zahllose Leerdiener in ihre Brennende Legion zu rufen.\n\nNun liegt der Schlüssel zur Beendigung dieses Kreislaufs und der Befreiung der Orcgeister bei einem anderen Naaru, A'dal. Ich konnte seine Essenz in der uralten Stadt Shattrath in den Wäldern von Terokkar fühlen.", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "<Ihr seid der Meinung, dass das Wesen Euch, wenn es das könnte, zunicken würde.>\n\nNatürlich... Wir haben nach der Essenz eines Naaru gesucht. K'ure liegt seit Jahrhunderten im Sterben, und die Leere hat ihn schon fast ganz erfüllt. Wir haben seine Anwesenheit nicht spüren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Zurai", description = "Mit der Ankunft von Feldkommandeur Romus und seinen Streitmächten sind die Allianz und ihre Draeneifreunde mutiger geworden. Sie wandeln alle alten Draeneiruinen von hier bis Shattrath in Heerlager um.\n\nAls Antwort darauf haben die Trolle einen neuen Außenposten im östlichen Teil der Zangarmarschen errichtet, südlich des Todesmoors. Sie nennen ihn Sumpfrattenposten. Ich bin froh, dass sie sich in einer solchen Umgebung ihren Humor bewahrt haben. Ich wollte jedenfalls nicht mit ihnen tauschen.\n\nDer Kommandeur des Posten hat mich gebeten, ihm alle Mann zu schicken, die ich entbehren kann.", sourceObjective = "Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen.", completion = "Um ehrlich zu sein hatte ich mehr Leute erwartet, aber Ihr müsst reichen. Willkommen im Sumpfrattenposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorgen um Tuurem", description = "Die Gerüchte über Tuurem sind beunruhigend. Manche sagen, die Ruinen der Stadt laufen vor verrückten Zerschlagenen und Verirrten über, während gierige Artefaktjäger Draeneirelikte stehlen.\n\nEs ist schwer zu sagen, welche wahr und welche falsch sind, aber es liegt in unserer Verantwortung, die Ruinen so gut es geht zu schützen. Sucht Andarl in Allerias Feste in den Wäldern von Terokkar. Er ist eine Art Forscher für magische Relikte. Er weiß wahrscheinlich besser als alle anderen Bescheid, was dort vor sich geht.", sourceObjective = "Sprecht mit Andarl in Allerias Feste in den Wäldern von Terokkar.", completion = "Ich fühle mich geschmeichelt, dass Euer Freund von den Zerschlagenen mich für einen Gelehrten für Relikte seines Volkes hält, aber um ehrlich zu sein habe ich seit meiner Ankunft nicht viel Gelegenheit gehabt, sie zu studieren. Das war sicherlich meine Absicht, aber als ich hier ankam musste ich feststellen, dass es andere Dinge gibt, um die ich mich dringend kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichten für Rakoria", description = "Jetzt, da der Sumpfrattenposten fertig ist, haben wir nicht mehr so viel Kontrolle über die Wege, die in die Marschen und aus ihnen heraus führen. Unsere Anwesenheit in den Wäldern von Terokkar ist nun viel unsicherer. Trotzdem wartet Rakoria in der Steinbrecherfeste auf Nachrichten über unsere Fortschritte hier.\n\nSie ist sehr schlau und tüchtig, {name}, aber seid vorsichtig, wenn Ihr in ihrer Nähe seid. Sie hat viele Waren, die sie nur zu gerne auf den Weg schicken würde, aber glaubt nicht, dass sie nur unser Bestes im Sinn hat. Rakoria geht dorthin, wo sie den besten Gewinn machen kann.", sourceObjective = "Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar.", completion = "Ich hatte gehofft, seine Leute würden den Außenposten früher fertigstellen, aber sein Geld kostet es ja schließlich nicht. Immerhin geht es voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", progress = "{name}, kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Kilrath hat Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Südosten, nahe der Grenze zu Terokkar. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Maßnahmen", description = "Die Agenten der Jägerin haben Neuigkeiten über den Anführer der Felsfäuste geschickt: Es ist ein Orc! Ein uralter Orc, der in der Zeit unserer Väter das Dunkle Portal durchschritten hat und in sein Heimatland zurückgekehrt ist. Ich möchte, dass Ihr diesen Orc ausfindig macht und ihn davon überzeugt, die Felsfäuste zurückzuziehen. Er lebt auf einer der höheren Ebenen bei den Ruinen der Brennenden Klinge im Osten. Viel Erfolg, {name}!\n\nSeid auf der Hut, er ist ein Klingenmeister...", sourceObjective = "Mo'mor der Brecher in Telaar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht.", progress = "Sprecht.", completion = "Wie also lautet Eure Entscheidung? Soll es Krieg geben, oder werdet Ihr mich unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich muss sie haben!", description = "Könnt Ihr sie sehen?? Bei Gazlows wundervollem Mundgeruch, ich muss diese Eier haben! Ihr seht aus wie jemand, den man gebrauchen kann.\n\nIch sag Euch was, {race}, wenn Ihr ein paar Dinge für mich sammelt, damit ich meinen Spring-o-Mat 4000 zum Laufen bekomme, werde ich Euch einen Schlüssel geben, mit dem auch Ihr die Maschine bedienen könnt! Was man mit einem Spring-o-Mat 4000 machen kann? Wohl eher was man damit nicht machen kann...\n\nIch brauche Luftelementargas von den Luftelementaren in Nagrand. Sie sind überall, fragt mich also nicht, wo Ihr sie finden könnt!", sourceObjective = "Wazdaz gegenüber der Klanwacht im Süden von Nagrand möchte, dass Ihr ihm 3 Einheiten Luftelementargas bringt.", progress = "Habt Ihr das Gas?", completion = "Ausgezeichnet! Nur ein paar kleine Einstellungen und dieses Ding ist so gut wie neu. Oh richtig, Euer Schlüssel! Bitte sehr.\n\nDer Spring-o-mat hat übrigens noch ein paar Macken, die ich noch reparieren muss. Äh, seid einfach vorsichtig damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mir das Ei!", description = "Jetzt, da Ihr initiiert wurdet, möchte ich, dass Ihr mir dieses Ei bringt! Benutzt den Spring-o-Mat und versucht, das Nest genau in der Mitte zu treffen. Aber seid vorsichtig! Schlechte Sprünge können in körperlichen Schäden oder dauerhaften schweren Wunden resultieren.", sourceObjective = "Wazdaz in Nagrand möchte, das Ihr den Spring-o-Mat 4000 benutzt, um in das Nest in dem nahe gelegenen Baum zu springen und das geheimnisvolle Ei zu stehlen.", progress = "Habe ich meine Vorliebe für Eier erwähnt?", completion = "Nun, es ist kein Ei... Aber Hühnchen mag ich auch! Ich beiße mich einfach durch diese riesige Klaue durch! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein persönlicher Gefallen", description = "Hmmm? Eine Kiste sagt Ihr? Oder waren es mehrere? Wisst Ihr aus welchem Material sie war?\n\nUnd wie heißt der Händler? Empoor? Und Ihr seid Euch sicher, dass er ein Zerschlagener ist? Ich mache nicht viele Geschäfte mit ihresgleichen.\n\nVielleicht hilft es meinem Gedächtnis ein wenig auf die Sprünge, wenn Ihr mir einen Gefallen tut.\n\nDie Arakkoa der Skith - diese primitiven Zauberer - haben neulich eine große Schiffladung meiner magischen Waren gestohlen. Ich will alles zurückhaben!\n\nIhr könnt das Skithversteck südlich von Shattrath finden.", sourceObjective = "Holt 5 von Lathrais gestohlenen Waren zurück und bringt sie zu Windhändler Lathrai bei der Taverne Weltenend im Unteren Viertel in Shattrath.", progress = "Hmm, wird mein Gedächtnis schon besser?", completion = "Ja, ich glaube, es wird alles deutlicher.\n\nUnd ich glaube, dass Euer Eifer in dieser Angelegenheit mit mehr als nur den Informationen, die Ihr sucht, belohnt werden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "\"Geht und sucht ein paar Vorräte\", hat er gesagt. Ich bin fast fünfzehn Mal getötet worden, bevor ich diesen Ort hier überhaupt gefunden habe! Diese Zerschlagenen sind vielleicht nicht das gastfreundlichste Volk, das ich kenne, aber immerhin haben sie nicht versucht, mir die Haut von den Knochen zu ziehen!\n\nWie auch immer, ich gehe nicht zurück. Meine Tage als Großwildjäger sind vorbei. Wenn ihr zufällig nach Nordosten Richtung Zangarmarschen geht und bei Nesingwarys Safari vorbeikommt, sagt dort Bescheid, dass \"die Flinte\" gekündigt hat.\n\nHey, vielleicht könnt Ihr ja meinen Platz einnehmen! Viel Glück, <Fremder/Fremde>.", sourceObjective = "\"Die Flinte\" Jones möchte, dass Ihr mit Hemet Nesingwary in Nesingwarys Safari am nordöstlichen Rand von Nagrand sprecht.", completion = "Ich schätze, wir müssen einen Ersatz für den Wasserträger finden. Nun, Ihr seht aus wie ein kräftiger {class}. Interesse an einem Job? Oder kommt Ihr wegen der Jagd?", sourceObjectiveStatus = "unverified-source-field" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwarys Safari", description = "Diese Orcs haben noch nie zuvor einen Tauren gesehen, könnt Ihr das glauben? Wenn Hauptmann Kroghan nicht wäre, würden sie mich wahrscheinlich in diesem Moment zum Abendessen verschlingen!\n\nAber wo sind meine Manieren? Ich bin Ohlorn Fernreiser, herausragender Jäger! Ich gehöre zu Nesingwarys Expedition, die sich von Azeroth aus auf die Jagd nach Großwild hierher begeben hat. Wenn Ihr Euch für die Jagd interessiert, solltet Ihr meine Truppe in Nesingwarys Safari östlich von hier an den Grenzen zu den Zangarmarschen besuchen.", sourceObjective = "Ohlorn Fernreiser möchte, dass Ihr mit Shado 'Fitz' Fernreiser in Nesingwarys Safari in Nagrand sprecht.", completion = "Ich bin erleichtert zu hören, dass er in Sicherheit ist. Seid Ihr hier, um an der Jagd teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchfennkrise", description = "Die Kurenai und die Draenei sind nicht immer der gleichen Meinung, besonders nicht, wenn es um die Verirrten geht. Wir helfen den Verirrten, die sich an uns wenden, gerne, aber wir werden sie niemals verfolgen. Manche Draenei sind andererseits überzeugt davon, dass sie alle 'erlöst' werden müssen.\n\nEs gibt jedoch Zeiten, in denen sogar die Verirrten zu weit gehen, wie zum Beispiel der Dolchfennstamm. In ihrem Dorf im Westen hantieren sie mit Giften herum, lügen und betrügen, was für uns sehr unnatürlich ist.\n\nWir müssen dem ein Ende bereiten, bevor der bösartige Dolchfennstamm seinen Einfluss noch weiter ausbreiten kann.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn.", completion = "Ihr habt gute Arbeit geleistet, {name}. Keiner ist der Meinung, dass es noch Erlösung für den Dolchfennstamm gegeben hätte, aber ich glaube nicht, dass die Draenei in dieser Situation schnell genug gehandelt hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamms der Verirrten, wegen seiner brutalen Angriffe auf die Oreborzuflucht.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Kurenai und Draenei auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn westlich der Oreborzuflucht zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Ikuti eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Ikuti in der Oreborzuflucht.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Bemerkenswert! Es gab schon einige vor Euch, die das Kopfgeld gewinnen wollten, aber keiner von ihnen ist je zurückgekehrt. Es ist nicht schwer sich auszumalen, was ihnen wohl zugestoßen ist.\n\nIch bin sehr erleichtert, dass wir in Zukunft nichts mehr von Mummaki und seinem Gesindel zu befürchten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Häuptling Mummaki", description = "Gesucht: Häuptling Mummaki - Anführer des verdorbenen und degenerierten Dolchfennstamm der Verirrten, wegen seiner brutalen Angriffe auf Zabra'jin und seine Einwohner.\n\nDer Häuptling und seine Truppe von Auftragsmördern haben mehrere Späher und Boten auf dem Gewissen. Nur erfahrene Kämpfer sollten sich an sie heranwagen.\n\nReisenden wird nahe gelegt, die Gegend um Dolchfenn nordwestlich von Zabra'jin zu meiden.\n\nDas Kopfgeld kann bei Vorlage eines Beweises für das Ableben des Häuptlings bei Schattenjäger Denjai eingefordert werden.", sourceObjective = "Bringt Häuptling Mummakis Totem zu Schattenjäger Denjai.", progress = "Ihr wollt also das Kopfgeld für Häuptling Mummaki einfordern?", completion = "Ihr habt meinen Dank, {name}. Ich hatte mir schon überlegt, einen Teil der Garnison dorthin zu schicken und Mummaki selbst zu erledigen. Welche Folgen das jedoch für Zabra'jin gehabt hätte, ist schwer zu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Dolchfenn", description = "Von allen Stämmen der Verirrten in den Zangarmarschen ist der Dolchfennstamm der gerissenste und aggressivste. Er ist sehr gut organisiert und macht keinen Hehl daraus, dass er gerne die Kontrolle über alle Verirrten in den Marschen hätte.\n\nIhren Angriffen sind schon viele meiner Späher und Boten zum Opfer gefallen. Ich kann es mir nicht leisten, noch mehr Männer zu verlieren.\n\nWenn wir nicht bald handeln, werden sie die komplette Kontrolle über alle Straßen erlangen und Zabra'jin einkesseln.", sourceObjective = "Tötet 3 Auftragsmörder von Dolchfenn und 15 Matschwirbler von Dolchfenn und kehrt dann zu Schattenjäger Denjai in Zabra'jin zurück.", completion = "Ich glaube, Ihr habt ihnen eine ziemlich deutliche Botschaft zukommen lassen. Vielleicht haben meine Männer nun nicht mehr so viel Angst vor dem Dolchfennstamm. Oder sie schämen sich zumindest für ihren Mangel an Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Dunkle Portal", description = "Zwanzig Jahre lang stand das Dunkle Portal still - ein Symbol für längst vergangene Zeiten. Aber nun ist es nicht mehr still.\n\n<Reldorn sieht sich um.>\n\nIch habe nicht geglaubt, dass ich den heutigen Tag erleben werde, aber hier stehen wir nun und schauen tief in den Abgrund.\n\nAuf der anderen Seite des Portals sind wir in einem grausamen Krieg gefangen - ein Krieg, den wir nicht ohne Hilfe gewinnen können. Ihr müsst durch das Dunkle Portal reisen und unseren Truppen helfen, {class}.\n\nMeldet Euch umgehend bei Kommandant Duron. Er erwartet Euch in der Scherbenwelt...", sourceObjective = "Reist durch das Dunkle Portal und sucht Kommandant Duron. Er wartet auf der anderen Seite auf Eure Ankunft - in der Scherbenwelt.", completion = "Willkommen in der Scherbenwelt, {name} -- willkommen im Alptraum! Auch wenn das erste Expeditionskorps es unbeschadet hierher geschafft hat, versucht die Legion nun, das Portal zurückzuerobern und unsere Verstärkung daran zu hindern, es zu durchschreiten.\n\nIch würde Euch gerne hier einsetzen, aber unsere Truppen und die Soldaten der Horde können die Kolonnen der Legion, die diese Plattform erobern wollen, selbst zurückhalten.\n\nIhr müsst dorthin gehen, wo Ihr am meisten gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft in der Scherbenwelt", description = "Mit der Unterstützung der Allianz können meine Leute die Verteidigung hier aufrechterhalten, aber Ihr müsst dringend meinen Bericht zu General Krakork in Thrallmar bringen. Mit seiner Hilfe können wir diese Dämonen zurück in den Abgrund drängen, aus dem sie gekommen sind! Sprecht mit Vlagga Freyfeder auf der Anhöhe hinter uns. Sie wird Euch schnell auf den Weg dorthin bringen.", sourceObjective = "Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt.", progress = "Ich habe gesehen, wie Ihr mit Orion gesprochen habt - es muss eine wichtige Angelegenheit sein...", completion = "Ihr seid also Orions neuer Bote? Ich hoffe, es ergeht Euch besser als dem letzten, den er geschickt hat, {class}. Mit der vorrückenden Legion schafft Ihr es niemals zu Fuß nach Thrallmar. Sagt Bescheid und mein treuer Flügeldrache wird Euch sicher dorthin bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brennende Legion ausrotten", description = "Auch wenn dieses Land voller neuer, unbekannter Feinde ist, ist die Brennende Legion immer noch die größte Bedrohung für unsere Expedition. Einer meiner vertrauenswürdigsten Krieger, Unteroffizier Schädelbrecher, hat die Taktiken der Legion untersucht und versucht, das wahre Ziel der Legion in diesem Land herauszufinden. Ihr findet ihn bei der Versorgungskarawane außerhalb des südlichen Walls.\n\nUnd {name}, hütet Euch vor der Legion. Ihre Bösartigkeit darf nicht unterschätzt werden.", sourceObjective = "Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten.", completion = "Ihr habt sicher auf Eurem Flug vom Dunklen Portal die Krieger der Legion überall in der Landschaft gesehen. Auch wenn wir sie in der Schlacht am Berg Hyjal vor etwa 5 Jahren besiegt haben, haben diese verfluchten Dämonen immer noch nicht genug. Wenn sie auf eine Herausforderung aus sind, wird die Horde ihnen entsprechend antworten!\n\nWir Orcs haben mit der Legion mehr als nur eine Rechnung zu begleichen! Was ist mit Euch, {name}? Soll ich Euch von unserem Feind erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erstreckung der Zitadelle", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Späher, Gefreiter Imarion, losgeschickt, um ihre Vorgehensweise zu erkunden, aber er ist noch nicht mit seinem Bericht zurückgekehrt.\n\nImarion sollte sich auf das nördlichste Lager entlang des Südlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet ihn, {name}. Ohne seinen Bericht sitzen wir hier hilflos herum.", sourceObjective = "Durchsucht das nördlichste Lager entlang des Südlichen Bollwerks nach einer Spur von Gefreiter Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfunkenklamm", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords in der Teufelsfunkenklamm östlich von hier postiert. Sie sind für diese höllischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", sourceObjective = "Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", sourceObjectiveStatus = "unverified-source-field" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorposten: Häschersturz", description = "Eure Fähigkeiten in der Schlacht sind dem Oberkommando aufgefallen, {class}. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der herstehenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", completion = "Ihr habt also die Teufelsfunkenklamm aufgeräumt, was? Gut zu hören - wir brauchen Soldaten wie Euch, die sich kopfüber in die Schlacht stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Kommunikation unterbrechen", description = "Direkt im Osten liegt die Front der Legion. Die Front dient der Brennenden Legion als mobile Kommandobasis. Ihr könnt die Sender der Legion aus der Erde herausragen sehen. Mit ihrer Hilfe kommuniziert die Legion mit ihren Konstruktionslagern in der ganzen Scherbenwelt. Sie dienen ebenfalls als Schutzeinrichtung zur Verschlüsselung sämtlicher Übertragungen, sodass eine magische Überwachung nicht mehr möglich ist.\n\nIch möchte, dass Ihr diesen Sprengstoff nehmt und die Sender damit zerstört. Zerstört sie alle, {name}! Sie sind von Süden nach Norden an der Grenze der Front der Legion aufgereiht.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10126] = { id = 10126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsboss Nekroggs Befehle", description = "Die Anweisungen sind mit Kriegsboss Nekrogg unterzeichnet. Sie befehlen den Höllenorcs in diesem Lager, ihren menschlichen Gefangenen zum Verhör nach Süden zu bringen.\n\nLeutnant Amadi hat erwähnt, dass das Südliche Bollwerk über mehrere Höllenorclager verfügt. Vielleicht haben sie Gefreiter Imarion zum nächsten größeren Abschnitt des Walls Richtung Süden gebracht.\n\nDa dieser Befehl von Verhör spricht, scheint es den Höllenorcs wichtig zu sein, dass Gefreiter Imarion am Leben bleibt. Nehmt schnell ihre Spur auf, bevor sie es sich anders überlegen!", sourceObjective = "Reist entlang der westlichen Seite des Südlichen Bollwerks nach Süden und durchsucht das nächste Lager nach einer Spur von Gefreiter Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Das Band zerreißen", description = "Es wäre Vernachlässigung meiner Pflicht, wenn ich Euch nicht befehlen würde, die Dämonen an der Front der Legion, östlich von dieser Basis, zu vernichten.\n\nBeide Seiten der Front sind nach dem selben Muster aufgebaut: Teufelstreiber wandeln zwischen den Lagern der Legion hin und her, die von Zornwächtern bewacht werden. Die ganze Operation wird von einer Unterwerferin der Shivan beaufsichtigt. Tötet sie alle und überlasst Kazzak den Rest.\n\nUnd passt auf die patrouillierenden Teufelshäscher auf. Ich weiß, dass Ihr stark seid, aber diese Biester machen mit Euch kurzen Prozess.", sourceObjective = "Vorpostenkommandant To'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi'aziv tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10128] = { id = 10128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Soldat Imarion", description = "Die Spuren führen von Imarions Ausrüstung aus nach Süden, anscheinend entlang des Südlichen Bollwerks. Aus den Furchen lässt sich schließen, dass die Entführer es eilig hatten, ihn an den nächsten Ort zu bringen, aber warum?\n\nHat ihn dort jemand erwartet? Vielleicht Kriegsboss Nekrogg, der Anführer, der in den Befehlen, die Ihr weiter nördlich gefunden habt, erwähnt wurde?\n\nDas Schild und die Spuren werfen mehr Fragen auf, als sie beantworten, aber es scheint sicher, dass Ihr dort, wo Ihr Gefreiter Imarion findet, auch Kriegsboss Nekrogg finden werdet.", sourceObjective = "Setzt Euren Weg entlang des Südlichen Bollwerks fort und sucht nach dem Ort, an dem Kriegsboss Nekrogg Gefreiter Imarion gefangen hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tore Murketh und Shaadraz", description = "Wir haben die beiden Haupttransporter, mit denen die Brennende Legion ihre Verstärkung herbeiholt, ausgemacht: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie beide in Stücke sprengt!\n\nHier sind die Bomben, die Ihr dafür benötigt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht mit Schwadronskommandant Brack - er wird Euch einen Wyvern zur Verfügung stellen.", sourceObjective = "Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To'arch im Häschersturz zurück.", progress = "Wenn Ihr beim ersten Versuch verfehlt, startet einen neuen...", completion = "Das wird sie um Wochen zurückwerfen! Fantastische Arbeit, {name}. Die Legion hätte sicher nie mit so starkem Widerstand gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die westliche Flanke", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um die Ehrenfeste in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Die Ehrenfeste kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.", sourceObjective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10131] = { id = 10131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluchtplan", description = "Wie ich schon gesagt habe, hier rauszukommen wird nicht leicht. Kriegsboss Nekrogg mag vielleicht wie ein übergroßer Schläger aussehen, aber er ist kein Dummkopf.\n\nEr wird den Käfigschlüssel nicht aus den Augen lassen und kommt nicht aus seinem Turm auf dieser massiven Mauer heraus, bis er bereit ist, mich oder diese Orcfrau, die er gefangen hat, zu verhören.\n\nWir brauchen schon etwas Besonderes, um ihn aus diesen Mauern zu locken, aber ich habe einen Plan. Sucht einen der Grenadiere, die am Südlichen Bollwerk entlang patrouillieren, und bringt mir etwas von seinem Sprengstoff.", sourceObjective = "Tötet einen Grenadier des Lachenden Schädels und bringt seine primitive Sprengladung zu Gefreiter Imarion im Außenposten von Gor'gaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kolossale Bedrohung", description = "Seht Ihr diesen riesigen roten Kristall im Norden? Er ist vor Kurzem vom Himmel gefallen und hat dabei ein großes Erdbeben ausgelöst.\n\nAls wir hierher kamen, um den Grund für den Aufruhr zu erforschen, haben wir all die Kolosse hier gesehen, die zuvor noch nicht da waren.\n\nEs ist eindeutig etwas faul an dem Kristall und den Energien, die er ausstrahlt, aber ich habe keine Zeit dafür. Ich muss mich zuerst um diese Bergriesen kümmern.\n\nIch möchte, dass Ihr zum Himmelssturzgrat geht und Euch um sie kümmert.", sourceObjective = "Tötet 5 tobende Kolosse und kehrt dann zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", completion = "Gute Arbeit.\n\nWenn Ihr mich fragt, müssen wir einfach genug von diesen Kolossen töten, dann brauchen wir uns nicht mehr um diese merkwürdigen Kristall in der Mitte kümmern.\n\nHier, nehmt eines hiervon als Belohnung der Expedition des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[10133] = { id = 10133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tötet den Boten", description = "Euer Geschick bereitet der Legion große Schwierigkeiten, {name}. Meine Späher haben mich informiert, dass die Legion Kuriere benutzt, um untereinander zu kommunizieren. Wir haben es geschafft, ihre Truppen vom Hauptlager abzuschneiden!\n\nWorum ich Euch nun bitte ist mehr, als ich von einem normalen Soldaten verlangen würde.\n\nDer Kurier der Legion reist zwischen den Teichen von Aggonar und dem Konstruktionsbasis: Mageddon, nördlich von hier, hin und her. Ihr müsst den Kurier bei Mageddon abfangen, ihn erledigen und mit dem Schriftwechsel der Legion zu mir zurückkehren.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr Arix'maladish findet und tötet und den Schriftwechsel der Legion besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise des purpurnen Kristalls", description = "Als der Koloss Eurem Angriff zum Opfer fällt, bemerkt Ihr, dass er ein rotes Kristallfragment in der Hand hält.\n\nIn der Hand des Riesen schien es sehr klein und unauffällig, aber für Euch ist das Stück sehr schwer zu tragen. Es sieht sehr verdächtig nach einem Stück des riesigen roten Kristalls in der Mitte des Grats aus.\n\nDies ist ganz sicher ein Hinweis auf die merkwürdigen Dinge, die hier geschehen. Ihr seid Euch sicher, dass die Druiden beim Posten des Cenarius im Süden den Splitter sehen wollen.", sourceObjective = "Bringt den Purpurkristallsplitter zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel.", progress = "Das ist ein ganz schön großer Kristall, den Ihr da habt. Habt Ihr ihn von den Kolossen im Grat?\n\nLasst mich ihn anschauen.", completion = "Hm, für mich sieht es einfach wie ein großer Klumpen ungeschliffenen Kristalls aus.\n\nZugegeben, ich fühle eine kranke, böse Aura, die von ihm ausgeht, aber das ist nicht gerade mein Spezialgebiet. Ich bin nur hier, um die Bedrohung durch die Bergriesen aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10135] = { id = 10135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Seid der Bote", description = "Ich bin nur ein Feldkommandeur, {class}. Die Befugnis, auf solche Informationen hin zu handeln, fällt nur unserem Anführer, Nazgrel, zu. Ihr müsst den Schriftwechsel nach Thrallmar zu ihm bringen. Reitet schnell wie der Wind, Soldat. Lasst Euch durch nichts aufhalten!", sourceObjective = "Bringt den Schriftwechsel der Legion zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausame Pläne", description = "Magister Blutfalke hat endlich den Schriftwechsel der Legion, den Ihr gefunden habt, entziffert. Wie es aussieht, handelt es sich dabei um Angriffspläne, die von einem Leutnant des Hochlords Kazzak geschickt wurden - Arazzius der Grausame. Offensichtlich hat Arazzius den Befehl über die Bodentruppen auf der Höllenfeuerhalbinsel. Es ist an der Zeit, dass wir seinen Befehl beenden, {name}. Vernichtet ihn mit größter Vorsicht.\n\nBegebt Euch zu den Teichen von Aggonar und setzt dem so genannten 'Legionslord' ein Ende. Heute fordert die Horde die Höllenfeuerhalbinsel zurück. Die Legion möge verdammt sein.", sourceObjective = "Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück.", completion = "Alle kommenden Generation werden diesen Tag bejubeln, {name}. Sie werden von Eurem Heldenmut singen. Ich wünschte, Thrall wäre hier, um diesen Sieg mit uns zu feiern. Die Legion liegt am Boden, und die Höllenfeuerhalbinsel gehört wieder der Horde! Vielleicht besteht doch noch Hoffnung für diese verwüstete Welt und unser Volk auf ihr.\n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10137] = { id = 10137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kriegsboss provozieren", description = "Der Erfolg des Plans hängt von der Qualität des Sprengstoffs ab...\n\nSo ungern ich mich auch auf etwas verlasse, das von einem Orc hergestellt wurde, ist dies meine einzige Möglichkeit hier rauszukommen. Nehmt dies und werft es gegen das Banner, das vom Turm da oben weht.\n\nWenn es explodiert wird Kriegsboss Nekrogg es sich nicht nehmen lassen, ein Exempel an dem Störenfried zu statuieren. Tötet ihn und nehmt den Schlüssel, um meinen Käfig zu öffnen. Viel Erfolg, {name}.", sourceObjective = "Benutzt die primitiven Sprengladungen um einen Tumult zu veranstalten und Kriegsboss Nekrogg aus seinem Turm zu locken. Tötet ihn, besorgt Nekroggs Schlüssel und öffnet damit Gefreiter Imarions Käfig. Wenn Ihr Gefreiter Imarion befreit habt, meldet Euch bei Leutnant Amadi.", sourceObjectiveStatus = "unverified-source-field" }
quests[10138] = { id = 10138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf wessen Befehl hin?", description = "Eines ist klar, {name}: wir können nicht so weitermachen. Die Höllenorcs haben uns eingekreist, und sobald wir sie erledigen, nehmen gleich mehrere ihren Platz ein. Wir können nicht hoffen, dass wir diesen Krieg gewinnen können, indem wir uns hinter den zerschlagenen Mauern der Ehrenfeste verstecken und die Tage bis zu unserem Tod durch die Hand der Höllenorcs zählen.\n\nIhr habt beeindruckende Arbeit geleistet und uns vor den schlimmsten Angriffen der Höllenorcs bewahrt, aber jetzt müsst Ihr Euch den Weg entlang des Pfads des Ruhmes freikämpfen und herausfinden, wer diese Angriffe steuert.", sourceObjective = "Tötet 20 Grunzer der Zerschmetterten Hand, 10 Hexenmeister der Zerschmetterten Hand und besorgt Euch Drillmeister Zurok's Anweisungen. Kehrt dann zu Leutnant Amadi im westlichen Wachturm der Ehrenfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10139] = { id = 10139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beseitigung des Kommandanten", description = "So wie ich das sehe, war Drillmeister Zurok die rechte Hand des Anführers der Höllenorcs auf der Höllenfeuerhalbinsel, Truppenkommandant Gorax.\n\nDieser Gorax ist anders als die gewöhnlichen Schläger der Höllenorcs. Ich bewundere fast, wie er uns schon so lange in der Defensive halten konnte.\n\nZuroks Befehle deuten an, dass Gorax' Kommandozentrale am Ende des Pfads des Ruhms liegt, dort, wo die Mauern der Zitadelle auf das Nördliche Bollwerk treffen. Ich habe keine Ahnung, was Euch dort erwartet, {name}, aber Ihr solltet besser mit ein paar Gefährten reisen.", sourceObjective = "Tötet Truppenkommandant Gorax und meldet Euch dann bei Leutnant Amadi im westlichen Turm der Ehrenfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10140] = { id = 10140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zur Ehrenfeste", description = "Wenn Ihr bereit seid, werde ich Euch einen Flug direkt zur Ehrenfeste besorgen.\n\nSprecht dort mit Marschall Isildor und gebt ihm Durons Bericht. Er wird sich freuen, einen weiteren Rekrut aus der Heimat zu sehen, und ich bin mir sicher, dass die Informationen in diesem Bericht sehr wichtig sind!", sourceObjective = "Fliegt zur Ehrenfeste und übergebt Marschall IsildorDurons Bericht.", progress = "Dem Licht sei Dank, dass Ihr heil hier angekommen seid. Die Ehrenfeste benötigt alle erfahrenen Krieger, die sie bekommen kann.", completion = "Unsere Expedition zu dieser verlassenen, zerschlagenen Welt wäre fast zum Stillstand gekommen, {name}. Wir haben mehr Widerstand erfahren, als wir dachten.\n\nAls ob die Brennende Legion nicht schon schlimm genug wäre, gibt es in diesen Ländern Schrecken, die wir noch nie zuvor gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10141] = { id = 10141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergeburt der Brennenden Legion", description = "Als die Brennende Legion in Azeroth eingefallen ist, war sie hier in der Scherbenwelt nicht untätig. Wir haben ihre Bewegungen über die Jahre verfolgt, aber ihre letzte Tat, {class}, ist schlimmer als alles, was wir je gesehen haben.\n\nSprecht mit Unteroffizier Altumus in der Nähe der Östlichen Versorgungskarawane. Er hat die Eindringlinge beobachtet und weiß vielleicht mehr über ihre Pläne.\n\nSeid schnell und passt auf, {name} - die Brennende Legion darf auf keinen Fall unterschätzt werden.", sourceObjective = "Sprecht mit Unteroffizier Altumus bei der Östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten.", completion = "Truppenkommandant Danath hat meine Anfrage nach Verstärkung wohl etwas falsch verstanden. Ihr seht zwar fähig aus, aber... ich habe um ein komplettes Bataillon gebeten!\n\nWisst Ihr, wir haben da ein kleines Dämonenproblem.", sourceObjectiveStatus = "unverified-source-field" }
quests[10142] = { id = 10142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Pein", description = "Verdammnislord Kazzak hat das Kommando über die Brennende Legion in der Scherbenwelt. Da wir Kazzak nicht direkt angreifen können - noch nicht - müssen wir zunächst seine Leutnants, die die Truppen vom Boden aus kommandieren, auslöschen.\n\nSie haben Schreckenslords am Pfad der Pein östlich von hier postiert. Sie sind für diese teuflischen Stürme, die auf uns herabprasseln, verantwortlich. Sie und ihre Diener zu vernichten wäre ein schwerer Schlag für die Legion.", sourceObjective = "Unteroffizier Altumus bei der Östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet.", progress = "Die Ehrenfeste ist sicher, solange die Bogenschützen unsere Himmel schützen.", completion = "Ausgezeichnete Arbeit, Soldat. Die Häufigkeit der Angriffe wird nun sicher nachlassen - zumindest bis sie neue Schreckenslords schicken.\n\nNun zu den schlechten Nachrichten: ich habe Eure neuen Befehle...", sourceObjectiveStatus = "unverified-source-field" }
quests[10143] = { id = 10143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsposten", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, {class}. Sie wollen Euch an die Front zu Rohamus' Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 400 Schritte nach Osten, durch das Tal der Knochen, bis Ihr auf einen zerstörten Teufelshäscher stoßt. Ihr findet den Expeditionsposten dort, wo einst ein Lager der Legion war. Wenn Ihr angekommen seid, meldet Euch bei Vorpostenkommandant Königstein.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet euch bei Vorpostenkommandant Königstein im Expeditionsposten.", completion = "Schön Euch zu treffen, Soldat.\n\nGenug gequatscht... nun hört zu -- Ich habe eine wichtige Mission für Euch und ich möchte, dass Ihr sie erfüllt... und überlebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[10144] = { id = 10144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verstärkung abschneiden", description = "Direkt im Nordosten liegt die Front der Legion. Entlang der Front befinden sich die infernalen Portale, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören, {name}!\n\nNehmt diesen Zünder. Er wurde in Area 52 hergestellt und benutzt die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Grimh und Portal Kaalez und haltet nach dämonischen Runensteinen Ausschau. Wenn Ihr genug Steine beisammen habt, benutzt den Zünder, um die Steine in den Portalen zu sprengen... und dann genießt das Feuerwerk!\n\nGeht, {name}, und kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", sourceObjective = "Besiegt die Feinde um Portal Grimh und Portal Kaalez herum, um dämonische Runensteine zu sammeln.\n\nBenutzt Königsteins Zünder in Portal Grimh und Portal Kaalez.\n\nKehrt danach mit dem Zünder zu Vorpostenkommandant Königstein zurück.", progress = "Ich wünschte, ich hätte die Feuer sehen können. Dieser Sprengstoff hat mächtig Dampf!", completion = "Gut gemacht, {name}. Die Zerstörung der Portale wird den Nachschub an Verstärkung für die Legion für eine Weile bremsen!\n\nAber noch können wir uns nicht ausruhen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10146] = { id = 10146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tor Murketh und Tor Shaadraz", description = "Westlich des Dunklen Portals befinden sich zwei riesige Transporter: Tor Murketh und Tor Shaadraz.\n\nWenn Ihr den Pfad des Ruhmes nach Osten hinaufschaut, könnt Ihr sie an beiden Seiten der Straße erkennen. Ich möchte, dass Ihr sie in Stücke sprengt!\n\nHier sind die Bomben, die Ihr benutzen sollt. Sie wurden speziell von einem Goblin in Area 52 entworfen. Sprecht nun mit Schwadronskommandant Dabir'ee - er wird Euch einen Greifen zur Verfügung stellen und Euch losschicken.", sourceObjective = "Sprecht mit Schwadronskommandant Dabir'ee, bombardiert Tor Murketh und Tor Shaadraz und kehrt dann zu Vorpostenkommandant Wa'ppun am Expeditionsposten zurück.", progress = "Dies ist ein wichtiger Auftrag, {name}. Ich würde ihn nicht an irgendjemanden vergeben.", completion = "Das wird sie um Wochen zurückwerfen, kein Zweifel! Ihr habt mir gerade ungewöhnlich gute Laune verschafft, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10147] = { id = 10147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Tötet den Boten", description = "Euer Geschick bereitet der Legion große Schwierigkeiten, {name}. Meine Späher haben mich informiert, dass die Legion Kuriere benutzt, um untereinander zu kommunizieren. Wir haben es geschafft, ihre Truppen vom Hauptlager abzuschneiden!\n\nWorum ich Euch nun bitte ist mehr, als ich von einem normalen Soldaten verlangen würde.\n\nDer Kurier der Legion reist zwischen den Teichen von Aggonar und dem Konstruktionsbasis: Mageddon, nördlich von hier, hin und her. Ihr müsst den Kurier bei Mageddon abfangen, ihn erledigen und mit dem Schriftwechsel der Legion zu mir zurückkehren.", sourceObjective = "Vorpostenkommandant Königstein im Expeditionsposten auf der Höllenfeuerhalbinsel möchte, dass Ihr Arix'maladish findet und tötet und den Schriftwechsel der Legion besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10148] = { id = 10148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Seid der Bote", description = "Ich bin nur ein Feldkommandeur, {class}. Die Befugnis, auf solche Informationen hin zu handeln, fällt nur unserem Anführer, Truppenkommandant Danath, zu. Ihr müsst den Schriftwechsel zur Ehrenfeste zu ihm bringen. Reitet schnell wie der Wind, Soldat. Lasst Euch durch nichts aufhalten!", sourceObjective = "Bringt den Schriftwechsel der Legion zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10149] = { id = 10149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Beendet alles, seid alles", description = "Wisst Ihr, was passiert wäre, wenn Ihr den Boten nicht abgefangen hättet, {name}?\n\n<Danath nickt.>\n\nDie gesamte Armee der Legion des Höllenfeuers hätte vor unserer Tür gestanden. Einen solchen Angriff hätten wie niemals überlebt.\n\nEs gibt nur eine Möglichkeit zu verhindern, dass diese Befehle jemals die Front erreichen. Ihr müsst zu den Teichen von Aggonar, westlich von hier, reisen und diesen Arazzius töten.\n\nWenn Ihr das tut, werde ich Euch eine Auszeichnung zukommen lassen.", sourceObjective = "Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Arazzius den Grausamen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10150] = { id = 10150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erstreckung der Zitadelle", description = "Jeden Tag öffnen sich die Tore der Höllenfeuerzitadelle und noch mehr Höllenorcs strömen heraus und in die Lager, die sie entlang des Bollwerks südlich der Zitadelle errichtet haben.\n\nIch habe einen meiner besten Spurenleser, Späherin Makha, losgeschickt, um ihre Vorgehensweise zu erkunden, aber sie ist noch nicht mit ihrem Bericht zurückgekehrt.\n\nMakha sollte sich auf das nördlichste Lager entlang des Nördlichen Bollwerks, nahe bei seiner Verbindung zur Zitadelle, konzentrieren. Findet sie, {name}. Ohne ihren Bericht sitzen wir hier hilflos herum.", sourceObjective = "Durchsucht das nördlichste Lager entlang des Nördlichen Bollwerks nach einer Spur von Späherin Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10151] = { id = 10151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsboss Nekroggs Befehle", description = "Die Anweisungen sind mit Kriegsboss Nekrogg unterzeichnet. Sie befehlen den Höllenorcs in diesem Lager, ihren menschlichen Gefangenen zum Verhör nach Süden zu bringen.\n\nSchattenjäger Ty'jin hat erwähnt, dass das Nördliche Bollwerk über mehrere Höllenorclager verfügt. Vielleicht haben sie Späherin Makha zum nächsten größeren Abschnitt des Walls Richtung Süden gebracht.\n\nDa dieser Befehl von Verhör spricht, scheint es den Höllenorcs wichtig zu sein, dass sie am Leben bleibt. Nehmt schnell ihre Spur auf, bevor sie es sich anders überlegen!", sourceObjective = "Reist entlang der westlichen Seite des Nördlichen Bollwerks nach Süden und durchsucht das nächste Lager nach einer Spur von Späherin Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10152] = { id = 10152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die westliche Flanke", description = "Zusätzlich zu den anderen Anweisungen werden die Orc in den Befehlen angewiesen, ihre Ausrüstung und Verpflegung für einen Angriff vorzubereiten.\n\nNach den Plänen sollen Kriegsboss Nekroggs Mannen sich zu einer westlichen Flanke formieren, um Thrallmar in die Zange zu nehmen.\n\nDa die Garnison der Feste sich auf die Verteidigung der östlichen Seite konzentriert, wäre ein Angriff von Westen fatal. Thrallmar kann nur gehalten werden, wenn der Angriff von Westen niemals stattfindet.", sourceObjective = "Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10153] = { id = 10153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Späherin Makha", description = "Die Spuren führen von Makhas Ausrüstung aus nach Süden, anscheinend über den Pfad des Ruhms. Aus den Furchen lässt sich schließen, dass die Entführer es eilig hatten, sie an den nächsten Ort zu bringen, aber warum?\n\nHat sie dort jemand erwartet? Vielleicht Kriegsboss Nekrogg, der Anführer, der in den Befehlen, die Ihr weiter nördlich gefunden habt, erwähnt wurde?\n\nDas Schild und die Spuren werfen mehr Fragen auf, als sie beantworten, aber es scheint sicher, dass Ihr dort, wo Ihr Späherin Makha findet, auch Kriegsboss Nekrogg finden werdet.", sourceObjective = "Setzt Euren Weg über den Pfad des Ruhms fort und sucht nach dem Ort, an dem Kriegsboss Nekrogg Späherin Makha gefangen hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[10154] = { id = 10154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluchtplan", description = "Wie ich schon gesagt habe, hier rauszukommen wird nicht leicht. Kriegsboss Nekrogg mag vielleicht wie ein übergroßer Schläger aussehen, aber er ist kein Dummkopf.\n\nEr wird den Käfigschlüssel nicht aus den Augen lassen und kommt nicht aus seinem Turm auf dieser massiven Mauer heraus, bis er bereit ist, mich oder diese Orcfrau, die er gefangen hat, zu verhören.\n\nWir brauchen schon etwas Besonderes, um ihn aus diesen Mauern zu locken, aber ich habe einen Plan. Sucht einen der Grenadiere, die am Südlichen Bollwerk entlang patrouillieren, und bringt mir etwas von seinem Sprengstoff.", sourceObjective = "Tötet einen Grenadier des Lachenden Schädels und bringt seine primitive Sprengladung zu Späherin Makha im Außenposten von Gor'gaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10155] = { id = 10155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kriegsboss provozieren", description = "Der Erfolg des Plans hängt von der Qualität des Sprengstoffs ab...\n\nSo ungern ich mich auch auf etwas verlasse, das von einem Höllenorc hergestellt wurde, ist dies meine einzige Möglichkeit hier rauszukommen. Nehmt dies und werft es gegen das Banner, das vom Turm da oben weht.\n\nWenn es explodiert wird Kriegsboss Nekrogg es sich nicht nehmen lassen, ein Exempel an dem Störenfried zu statuieren. Tötet ihn und nehmt den Schlüssel, um meinen Käfig zu öffnen. Viel Erfolg, {name}.", sourceObjective = "Benutzt die primitive Sprengladung um einen Tumult zu veranstalten und Kriegsboss Nekrogg aus seinem Turm zu locken. Tötet ihn, besorgt Nekroggs Schlüssel und öffnet damit Späherin Makhas Käfig. Wenn Ihr Späherin Makha befreit habt, meldet Euch bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10156] = { id = 10156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf wessen Befehl hin?", description = "Eines ist klar, {name}: wir können nicht so weitermachen. Die Höllenorcs haben uns eingekreist, und sobald wir sie erledigen, nehmen gleich mehrere ihren Platz ein. Wir können nicht hoffen, dass wir diesen Krieg gewinnen können, wenn unsere Streitkräfte zweigeteilt sind und sich im ständigen Kampf mit den Höllenorcs und den Dämonen der Legion befinden.\n\nIhr habt beeindruckende Arbeit geleistet und uns vor den schlimmsten Angriffen der Höllenorcs bewahrt, aber jetzt müsst Ihr Euch den Weg entlang des Pfads des Ruhmes freikämpfen und herausfinden, wer diese Angriffe steuert.", sourceObjective = "Tötet 20 Grunzer der Zerschmetterten Hand, 10 Hexenmeister der Zerschmetterten Hand und besorgt Euch Drillmeister Zurok's Anweisungen. Kehrt dann zu Steingardist Ambelan im Rückenbrechergrat zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10157] = { id = 10157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beseitigung des Kommandanten", description = "So wie ich das sehe, war Drillmeister Zurok die rechte Hand des Anführers der Höllenorcs auf der Höllenfeuerhalbinsel, Truppenkommandant Gorax.\n\nDieser Gorax ist anders als die gewöhnlichen Schläger der Höllenorcs. Ich bewundere fast, wie er uns schon so lange in der Defensive halten konnte.\n\nZuroks Befehle deuten an, dass Gorax' Kommandozentrale am Ende des Pfads des Ruhms liegt, dort, wo die Mauern der Zitadelle auf das Nördliche Bollwerk treffen. Ich habe keine Ahnung, was Euch dort erwartet, {name}, aber Ihr solltet besser mit ein paar Gefährten reisen.", sourceObjective = "Tötet Truppenkommandant Gorax und meldet Euch dann bei Schattenjäger Ty'jin in Thrallmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10158] = { id = 10158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Blutenden Auges", description = "Die orcischen Ruinen von Zeth'Gor im Südosten dienen als Basislager für die immer weiter steigende Flut von Höllenorcs, die aus der Höllenfeuerzitadelle strömt.\n\nSchattenjäger Ty'jin hat mich geschickt, um den Außenposten und seine merkwürdigen Bewohner zu beobachten.\n\nEtwas hat diese Orcs auf eine Art und Weise verändert, die ich noch nie zuvor gesehen habe. Wir müssen alles in unserer Macht Stehende tun, um zu verhindern, dass sie noch stärker werden. Geht nach Zeth'Gor und zerstört sämtliche Vorräte, die Ihr dort finden könnt.", sourceObjective = "Zerstört 6 Stapel Vorräte des Blutenden Auges und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10159] = { id = 10159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet den Dornnebelhügel sauber!", description = "Wir kämpfen schon die ganze Zeit, um den Pass durch den Dornnebelhügel von den Verheerern freizuhalten. Es wäre schlecht, wenn wir ganz von der Zuflucht in den Zangarmarschen abgeschnitten wären.\n\nWir möchten die Tiere nicht vertreiben, aber wir haben kaum einen andere Wahl, sie werden Reisenden in dieser Gegend gegenüber immer aggressiver.\n\nLöscht ein paar von den Felshetzern aus, wenn Ihr könnt.", sourceObjective = "Tötet 8 Dornenfangfelshetzer und 8 Dornenfanggiftspucker und kehrt dann zu Mahuram Starkhuf im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück.", progress = "Wie läuft es mit der Bereinigung des Dornnebelhügels?", completion = "Jetzt, da die Verheerer fort sind, können die Reisenden der Zuflucht des Cenarius in den Zangarmarschen wieder sicher vorankommen.\n\nDie Expedition des Cenarius ist Euch etwas schuldig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10160] = { id = 10160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind kennen", description = "Es gibt Gerüchte, dass eine neue Brut von Orcs aufkommt. Größer, bösartiger und listiger als die Rüpel, mit denen wir uns sonst herumschlagen müssen. Wenn diese Gerüchte wahr sind, müssen unsere Streitkräfte, die ohnehin schon überansprucht sind, sich bis über ihre Grenzen hinaus belasten.\n\nIch habe meinen Leutnant, Amadi, damit betraut, die Sache zu untersuchen. Wenn Ihr uns in dieser dunklen Stunde beistehen wollt, dann meldet Euch bei ihr. Sie befindet sich in dem zerbrochenen Turm im Westen der Feste.\n\nUnd {name}, seid vorsichtig da draußen. Ihr stürzt Euch in eine neue, gefährliche Welt.", sourceObjective = "Sprecht mit Leutnant Amadi im alten Wachturm im Westen der Ehrenfeste.", completion = "<Leutnant Amadi nickt.>\n\nGut, wir können jede Hilfe gebrauchen. Die zunehmende Orcbevölkerung am südlichen Bollwerk bereitet mir Kopfschmerzen. Ich habe einen Späher losgeschickt, um sie zu erkunden, aber er ist noch nicht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10161] = { id = 10161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Notfall...", description = "Bei einem Notfall ist es die Aufgabe des Piloten, einen kühlen Kopf zu bewahren, besonders, wenn die einzigen Befehle, die der Kopilot befolgt, die seines Magens sind.\n\nDie gute Nachricht ist, dass wir nicht tagelang darauf warten müssen, dass uns Ersatzteile geliefert werden. Die schlechte Nachricht ist, dass die Ersatzteile überall von hier bis zum Tal der Knochen im Osten verstreut sind.\n\nDie andere schlechte Nachricht? Die Ersatzteile sind nicht so leicht ersetzbar. Sie, äh, sind bei unserem schnellen Abgang abgefallen. Könntet Ihr mir vielleicht helfen, genügend davon wieder vom Boden aufzusammeln?", sourceObjective = "Sammelt 30 Zeppelintrümmer und bringt sie zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle.", progress = "Habt Ihr genügend Teile gefunden? Wenn nicht muss ich die Bratpfanne verwenden, mit der Legassi die ganze Zeit herumwedelt. Dann muss ich den Zeppelin in die \"Fliegende Bratpfanne\" umbenennen.", completion = "Einige davon sind in einem ziemlich schlechten Zustand, aber ich sollte damit zurechtkommen. Es braucht nur ein wenig kreative Ingenieurskunst und es wird sicher klappen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10162] = { id = 10162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Abyssische Untiefe", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Wyvern und zerstört das verdammte Ding!\n\nHier sind die Bomben. Sprecht mit Schwadronskommandant Brack wenn Ihr zum Abflug bereit seid.", sourceObjective = "Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, {name}. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Flügeldrachenzerstörern!", sourceObjectiveStatus = "unverified-source-field" }
quests[10163] = { id = 10163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Abyssische Untiefe", description = "Jetzt, da Ihr Eure Flügel habt, habt Ihr vielleicht Interesse an einem weiteren Bombardement?\n\nDieses Mal haben wir die Hauptproduktionsstätte der Legion isoliert, hinter den Konstruktionslagern im Norden. Schwingt Euch auf einen Greifen und zerstört das verdammte Ding!\n\nHier sind Eure Bomben. Sprecht mit Greifnerin Heulwind wenn Ihr zum Abflug bereit seid.", sourceObjective = "Schwadronskommandant Greifgar im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet.", progress = "Zeigt Ihnen, dass nicht einmal die Himmel sicher sind!", completion = "Ihr fliegt, als hättet Ihr Euer Leben lang nichts anderes getan, {name}. Hervorragende Vorstellung! Und nicht einmal ein kleiner Kratzer an den Greifenzerstörern!", sourceObjectiveStatus = "unverified-source-field" }
quests[10164] = { id = 10164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird gut", description = "Ihr habt ein ganz schönes Abenteuer hinter Euch, {name}. Und das noch bevor Ihr überhaupt einen Fuß in den Auchenaikrypta gesetzt habt.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden oder Teil eines der bösartigen Experimente in der Nekromantie von Exarch Maladaar. Während Levixus durch Eure Hand gestorben ist, lebt Maladaar immer noch weiter und quält die Geister in der Krypta.\n\nWorum ich Euch bitte ist ganz einfach. Geht in die Auchenaikrypta und tötet Exarch Maladaar, damit die gefangenen Geister endlich Frieden finden können.", sourceObjective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", completion = "Ihr habt es geschafft, {name}! Die Geister sind frei!\n\nAuch wenn ich keinen weltlichen Körper habe, kann ich Euch trotzdem mit Gegenständen aus der Geisterwelt belohnen. Benutzt sie mit Vorsicht, da diese Gegenstände oft unberechenbar sind und Ihrem Träger großen Schaden zufügen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10165] = { id = 10165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Konkurrenz untergraben", description = "Dieser Shaffar ist ganz schön gerissen, das muss man ihm lassen... Er hat es geschafft, das Konsortium fern zu halten, während er in aller Seelenruhe diese Gruft all ihrer Schätze beraubt. Ich glaube nicht, dass diese Dummköpfe es tatsächlich schaffen, durch seine Verteidigung zu brechen, deshalb mache ich Euch einen Vorschlag, {race}.\n\nDringt in die Managruft ein und tötet den Nexusprinzen Shaffar. Bringt mir seine Körperbandagen als Beweis Eurer Tat, und ich werde Euch fürstlich belohnen.", sourceObjective = "Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt.", progress = "Ich teile nicht gerne.", completion = "Und wieder ein Konkurrent weniger... Ihr leistet gute Arbeit für ein Wesen aus Fleisch und Blut, {race}. Sucht mich auf, wenn Ihr je im Nethersturm sein solltet. Ich wohne auf der Sturmsäule.", sourceObjectiveStatus = "unverified-source-field" }
quests[10166] = { id = 10166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißborkes Erinnerung", description = "Dieser Anhänger bringt Erinnerungen an eine andere Zeit zurück. Eine bessere Zeit.\n\nLeider sind Erinnerungen das letzte, was ich jetzt gebrauchen kann.\n\nIch möchte, dass Ihr dies beim Runenstein im Versengten Hain vergrabt. Dort habe ich den Treantältesten zum ersten Mal getroffen. Bettet die Erinnerung an meinen alten Freund in Frieden.", sourceObjective = "Larianna Flusswind möchte, dass Ihr Weißborkes Anhänger beim Runenstein im versengten Hain vergrabt.", progress = "Ihr seid zurück, {name}. Habt Ihr denn noch nicht genug getan?", completion = "Ich gehöre dieser Welt nicht länger an und muss mich geschlagen geben. Das Land hat sich auf ewig verändert, und nichts wird mehr sein wie früher.\n\nLasst den Anhänger hier bei mir, {name}. Eines Tages vielleicht, wenn die Elfen schon lange nicht mehr sind, wird ein Baum an genau diesem Ort wachsen - in einem versengten Wald und zwischen toten Treants.", sourceObjectiveStatus = "unverified-source-field" }
quests[10167] = { id = 10167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun...", description = "Tief in der Auchenaikrypta befindet sich ein Grab: ein Grab, dass keinesgleichen in den Zerschlagenen Weiten findet. Aus diesem Grab, dem ersten Grab, wurde das riesige Mausoleum von Auchindoun geboren.\n\nIhr müsst zu der Auchenaikrypta reisen und dieses Grab finden. Tötet den Grabwächter und befreit den Geist, der darin gefangen ist. Der Geist ist der Schlüssel...", sourceObjective = "Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D'ore zu befreien.", completion = "Die Erinnerung ist sehr lebendig, {name}. Meine Energien wurden bei dem Aufprall vollkommen ausgelaugt. Ich war nichts als ein kleiner Fleck von Leerenergien, als Prophet Velen und seine Draeneifreunde meine Überreste geborgen und hierher gebracht haben. Nach einer Zeremonie wurde meine geschwächte Form hier in diesem Sarkophag zur Ruhe gebettet. Ich habe mich nun für fast tausend Jahre regeneriert. Der Kreis ist fast geschlossen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10168] = { id = 10168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was die Seele sieht", description = "Seit mehreren Jahrhunderten verbinden sich die Geister von Auchindoun nun mit meiner getrübten Essenz. Viele der Katastrophen, die diese Krypta heimgesucht haben, sind auf meinen geschwächten Zustand zurückzuführen.\n\nUnglücklicherweise kann nichts diesen Kreis aufhalten. Das gehört zur Natur der Naaru - ohne die Leere kann das Licht nicht existieren.\n\nEure einzige Möglichkeit besteht darin, die Geister von Nagrand zu vernichten, bevor sie sich in Wesen der Leere verwandeln. Benutzt die Seelenspiegel, die sich überall in der Krypta befinden, um sie zu befreien...", sourceObjective = "Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen von Nagrand zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können.\n\nKehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid.", progress = "<Mutter Kashur ist sichtlich aufgebracht.>\n\nDiese Naaru sind weiser als alle Lebewesen in dieser Welt.", completion = "Ihr habt eine lange und gefährliche Reise hinter Euch und Leben und Gesundheit für die Sicherheit der Mag'har und den Frieden unserer Ahnen aufs Spiel gesetzt. Ich bin Euch dafür dankbarer, als tausend Worte sagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10169] = { id = 10169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Würde verlieren", description = "Die Aldor haben sich heute das Wohlwollen der Sha'tar verdient. Als ob das etwas Überraschendes wäre!\n\nSchaut nur, wie sie nur ein paar Fuß von A'dal entfernt mit ihrer tollen Beinarbeit angeben. Könnten sie sich wohl noch mehr bemühen, sich bei den Naaru einzuschmeicheln?\n\nHerold Haronems Schützen sind so engagiert, dass sie sogar ihren eigenen Kochtopf mitbringen, um keine langen Pausen zum Mittagessen machen müssen. Das kann nicht ohne Strafe vonstatten gehen, {name}.\n\nIch möchte, dass Ihr diese Phiole in ihr Essen kippt. Die Folgen sollten... sehr amüsant sein.", sourceObjective = "Magister Falris in Shattrath möchte, dass Ihr die Phiole mit Beruhigungsserum zur Terrasse des Lichts bringt und sie in den Kochtopf von Haronems Regiment schüttet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10170] = { id = 10170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Großmutter", description = "Kehrt zu Großmutter Geyah in Garadar zurück und berichtet ihr von Eurem Sieg, {name}. Das wird den Mag'har sicher neuen Mut geben. Vielleicht erwacht sogar der junge Höllschrei aus seiner Melancholie.", sourceObjective = "Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah.", completion = "Ich möchte, dass Ihr diese Nachrichten persönlich zu Garrosh bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10171] = { id = 10171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der untröstliche Häuptling", description = "Ihr habt so viel für die Mag'har getan, {name}. Alle wissen von Euren Taten, auch Garrosh. Geht nun zu ihm und erzählt ihm von eurem letzten Erfolg. Sagt ihm, was Ihr für ihn und sein Volk getan habt. Eure Worte werden ihn sicher trösten.", sourceObjective = "Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht.", completion = "Alle sind stolz. Stolz dass unser Volk einen weiteren Winter überleben wird. Aber danach? Was ist danach?\n\nVielleicht solltet Ihr diesen Klan anführen, {name}. Vielleicht ist es mir dann vergönnt zu sterben, wenn die Großmutter dahinscheidet. Vergönnt, die Schande meines Familiennamens auszulöschen. Ich sehne mich nach diesem Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10172] = { id = 10172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt keine Hoffnung", description = "Ihr seid <ein ehrenwerter/eine ehrenwerte:r> {race}, {name}. Ihr habt viel für die Mag'har getan. Niemand könnte Eure Dienste für mein Volk je leugnen. Dennoch ist die Zeit der Mag'har abgelaufen. Ihr habt mir mehr als alles andere gezeigt, dass ich nicht in der Lage bin, diese Leute anzuführen. Zu stark ist der Fluch meines Blutes. Ich werde nicht... ich kann nicht der nächste Höllschrei sein, der die Orcs in die Verdammnis führt.\n\nBitte, {name}, kehrt zur Großmutter zurück und erklärt ihr, was ich Euch gesagt habe. Ich schäme mich zu sehr, um zu ihr zu gehen... ihr in die Augen zu schauen.", sourceObjective = "Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat.", completion = "<Tränen strömen über Großmutter Geyahs Gesicht.>\n\nGeht zu Eurem Kriegshäuptling. Sagt ihm, dass ich ihn hier erwarte...", sourceObjectiveStatus = "unverified-source-field" }
quests[10173] = { id = 10173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stab des Erzmagiers", description = "Erlaubt, dass ich mich vorstelle, {class}.\n\nMein Name ist Ravandwyr, Lehrling des Erzmagiers Vargoth.\n\nMein Meister ist... nennen wir es indisponiert. Ich bin hier in einer Angelegenheit von höchster Wichtigkeit.\n\nDie Ruinen von Arklon südöstlich der Stadt sind eine Brutstätte für die Aktivitäten der Brennenden Legion. Was sie mit den Ruinen vorhaben interessiert weder mich noch meinen Meister. Aber ihre Anführerin, Ekkorash, hat den Stab meines Meisters.\n\nMit diesem Beschwörungspulver könnt Ihr die Dämonin aus ihrem Versteck locken. Streut es über die Kohlenpfanne in der Mitte der Ruinen.", sourceObjective = "Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen.", progress = "Ich werde nicht ruhen, bis Erzmagier Vargoth seinen Stab zurück hat. Konntet Ihr ihn den Klauen des Dämonen entreißen?", completion = "Ah, Ihr habt es also geschafft den Stab zurückzuholen. Beeindruckend, {name}. Vielleicht seid Ihr genau der {class}, den ich suche.\n\nOh ja, Eure Belohnung...\n\n\n\nIhr habt sicherlich mehr erwartet, aber das kommt schon noch mit der Zeit. Fürs Erste soll die Möglichkeit Eure Belohnung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10174] = { id = 10174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch des Violetten Turms", description = "Jetzt könnt Ihr mithilfe des Stabs Kontakt zu dem Erzmagier aufnehmen.\n\nEr lebt im Violetten Turm, auf einer Insel im Süden. Der verfluchte Turm ist sowohl eine Zuflucht als auch ein Gefängnis für ihn. Mitglieder und Verbündete der Kirin Tor können weder hinein noch hinaus, weswegen ich meinen Meister nicht sehen kann.\n\nDer Stab kann die Verteidigung des Turms durchbrechen, jedoch nur, wenn er von jemandem, der nicht zu den Kirin Tor gehört, aktiviert wird.\n\nNehmt den Stab und benutzt ihn, um ein Abbild des Erzmagiers zu erschaffen. Sagt ihm, was passiert ist und beweist ihm, dass ich ihn nicht ganz enttäuscht habe.", sourceObjective = "Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen.\n\nFalls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz.\n\nBereitgestellter Gegenstand:", completion = "<Erzmagier Vargoth betrachtet Euch, als Ihr ihm Ravandwyrs Nachricht übermittelt.>\n\nRavandwyr hat alles, was ein Meister sich von einem Lehrling wünschen kann. Als ich ihm den Stab gab und ihm befohlen habe, zu fliehen, habe ich gehofft, dass er ihn benutzen würde, um jemanden zu finden, der mich nach dem Abzug von Kael'thas Truppen aus dem Turm befreien kann. Seitdem habe ich viel über den Fluch herausgefunden.\n\nEr kann gebrochen werden, aber dazu brauche ich Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10175] = { id = 10175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall, Sohn Durotans", description = "Kehrt in Eure Welt zurück, {name}. Sucht meinen Enkelsohn und sagt ihm, dass sein Blut hier ist - in dieser zerschlagenen Welt.\n\nSagt ihm, dass das Erbe seines Vaters weiterlebt.\n\nSagt ihm alles...", sourceObjective = "Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht.", completion = "<Thralls Stimme wird dumpf wie ein fernes Donnergrollen.>\n\nIch... Ich habe eine Großmutter? Sie ist am Leben?", sourceObjectiveStatus = "unverified-source-field" }
quests[10176] = { id = 10176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'kelos der Wächter", description = "Jetzt, da Ihr alle Gegenstände, die ich benötige, um Kael'thas Fluch zu brechen, gesammelt habt, gibt es nur noch Eines zu tun. Als Kael'thas den Turm versiegelt hat, hat er einen arkanen Golem, der als Ar'kelos bekannt ist, auf dem Grund des Turms platziert.\n\nIhr müsst Ar'kelos besiegen, damit ich innerhalb des Turms wieder meine Magie wirken kann.\n\nWenn Ihr den Violetten Turm betretet, wird der Fluch Euch treffen.\n\nSobald Ihr Ar'kelos besiegt habt, steigt den Turm hinauf und unterstützt mich bei den Vorbereitungen für das Ritual.", sourceObjective = "Betretet den Violetten Turm in der Mitte von Kirin'Var und besiegt Ar'kelos. Sprecht danach mit Erzmagier Vargoth.", progress = "Endlich treffen wir uns.", completion = "Das habt Ihr gut gemacht, {name}. Ohne das Dämpferfeld wird es viel leichter für mich, die Magie vorzubereiten, mit der ich den Fluch des Turms endlich aufheben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10177] = { id = 10177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Auchindoun", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", sourceObjective = "Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", completion = "Es wird langsam Zeit, dass Ihr kommt.\n\nMehlisah hat schon vor Tagen gesagt, dass sie Hilfe schicken würde. Und wir kämpfen hier schließlich schon eine ganze Weile!", sourceObjectiveStatus = "unverified-source-field" }
quests[10178] = { id = 10178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Spion To'gun", description = "To'gun, dieser Narr! Wir können hier kaum die Angriffe zurückhalten und er geht wieder hinein um Informationen zu sammeln und die anderen Spione zu retten!\n\nIch weiß nicht, ob ich ihn umarmen oder töten soll!\n\nDer Schattenrat muss uns mithilfe von Magie ausfindig gemacht haben, denn all unsere Spionen mussten hastig von dort fliehen. Die meisten von uns haben es nicht geschafft.\n\nBitte, wenn Ihr mutig genug seid, um das Schattenlabyrinth zu betreten, könntet Ihr dann nach To'gun Ausschau halten? Er ist schon eine ganze Weile fort, und ich befürchte das Schlimmste.", sourceObjective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", completion = "Was? Grik'tha hat Euch nach mir geschickt?\n\nIch weiß nicht, ob ich mich geehrt fühlen oder sie eine Närrin schimpfen soll!\n\nKönntet Ihr mir vielleicht aus diesem Käfig raushelfen? Es ist ein bisschen eng hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[10179] = { id = 10179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hüter von Kirin'Var", description = "Als klar wurde, dass unsere Expedition ohne Hoffnung auf Rückkehr nach Azeroth in der Scherbenwelt gefangen war, reisten die Kirin Tor zu den Ebenen von Farahlon und erbauten Kirin'Var. Ich habe die Verwaltung des Dorfs Hüter Dierwert übertragen, aber als Kael'thas und seine Streitkräfte mich hier im Violetten Turm einsperrten, ist mein Kontakt zu ihm abgebrochen.\n\nSucht ihn in Kirin'Var und helft ihm, wo Ihr nur könnt, {name}. Ich bin sicher, dass er seit dem Angriff alle Hände voll zu tun hat.", sourceObjective = "Sprecht mit Hüter Dierwert in Kirin'Var im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10180] = { id = 10180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann es einfach nicht lassen", description = "Ich habe versucht, Isfar davon zu überzeugen, hier in den sicheren Mauern von Shattrath zu bleiben, aber er wollte nicht auf mich hören. Stattdessen hat er sich entschlossen, wieder auf eigene Faust nach Auchindoun zu gehen.\n\nEr hatte zwar das Glück, den Sethekkhallen einmal zu entkommen, aber wenn sie ihn erwischen wird es kein zweites Mal geben.\n\nIch bewundere seine Entschlossenheit, seine Schwester zu befreien, aber ohne Hilfe wird er es nicht schaffen.\n\nFindet Isfar und sprecht mit ihm, {name}. Wenn Ihr ihn nicht davon überzeugen könnt, zurückzukommen, könntet Ihr ihm dann vielleicht helfen Lakka zu retten?", sourceObjective = "Sprecht mit Isfar in den Sethekkhallen in Auchindoun.", completion = "Ich hätte wissen sollen, dass er nach mir schicken würde. Er hat versucht mir auszureden, in die Sethekkhallen zurückzukehren, aber ich könnte nicht damit leben, wenn Lakka etwas zustoßen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10182] = { id = 10182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfmagier Dathric", description = "Das Schwert ist von außergewöhnlicher Qualität, fein geschmiedet und perfekt für einen Kampfmagier ausbalanciert. Auf dem Knauf der Waffe sind das Siegel der Kirin Tor und der Name \"Dathric\" eingraviert.\n\nWährend Ihr die Waffe in den Händen hin und her dreht, bemerkt Ihr, dass etwas mit dem Schwert nicht stimmt. Es fühlt sich an, als wäre es zwischen zwei Welten hin- und hergerissen. Könnte dies der Gegenstand sein, der Kampfmagier Dathrics Geist an diese Welt bindet?\n\nVielleicht zerbricht das Band, wenn Ihr es an seinen angestammten Platz zurückbringt, und befreit Dathrics Geist endgültig.", sourceObjective = "Sucht die Wohnung von Kampfmagier Dathric in der Zaubergasse und bringt die Klinge zurück in sein Waffenregal. Sprecht danach mit Hüter Dierwert in Kirin'Var.", completion = "Gut gemacht, {name}. Ich kann keine Rastlosigkeit mehr in Dathrics Geist spüren. Ich würde viel dafür geben, wenn ich noch einmal mit ihm sprechen könnte, aber es ist schon gut genug, dass er nun in Frieden ruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10183] = { id = 10183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Area 52", description = "Ich studiere hier draußen den Nether - die astralen Strömungen und so weiter. Dies ist ein idealer Platz, weit weg von den Lichtern und dem Getöse der Stadt. Wenn ich diesen Schrott doch nur am Laufen halten könnte!\n\nHey, wisst Ihr, wenn Ihr nach Arbeit sucht, solltet Ihr nach Area 52 gehen! Das liegt gleich den Pfad hoch und bei der Weggabelung rechts.\n\nWarum bringt Ihr nicht einfach meine neusten Forschungsnotizen zu Raketenchef Doppeldecker? Ich bin sicher, er hat genug Arbeit für Euch, wegen des Raketenschiffs X-52 und so.", sourceObjective = "Bringt die Notizen des Netheorologen zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", progress = "Stress, Stress. Keine Zeit verschwenden! Es gibt ein Raketenschiff, das gebaut werden will!\n\nWas wollt Ihr?", completion = "Oh, Kupfernickel hat sich also endlich entschlossen, seine Entdeckungen zu berichten, was? Faule Wissenschaftler!\n\nWas ist das?\n\n<Der Chef blättert ein paar Mal durch die Notizen mit einem deutlich skeptischen Gesichtsausdruck.>\n\nEr sagt, dass die gewaltigen Netherenergien, die durch den Nethersturm fließen, alles in nur ein paar Monaten in Stücke reißen werden.\n\nDas ist ungünstig - jetzt müssen wir den Zeitplan für das Raketenschiff etwas straffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10184] = { id = 10184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösartige Überbleibsel", description = "Die meisten Geister im Dorf sind nicht mehr als blasse Überbleibsel der Magier der Kirin Tor, die sie einst waren. Sie erinnern sich nicht mehr an ihr früheres Ich und streunen blind vor Wut um die Ruinen herum.\n\nDas war jedoch nicht immer so. Direkt nach dem Angriff waren die Geister zwar rastlos, aber nicht bösartig. Mit der Zeit sind sie jedoch immer aggressiver geworden. Ich traue mich nicht, in den südlichen Teil des Dorfs zu gehen, denn sie machen nicht einmal vor mir Halt. Beruhigt sie und lasst uns hoffen, dass Ihr Ärger dann verfliegt.", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 20 abtrünnige Geister auf dem Ratsplatz tötet.", completion = "<Hüter Dierwert schüttelt langsam den Kopf.>\n\nSie haben das nicht verdient, aber es ist das Beste, was wir tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10185] = { id = 10185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer als der Tod", description = "Nachdem die Blutelfen Kirin'Var dem Erdboden gleich gemacht hatten, haben sie mit dem Bau eines großen Gebäudes im Nordwesten begonnen. Ohne die Kräfte des Erzmagiers können wir nicht genau sagen, was dort vor sich geht.\n\nEines ist jedoch klar. Die Anwesenheit der Blutelfen hat eine Flut von gefräßigen Manaelementaren entfesselt. Sie scheinen von den Ruinen der Zaubergasse angelockt zu werden und verursachen noch weitere Zerstörung... Wir können das nicht weiter zulassen.", sourceObjective = "Tötet 10 Magiertöter und 10 Manasucher und kehrt zu Hüter Dierwert in Kirin'Var zurück.", completion = "<Der Hüter sieht bestürzt aus.>\n\nIch kann die nächste Welle schon über den Horizont kommen sehen. Sie auszumerzen hilft vielleicht für den Moment, aber wir brauchen langfristige Maßnahmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10186] = { id = 10186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid eingestellt!", description = "Lasst mich der Erste sein, der Euch an Bord willkommen heißt, Juniortechniker dritten Grades {name}!\n\nWir bauen hier draußen mein Meisterwerk - die X-52 Netherrakete!\n\nDoch zuerst müssen wir alle Teile und den Treibstoff für sie besorgen. Und da kommt Ihr ins Spiel.\n\nZuerst brauche ich Kristalle, VIELE Kristalle, für die astrallithische Antriebsmatrix. Die Draenei hatten so viele, dass sie ihnen schon zu den Ohren herauswuchsen!\n\nBegebt Euch also zu den Ruinen von Enkaat und sammelt ein paar für mich! Und kümmert Euch nicht um die Draeneigeister.", sourceObjective = "Sammelt 10 Astrallithiummatrixkristalle und kehrt dann zu Raketenchef Doppeldecker in Area 52 im Nethersturm zurück.", progress = "Sieht es etwa aus, als wäre die X-52 Netherrakete bereit zum Abflug? Durchquere ich den wirbelnden Nether im meinen bequemen Kommandostuhl? Entdecke ich fremde neue Welten? Suche nach neuen Technologien und Geschäftsgelegenheiten? Dringe in Galaxien vor, die nie ein Goblin zuvor gesehen hat?\n\nNein!\n\nAlso hoffe ich, dass Ihr die Kristalle habt, nach denen ich Euch geschickt habe.", completion = "Pah! Die sehen aber grob aus. Vielleicht können wir sie in einer tertiären Antriebsmehrfachkammer einsetzen?\n\nTrotzdem gute Arbeit, Juniortechniker dritten Grades! Ihr werdet es sicher bald zum zweiten Grad schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10187] = { id = 10187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht für den Erzmagier", description = "Auch wenn es hier sehr ungemütlich ist, muntert es uns ein wenig auf, dass der Erzmagier die Misere des Dorfs nicht vergessen hat.\n\n<Der Hüter schaut zum Turm hinauf.>\n\nEs ist lächerlich, oder? Manchmal scheint es, als trenne uns nur eine Wand aus einfachem Stein. Wie leicht vergisst man die Wand aus Magie.\n\nWenn Ihr so nett wärt, erklimmt den Turm und sagt Erzmagier Vargoth, dass wir Fortschritte im Dorf machen und bald einen Weg finden werden, um die Manakreaturen fernzuhalten.", sourceObjective = "Sprecht mit Erzmagier Vargoth im Violetten Turm im Nethersturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10188] = { id = 10188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel von Krasus", description = "Bevor wir uns vor so vielen Jahren von Azeroth aus aufmachten, haben die Kirin Tor unserer Expedition ein mächtiges Artefakt anvertraut, das Siegel von Krasus. Es hat uns im Kampf gegen die Orcs große Dienste erwiesen und könnte eine wichtige Rolle beim Brechen des Zaubers, der mich gefangen hält, spielen.\n\nAls Kael'thas mich jedoch meiner Besitztümer beraubt hat, gab er das Siegel an Zauberbinderin Maryana, die mit der Garnison zurückblieb. Hätte er gewusst, was er in seinem Besitz hatte, hätte er es nicht so einfach weggegeben.", sourceObjective = "Holt Euch das Siegel von Krasus von Zauberbinderin Maryana in der Manaschmiede Coruu, nordwestlich vom Violetten Turm.", progress = "Wenn ich vom Fluch des Turmes frei sein will, muss ich das Siegel haben.", completion = "Ah, es ist so wundervoll, wie ich es in Erinnerung hatte. Könnt Ihr die Macht, die davon ausgeht, spüren?\n\nNatürlich ist noch viel mehr zu tun, aber Ihr habt meinen tiefsten Dank dafür, dass Ihr mir das Siegel zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10189] = { id = 10189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede B'naar", description = "Vielleicht sind Euch Kaels Manaschmieden auf dem Weg hierher aufgefallen. Das sind diese großen violetten Gebäude, die Energie aus dem Himmel saugen.\n\nWir wurden von den Sha'tar hierher geschickt, um sie zu erkunden. Ihr könnt uns dabei helfen, indem Ihr eine Stammrolle von dort besorgt. Wenn wir eine Vorstellung davon hätten, wer dort als was arbeitet, wäre uns über alle Maßen geholfen.\n\nWir glauben, dass Hauptmann Arathyn, der eine Ballistentruppe direkt außerhalb der Manaschmiede B'naar leitet, eine solche Rolle besitzen könnte. Holt sie für uns.", sourceObjective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr zum Rand der Manaschmiede B'naar geht und die Stammrolle von B'naar von Hauptmann Arathyn besorgt.\n\nDas Abschließen von Aufgaben für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr bekommen, worum ich Euch gebeten habe, {name}?", completion = "Ausgezeichnet! Mit dieser Stammrolle können wir bessere Entscheidungen treffen, wenn wir die Anhänger Kaels bei den Manaschmieden angreifen.\n\nEigentlich schade, ich mochte es irgendwie, seine Lakaien wahllos zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10190] = { id = 10190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batterien aufladen", description = "Ich habe die wichtige Aufgabe, die Maschinerie in diesen Ruinen zu sammeln, aber ich habe ein paar Probleme damit, alle meine Bots am Laufen zu halten.\n\nDie Phasenjäger - diese wurmähnlichen Dinger - stecken voller Energie! Man kann sie überall finden, wie sie aus dem Nether herausströmen.\n\nFüllt die Batterie mit diesem Ladeblaster, indem Ihr ihn bei einem Phasenjäger benutzt, wenn er sehr schwach ist, und ihm dann die restliche Energie entzieht.", sourceObjective = "Benutzt den Batterieladeblaster bei genügend Phasenjägern, um den Batterieladestatus auf 10 zu bringen. Bringt die Batterie danach zu Bot-Spezialistin Alley in den Ruinen von Enkaat im Nethersturm zurück.", progress = "Habt Ihr die Batterie schon aufgeladen?", completion = "He, passt auf, auf wen Ihr mit dem Ding zeigt! Ihr habt es auf \"töten\" gestellt!!!\n\nGut, es sieht so aus, als hättet Ihr die Batterie genügend aufgeladen. Ich baue sie gleich in Nr. V ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10191] = { id = 10191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nummer V lebt!", description = "Grüße, {race}. Ich bin aufgeladen und voll einsatzfähig!\n\nIn den Ruinen gibt es ein paar zerbrechliche Draeneimaschinen, die ich wieder beschaffen muss. Ich habe sehr edle Servos in den Stellgliedern meiner Handgelenke und bin mit den neusten verbrennungspneumatischen Beulensaugern ausgestattet. Die Maschinen mit der nötigen Sorgfalt zu behandeln ist also kein Problem für mich.\n\nLeider werden die Geister, die in den Ruinen spuken, mich sehr wahrscheinlich angreifen, daher brauche ich Euch und Eure Freunde als Beschützer.", sourceObjective = "Begleitet Maxx E. Million Nr. V durch die Ruinen von Enkaat und wieder in Sicherheit. Sprecht dann mit Bot-Spezialistin Alley außerhalb der Ruinen von Enkaat im Nethersturm.", progress = "So schnell schon zurück?\n\nIst mit Maxx E. Million Nr. V alles in Ordnung?!", completion = "Ihr habt es geschafft! Ihr habt es geschafft! Ich könnte Euch küssen!\n\nOh verdammt... der Maxx E. Million Nr. V hat schon wieder keine Batterie mehr. Naja, er hat seine Arbeit erledigt, und das ist das Wichtigste.\n\nRaketenchef Doppeldecker wird sich freuen, wenn er diese Draeneimaschinen in der X-52 Netherrakete einbauen kann! Das bedeutet eine Beförderung für mich! Ich bin so glücklich, ich muss Euch einfach belohnen!\n\nHier, sucht Euch etwas davon aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10192] = { id = 10192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Kompendium", description = "Die Kirin Tor haben unserer Expedition einen weiteren Gegenstand aus Krasus' Besitz mitgegeben. Es handelt sich dabei um sein Zauberbuch, das Krasus' Kompendium genannt wird. Da es alle Zauber enthält, die Krasus beherrschte, war es uns eine unersetzliche Hilfe im Krieg.\n\nBevor Kael'thas und seine Truppen Kirin'Var besetzt haben, wurde mir das Buch von einem rebellischen Schüler, der begierig darauf war, die Nekromantie zu erlernen, gestohlen. Der Lehrling und seine Anhänger haben sich aufgeteilt und das Buch heimlich studiert, wobei sie sich in ihren Häusern im Süden der Stadt eingeschlossen haben.", sourceObjective = "Holt Euch Krasus' Kompendium - Kapitel 1, Krasus' Kompendium - Kapitel 2 und Krasus' Kompendium - Kapitel 3 vom Ratsplatz von Kirin'Var.", progress = "Habt Ihr das Buch besorgt, {name}?", completion = "<Das Abbild von Erzmagier Vargoth scheint das Kompendium zu begutachten.>\n\nEs ist ein wenig mitgenommen, aber wenn man bedenkt, was es durchmachen musste, ist es ein Wunder, dass es überhaupt überlebt hat. Bewahrt es auf, {name}. Ohne das Buch haben wir kaum eine Chance, den Schutzschild des Turms zu durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10193] = { id = 10193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochrangige Ziele", description = "Von den Informationen aus der Stammrolle wissen wir nun, dass die geistigen Führer der Manaschmieden die Warpmeister und Warpingenieure sind. Sie überwachen die Gewinnung der so genannten \"Warpenergie\" in den Manaschmieden und kümmern sich um ihre Lieferung an entfernte Orte über ein unterirdisches Rohrsystem.\n\nDie einzigen weiteren Spezialisten in dieser Gegend sind die Geologen. Alle anderen sind entweder Teil des Militärs oder Magister - beide sehr leicht zu ersetzen.\n\nGeht dort hinein und tötet Kaels Spezialisten. Das wird ihn am meisten treffen.", sourceObjective = "Spionagemeister Thalodien in Area 52 möchte, dass Ihr in die Manaschmiede B'naar geht und 2 Warpmeister des Sonnenzorns, 6 Warpingenieure des Sonnenzorns und 8 Geologen des Sonnenzorns tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ich seid ein zuverlässiger Bursche. {name}. Wenn es etwas gibt, das ich noch mehr mag, als Kaels Schoßhunde zu töten, dann ist es, wenn das jemand anderes für mich erledigt.\n\nSo habe ich weniger Blut auf meinen Klamotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10194] = { id = 10194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimlicher Flug", description = "Während Ihr weg wart, haben meine Männer eine weitere Manaschmiede entdeckt. Sie befindet sich östlich von hier und ist als Manaschmiede Coruu bekannt.\n\nZwei meiner besten Spione haben einen geheimen Landeplatz außerhalb der Manaschmiede eingerichtet. Ihr sollt ihnen helfen, Kaels Truppen zu unterwandern und so viele Informationen wie möglich zu sammeln.\n\nSprecht mit Veronia außerhalb der Stadtmauer. Sie hat einen Windreiter vorbereitet, der Euch zur Manaschmiede Coruu bringen wird. Wenn Ihr dort seid, meldet Euch bei Caledis Morgenhell. Er wird Euch mit Eurer Mission vertraut machen.", sourceObjective = "Sprecht mit Veronia außerhalb von Area 52 und fliegt zur Manaschmiede Coruu.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Euren Flug zu organisieren war nicht gerade billig. Ich hoffe, ihr habt das Zeug zu diesem Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[10195] = { id = 10195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Söldner sieht, Söldner handelt", description = "Seit Ihr den ersten Stapel Feder gebracht und Bertelms Hut fertiggestellt habt, wollen alle anderen Söldner auch einen haben, darunter auch Thander. Ich habe ihnen gesagt, dass ich mich gleich darum kümmern werde, aber ich werde mehr Arakkoafedern dafür brauchen.\n\nWenn Ihr auf Euren Abenteuern in den Wäldern noch mehr davon finden solltet, nehme ich sie Euch gerne ab.", sourceObjective = "Bringt 30 Arakkoafedern zu Ros'eleth in Allerias Feste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10196] = { id = 10196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Arakkoafedern", description = "Ich habe erste Erfolge darin, die Arakkoageister näher zu mir zu locken, aber sie sind immer noch sehr schüchtern. Vielleicht trauen sie sich näher, wenn ich meine Verkleidung verbessere.\n\nDazu benötige ich jedoch mehr Arakkoafedern wie die, die Ihr mir bereits gebracht habt. Wenn Ihr noch ein paar Federn bekommen könntet, würde ich sie Euch gerne abnehmen.", sourceObjective = "Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[10197] = { id = 10197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine überzeugende Verkleidung", description = "Die Reihen von Kaels Armee zu unterwandern wird keine leichte Aufgabe. Mit meinen geringen Künsten der Illusion könnte ich einen von uns wie einen Anhänger Kaels aussehen lassen, aber es gibt einige Details in ihrer Uniform, die ich nicht nachbilden kann.\n\nBringt mir ein Set ihrer Roben, ein Paar ihrer Handschuhe und ein Gardistenmedaillon des Sonnenzorns. Das wird die Ergebnisse meiner Magie überzeugender machen. Sie tragen alle das gleiche, also solltet Ihr keine Probleme haben, diese Gegenstände zu finden.", sourceObjective = "Bringt ein Set Arkanistenroben des Sonnenzorns, ein Paar Forscherhandschuhe des Sonnenzorns und ein Gardistenmedaillon des Sonnenzorns zu Caledis Morgenhell bei der Manaschmiede Coruu im Nethersturm.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Kleidungsstücke, um die ich Euch gebeten habe?", completion = "Ausgezeichnet! Wenn ich mit Euch fertig bin, werdet Ihr Euch unbemerkt unter die Ränge des Sonnenzorns mischen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10198] = { id = 10198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen sammeln", description = "Ich habe aus den Teilen, die Ihr mir besorgt habt, eine Uniform hergestellt. Sie ist magisch verbessert, um die Illusion perfekt zu machen.\n\nWir haben beobachtet, wie Kommandant Morgenschmied vor ein paar Minuten hineingegangen ist, um Arkanist Ardonis zu treffen. Er hatte sein gesamtes Gefolge an Wachen bei sich, daher ist das, was sie zu besprechen haben, sicher von größter Wichtigkeit. Versucht, etwas darüber herauszufinden.\n\nAch, das hätte ich fast vergessen. Haltet Euch von den arkanen Golems fern, die in der Manaschmiede patrouillieren. Sie werden Eure Illusion mühelos durchschauen.", sourceObjective = "Benutzt die Sonnenzornverkleidung, geht in die Manaschmiede Coruu und belauscht das Gespräch zwischen Sonnenzornkommandant Morgenschmied und Arkanist Ardonis.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Wir geht es mit der Bespitzelung voran, {name}? Ihr solltet Euch lieber beeilen. Ich werde hier schon ganz kribbelig.", completion = "Die Manaschmiede Duro ist in Schwierigkeiten? Ich bin mir sicher, dass Thalodien sich über diese Neuigkeiten freuen wird. Lasst uns zunächst diese Aufgabe hier fertigstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10199] = { id = 10199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kleine Extrakick", description = "So, nun fehlt mir noch die eine Zutat, die meinem Gebräu den entscheidenden kleinen Kick geben sollte, den wir brauchen.\n\nDer Stich der Netherrochen, die sich in der Nähe der Schieferhautschinder herumtreiben, ist ganz schön heftig. Bringt mir ein paar ihrer Stachel, damit ich das Gift aus ihnen gewinnen kann.\n\nIch bin mir sicher, dass die Ergebnisse explosiv sind!", sourceObjective = "Besorgt 5 Netherrochenstachel und bringt sie zu Stiefels in Area 52 im Nethersturm.", progress = "Wenn ich das Gift von genügend vielen Netherrochenstacheln extrahieren kann, bekommen wir vielleicht den explosivsten Kraftstoff, der gemischt wurde!", completion = "Wow! Ok, jetzt stimmt die Sache.\n\nLasst mich nur schnell die Boshaftigkeit aus diesen kleinen Schönheiten quetschen. Das sollte ein Raketentreibstoff werden, der alle von den Socken haut!\n\nHier, lasst mich das Schieferöl und das Stachelgift mischen, und dann schauen wir mal, was passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[10200] = { id = 10200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Thalodien", description = "Es wäre besser, wenn diese Information so schnell wie möglich zu Thalodien gelangen würde. Ich bleibe hier und verwische unsere Spuren.\n\nEs wäre alles andere als gut, wenn Kael'thas herausfinden würde, was wir hier getan haben. Geheime Informationen sind immer am besten, wenn der Feind nicht weiß, dass man sie hat.", sourceObjective = "Kehrt zu Spionagemeister Thalodien in Area 52 im Nethersturm zurück.", completion = "Ihr überrascht mich immer wieder, {name}. Das war beeindruckende Spionagearbeit, die Ihr da in der Manaschmiede Coruu geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10201] = { id = 10201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Moment der Wahrheit", description = "Das Öl ist endlich für einen ersten Test bereit. Es scheint dickflüssig genug zu sein, um als hochwertiges Waffenöl zu dienen.\n\nDer einzige Weg, dies herauszufinden ist, einen Profi zu fragen. Seht Ihr Grek da drüben bei den Fahndungsanschlägen? Ich weiß, er ist nicht gerade ein Poet, aber mit Waffen kennt sich der Orc aus!\n\nBringt ihm eine Probe des Öl und bittet ihn, es an seiner Waffe auszuprobieren. Wenn er das getan hat, berichtet mir von seiner Meinung.", sourceObjective = "Geht zu Grek und bittet ihn, das Öl an seiner Waffe auszuprobieren. Bringt das Ergebnis zu Rakoria, wenn er fertig ist.", completion = "<Ihr berichtet Rakoria die Testergebnisse und sie fängt an, schallend zu lachen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10202] = { id = 10202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Abtrünniger", description = "Wir wurden vor Kurzem von einem Magister des Sonnenzorns kontaktiert, der uns beitreten möchte und schwört, dass er uns Informationen geben kann, die wir dringend benötigen. Wir haben uns mit unseren Informanten in Verbindung gesetzt um zu überprüfen, ob es sich bei ihm um einen Doppelagenten handeln könnte, und er scheint sauber zu sein.\n\nEr befindet sich in der Manaschmiede Ara, was die Kommunikation etwas erschwert. Geht zu ihm und hört Euch an, was er zu sagen hat. Wenn er nur halb so hilfreich ist, wie er behauptet, können wir ihn sicher gut einsetzen.", sourceObjective = "Geht zur Manaschmiede Ara und sprecht mit Magister Theledorn.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Es ist an der Zeit, dass Ihr auftaucht. Ich habe mich schon gefragt, ob die Seher überhaupt interessiert sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10203] = { id = 10203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschätzbare Ausrüstung beamen", description = "Habt Ihr den Riss gesehen, der mitten durch Area 52 verläuft? Wir waren das! <Grinsen>\n\nIm Riss befinden sich allerlei Schätze für die X-52 Netherrakete! Das einzige Problem ist nur, dass wir nicht genug Ausrüstung haben.\n\nBis die Brennende Legion dort aufgetaucht ist, führten wir eine Operation in den Ruinen von Arklon aus. Ich möchte, dass Ihr diesen ultrastarken Dekonsolidierungsstrahler zu den Ruinen bringt. Benutzt ihn, um unsere Ausrüstung zum leitenden Ingenieur Zischeldruck im Riss zu beamen.\n\nJuniortechniker dritten Grades {name}, dies ist Eure Chance auf eine Beförderung. Vergeigt sie nicht!", sourceObjective = "Benutzt den ultrastarken Dekonsolidierungsstrahler, um den Hyperdreh-Grab-o-Matik, die servopneumatische Baggerklaue, den multispektralen Geländeabtaster und den großen Wagen voller Sprengstoff zurück nach Area 52 zu beamen. Meldet Euch dann beim leitenden Ingenieur Zischeldruck beim östlichen Ende des Risses in Area 52 im Nethersturm.", progress = "Ist es nicht schön hier? Und jeden Tag finden wir etwas Neues und Exotisches.\n\nWas für ein Glück, dass wir fast das Dorf zerstört haben, als wir hier gegraben haben.", completion = "Ihr müsst derjenige sein, der uns die ganze Ausrüstung von den Ruinen hergebeamt hat! Ein Hoch auf Euch!\n\nIch habe die Ausrüstung bereits an unsere Grabungsorte weiterverteilt. Jetzt können wir unsere Ausgrabungen im großen Stil überall auf der Insel durchführen! Die Netherrakete wird in null Komma nichts fertig werden!\n\nHmm, merkwürdig. Wartet mal, habt Ihr gesagt, Ihr habt uns vier Dinge zurück geschickt? Ich habe nur drei bekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10204] = { id = 10204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutjuwelenkristalle", description = "Kaels Magister haben den Gebrauch von Manakristallen so weit perfektioniert, dass sie innerhalb von Sekunden große Mengen von Energie aufnehmen können.\n\nDas tun sie, indem sie kleinere Kristallsplitter von Blutjuwelen an größeren und vollen Kristallen aufladen.\n\nGeht zur Manaschmiede B'naar und besorgt einen dieser Splitter von einem Magister des Sonnenzorns und benutzt ihn, um Energie von einem größeren Kristall aufzunehmen.\n\nKehrt zu mir zurück, damit ich die Wirkung der Aura untersuchen kann. Keine Sorge, Nebenwirkungen sollten nur temporär sein.", sourceObjective = "Magistrix Larynna möchte, dass Ihr zur Manaschmiede B'naar geht und einen Blutjuwelensplitter von einem Magister des Sonnenzorns besorgt. Benutzt den Splitter in der Nähe von größeren Blutjuwelenkristallen und kehrt zu ihr in Area 52 zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Hmmm... wie ich erwartet habe.\n\nSolch rohen Energien ausgesetzt zu sein erhöht unsere angeborene Sucht nach Magie gewaltig.\n\nIch bin nicht überrascht, dass Kael mit seinen Taten ungestraft davon kommt, wenn seine Angestellten praktisch die ganze Zeit betrunken sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10205] = { id = 10205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sphärenräuber Nesaad", description = "Sphärenräuber Nesaad muss erledigt werden! Ich habe keine Ahnung, wie er meinen Angriff überleben konnte, aber er darf seine Taten dort auf keinen Fall fortführen.\n\nGeht zurück und vernichtet Nesaad. Er hat ein kleines Lager des Astraleums im südwestlichen Teil des Hügels.\n\nVersagt nicht, wie ich es tat, {name}.", sourceObjective = "Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück.", progress = "Ist es vorbei? Ist Sphärenräuber Nesaad tot?", completion = "Ich bin erleichtert zu hören, dass dieser Abschaum endlich vernichtet wurde. Ihr macht Eure Arbeit gut, {name}... darf ich so vermessen sein, Euch beim Namen zu nennen?\n\nWenn Ihr möchtet, habe ich eine weitere Aufgabe für Euch. Eine, die besonders wichtig ist. Jemand mit so offensichtlichen Talenten wie Ihr wird sie sicher leicht bewältigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10206] = { id = 10206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Eure Rolle", description = "Diese astralen Hampelmänner sind genauso opportunistisch wie wir, das muss man ihnen lassen. Aber niemand, und ich meine NIEMAND, wagt sich auf das Gebiet von B.U.M.M.!\n\nDer Hügel im Süden gehört uns!\n\nWenn wir die X-52 Netherrakete fertigstellen wollen, brauchen wir alle neuen Technologien, die wir in die Finger bekommen können. Und da die Astralen von uns stehlen, ist es nur gerecht, wenn wir es ihnen mit gleicher Münze heimzahlen.\n\nWarum geht Ihr nicht zum Hügel und schaut, ob Ihr ihnen etwas von ihrer Technologie vor der Nase wegschnappen könnt.", sourceObjective = "Sammelt 10 Stück Astraltechnologie und bringt sie zu Papa Mauschel in Area 52 im Nethersturm.", progress = "So schnell schon zurück? Nehmt mich besser nicht auf den Arm, {class}.\n\nDer Erfolg des X-52-Projekts hängt davon ab, dass wir das Zeug so schnell wie möglich bekommen!", completion = "Hehe, astrale Deppen!\n\nDanke, dass Ihr uns die Teile gebracht habt, {class}. Ich wette, wir können diese Babys gleich in die Rakete einbauen. Ich frage mich, was sie wohl bewirken? Wird sicher lustig, es herauszufinden!\n\nHm, lasst mich mal schauen ob ich noch ein wenig Wechselgeld für Euch in der Hosentasche habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10207] = { id = 10207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall REUSE", description = "Eure Fähigkeiten in der Schlacht sind dem obersten Kommando aufgefallen, {class}. Sie wollen Euch an die Front zu Stümmelfausts Truppe schicken. Sie sind sehr radikal und haben sich der vollständigen Auslöschung der Legion verschrieben, also passt Ihr wahrscheinlich genau dazu...\n\nGeht etwa 200 Schritte nach Osten und biegt bei der hervorragenden Landmasse nach Süden ab. Ihr findet den Häschersturz dort, wo einst ein alter Bauernhof stand. Wenn Ihr angekommen seid, meldet euch bei Vorpostenkommandant To'arch.\n\nUnd jetzt weggetreten!", sourceObjective = "Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10208] = { id = 10208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verstärkung abschneiden", description = "Direkt im Osten liegt die Front der Legion. Entlang der Front befinden sich die höllischen Portale und Tore, mit deren Hilfe Verstärkung auf die Höllenfeuerhalbinsel und in die ganze Scherbenwelt gebracht wird. Wir müssen diese Portale zerstören!\n\nNehmt diese Zünder. Sie wurden in Area 52 hergestellt und benutzten die eigene Macht der Dämonen als Sprengstoff! Besiegt die Legion beim Portal Xilus und Portal Kruul und haltet nach dämonischen Runensteinen Ausschau. Benutzt den Zünder, um die vier Steine in den Portalen zu sprengen, sobald Ihr genug Steine beisammen habt... und dann genießt das Feuerwerk! Kehrt zu mir zurück, wenn Ihr Eure Aufgabe erfüllt habt.", sourceObjective = "Besiegt die Feinde um Portal Xilus und Portal Kruul herum, um dämonische Runensteine zu sammeln.\n\nBenutzt To'archs Zünder in Portal Xilus und Portal Kruul.\n\nKehrt danach mit To'archs Zünder zu To'arch im Häschersturz auf der Höllenfeuerhalbinsel zurück.", progress = "Die Legion ist bestimmt nicht auf unsere Überraschung gefasst, was, {name}?", completion = "Gut gemacht! Ich konnte die Explosionen fast bis hierher spüren!\n\nJetzt haben wir noch eine weitere Bombenmission für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[10209] = { id = 10209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörer Kanthins Preis", description = "Als nächstes müssen wir meinen Vertrauten, Gletscharius, aus den Händen des Blutelfenbeschwörers, der ihn gefangen hält, befreien. Beschwörer Kanthin war einst einer der erfahrensten Magister in der Streitmacht, die Kael'thas losgeschickt hat, um Kirin'Var auszulöschen. Es ist ganz normal, dass er meinen Vertrauten als Trophäe haben will.\n\nIch bin mir sicher, dass Kanthin, dumm wie er ist, versucht hat, Gletscharius zu seinem Diener zu machen. Ich habe herausgefunden, dass Kanthin sich jetzt in der Manaschmiede Duro aufhält, falls dies Euch etwas sagt.", sourceObjective = "Besiegt Beschwörer Kanthin in der Manaschmiede Duro auf der Insel nördlich des Sonnenzornpostens und holt den Stein des Gletscharius zurück.", progress = "Habt Ihr den Stein von Gletscharius bekommen?", completion = "<Ihr wisst nicht, ob es nur eine Verzerrung ist, aber der Erzmagier scheint zu lächeln.>\n\nJetzt, da ich all meine Besitztümer zurück habe, habe ich alles, um Kael'thas' Magie zu durchbrechen. Ich werde den Zauber gleich wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10210] = { id = 10210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dal", description = "Willkommen in Shattrath, {class}. Dies ist vielleicht der einzige Ort in der Scherbenwelt, in der Ihr so etwas wie Sicherheit empfinden könnt.\n\nEine Gruppe von Naaru, die als Sha'tar bekannt sind, hat die Dämonen von hier fortgejagt.\n\nWenn Ihr noch nie einen Naaru gesehen habt, solltet Ihr A'dal auf der Terrasse des Lichts besuchen. Der Anführer der Sha'tar ist der ehrfurchtgebietendste Anblick, den ich je gesehen habe. Ganz anders, als alles andere in diesem öden Land.", sourceObjective = "Sprecht mit A'dal, Anführer der Sha'tar in der Mitte der Terrasse des Lichts.", completion = "<Das Licht, das Eure Sinne erfüllt hat, als Ihr Euch A'dal nähertet, wird noch stärker, als Ihr ihn ansprecht. Melodische Klänge ertönen in Eurem Kopf.\n\nIhr seid hier sicher.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10211] = { id = 10211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt des Lichts", description = "Belästigt A'dal nicht mit Euren unbedeutenden Fragen, {class}. Er ist vielleicht das mächtigste Wesen, das Ihr je zu Gesicht bekommen werdet.\n\nIhr kommt mir nicht bekannt vor. Ich nehme an, Ihr wollt etwas über die Stadt erfahren?\n\nIhr müsst schon entschuldigen, dass ich selbst keine Führungen mache, aber ich muss einige Pläne mit A'dal besprechen. Vielleicht wärt Ihr ja mit einem herbeigerufenen Diener an meiner statt zufrieden? Ausgezeichnet!", sourceObjective = "Folgt Khadgars Diener und hört Euch an, was er zu erzählen hat. Kehrt nach dieser Aufgabe zu Khadgar zurück.", progress = "Die Geschichten der Lebewesen sind kurz, {name}. Die Geschichten der Städte dauern Jahre.", completion = "Ich hoffe, Ihr habt etwas über Shattrath erfahren, {name}. Lasst es einfach auf Euch wirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10212] = { id = 10212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Mag'har", description = "Ich muss erst alles in Ordnung bringen, bevor ich gehe. Kehrt zur Großmutter zurück und sagt ihr, dass ihr Enkelsohn kommt.", sourceObjective = "Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück.", completion = "Ihr seid wirklich der Held der Mag'har, {name}. Wärt Ihr nicht gewesen, wären wir sicher von den Ogern und Zerschlagenen überrannt worden.\n\nWir sind ein armes Volk, aber wir haben dennoch einige mächtige Artefakte. Bitte, ich bestehe darauf, dass Ihr Euch eines aus unserem Kasten nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10213] = { id = 10213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Absturzstelle", description = "Als ich verwundet in der Wüste lag, habe ich gesehen, wie ein goblinscher Zeppelin abgestürzt ist. Es kam im Nordwesten runter, hinter dem Expeditionsrüstlager.\n\nDer Zeppelin hat gebrannt. Schreiende, brennende Goblins fielen wie Bomben vom Himmel. Ich hatte natürlich sehr große Schmerzen und viel Blut verloren. Vielleicht habe ich mir das alles auch nur eingebildet.\n\nWenn Ihr irgendwelche Überlebenden finden solltet, bietet ihnen eine Zuflucht hier im Rückenbrecherposten an.", sourceObjective = "Durchsucht die Absturzstelle nach Überlebenden.", completion = "Wir wurden von der Brennenden Legion abgeschossen, obwohl wir eine Friedensflagge geschwenkt haben. Wer hätte ahnen können, dass die Brennende Legion so gemein ist?\n\nWir können leider nicht mit Euch zum Rückenbrecherposten kommen. Wir müssen den Zeppelin reparieren und dann weiterziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10214] = { id = 10214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt diese Mine zum Beben!", description = "Die Mine wurde von diesem Gan'argpack überrannt, und zu allem Übel sind die Peons der Meinung, dass jetzt die richtige Zeit für ein Schläfchen ist! Ich weiß nicht, wie sie bei all dem Lärm aus der Mine schlafen können, aber das ist mein geringstes Problem.\n\nWenn wir dieses Gan'arggesindel nicht bald loswerden, wird Thrallmars Nachschub an Kupfer und anderen Materialien abgeschnitten. Ich habe schon Wachkommandant Krunk um Hilfe gebeten, aber er sagt, dass er keine Männer schicken kann, solange die Stadt angegriffen wird. Könnt Ihr mir helfen?", sourceObjective = "Tötet 15 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10216] = { id = 10216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Shaffars Astrale haben uns ganz aus der Managruft ausgeschlossen. Zum Glück habe ich einen Plan. Auch wenn wir nicht durch die Eingangstür können, bin ich mir sicher, dass es innen viele Transporter gibt.\n\nIch möchte, dass Ihr zuerst den Weg für meine Gruppe freiräumt und dann einen der Transporter aktiviert, damit wir hineinteleportieren können.\n\nAktiviert den Transporter in der Kammer genau vor Shaffars Kammern, wenn Ihr den Weg freigemacht habt. Keine Sorge, ich werde Euch dafür entlohnen...", sourceObjective = "Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.\n\nWenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammer und aktiviert ihn.", progress = "Dieses Gerät hat über ein Dutzend Knöpfe, von denen Euch keiner bekannt vorkommt.", completion = "<Ihr schließt die Augen und drückt einen Knopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10218] = { id = 10218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemandes Arbeit zahlt sich aus", description = "Wen habt Ihr erwartet?! Dieser Idiot Morphalius wurde entpriorisiert. Jetzt bin ich hier, um sein Chaos aufzuräumen. Alles, was ich von Euch will, ist, dass Ihr mir den Rücken freihaltet, während ich Shaffars Astralsammler durchgehe und ihnen alles entnehme, was sie gesammelt haben. Wenn ich meinen Auftrag erfolgreich abschließe, wird Haramad selbst Euch belohnen!\n\nWas sagt Ihr? Begleitet mich durch die Managruft und sammelt ein paar unglaubliche Schätze! Die meiste Arbeit habt Ihr ohnehin schon erledigt! Hinter uns ist nichts mehr am Leben, oder?", sourceObjective = "Begleitet Kryoingenieur Sha'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann.\n\nMeldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart.", completion = "Da dies Morphalius' Idee war, habe ich ihm seinen alten Job zurückgegeben. Gut gemacht, kleines Fleischwesen. Wirklich gut!\n\nDenkt daran, wenn Ihr je auf der Suche nach Arbeit und im Nethersturm seid, sucht mich auf der Sturmsäule auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10220] = { id = 10220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie zum Zuhören", description = "Ich wurde hierher geschickt, Kontakt zu den unerschütterlichen Geistern herzustellen. Diese einst stolzen Soldaten der Allianz wurden vor langer Zeit besiegt, und nun spuken ihre Geister in den Ruinen im Westen.\n\nWenn sie sich uns anschließen würden, hätten wir einen mächtigen Verbündeten. Stellt Euch nur vor, eine Armee von untoten Kriegern, die sich unserem Feind entgegenstellt. Aber diese Untoten sind blind vor Hass und wollen sich meinen Vorschlag nicht anhören.\n\nVielleicht kann man sie zwingen, sich uns anzuschließen.", sourceObjective = "Mordiba möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 8 unerschütterliche Krieger und 6 unerschütterliche Zauberhexer beim Expeditionsrüstlager westlich des Rückenbrecherpostens tötet.", completion = "Die Unerschütterlichen haben die Macht der Horde gespürt. Vielleicht haben sie jetzt ja Lust, sich meinen Vorschlag anzuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10221] = { id = 10221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dr. Bumm!", description = "{name}, mein früherer Schützling, Sparky Überschub, hat sich geweigert, während seiner Arbeit hier seinen Helm zu tragen und hat sich in den berüchtigten Dr. Bumm verwandelt!\n\nEr hat sich mit einem Großteil unserer Pionierausrüstung nach Nordosten aufgemacht! Seitdem sind er und seine Bummbots eine große Bedrohung für Area 52!\n\nIch möchte, dass Ihr zu seinem Lager außerhalb der Stadt geht und ihm ein Ende macht! Benutzt diese Bummbomben um ihn auszulöschen.\n\nUnd passt auf, dass Ihr ihm oder seinen Bummbots nicht zu nahe kommt!", sourceObjective = "Tötet Dr. Bumm und kehrt dann mit den guten Nachrichten zu dem leitenden Ingenieur Zischeldruck in Area 52 im Nethersturm zurück.", progress = "Habt Ihr uns vor den Verwüstungen durch Dr. Bumm gerettet? Ich verspreche Euch, dass es diesmal keine explodierenden Wagen gibt, auch wenn das wirklich spaßig war!\n\nWir sollten das wirklich öfter tun!", completion = "Ich werde Sparky immer vermissen. <Schnief> Aber jetzt, da wir wissen, dass Dr. Bumm uns nicht mehr tyrannisieren kann, werden wir alle besser schlafen.\n\nLasst Euch das ein Lehre sein. Kommt hier nicht ohne Netherhelm runter!\n\nNun, wie kann ich Euch dafür belohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10222] = { id = 10222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison des Sonnenzornpostens", description = "Nachdem Prinz Kael'thas' Streitkräfte das Dorf zerstört und den Erzmagier im Turm eingesperrt hatten, haben sie sich zum Sonnenzornposten im Nordosten zurückgezogen. Die gleichen Männer, die unser Dorf zerstört und unsere Freunde getötet haben, stoßen nun auf ihren 'unglaublichen Sieg' an, während wir unsere Gefallenen nicht rächen können.\n\nWir dürfen diese Verbrechen nicht ungestraft lassen! Seid unser Instrument der Rache, {name}. Geht zum Sonnenzornposten und fordert das Leben der Verantwortlichen für dieses Verbrechen ein!", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr 10 Bogenschützen des Sonnenzorns tötet.", completion = "Was Ihr getan habt, kann die Gefallenen nicht zurückbringen, aber vielleicht kann es ihre Geister beruhigen. Obwohl ehrlich gesagt kein Blut der Welt meinen Zorn über Kael'thas Taten stillen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10223] = { id = 10223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Daellis", description = "Den Blutelf, der den Angriff geführt hat, werde ich nie vergessen. Er trug einen Wappenrock mit einem Ding, was ich noch nie zuvor gesehen habe, über einer roten Rüstung.\n\nEr war wild und erbarmungslos, und kämpfte an der Front, wo man kaum einen anderen Blutelfenoffizier je zu Gesicht bekommt. Er war an diesem Tag für den Tod vieler Kirin Tor verantwortlich, aber er blieb nicht lange im Sonnenzornposten. Kael'thas hat ihn zur Manaschmiede Duro beordert, um bei ihrem Versuch, das Gebiet zu kontrollieren, zu helfen. Findet ihn, {name}, und bringt seinen Bogen für immer zum Schweigen.", sourceObjective = "Hüter Dierwert in Kirin'Var möchte, dass Ihr Meister Daellis Morgenschlag tötet.", completion = "<Ihr seid Euch nicht sicher, aber es sieht so aus, als würde Hüter Dierwert gleich anfangen zu weinen.>\n\nEndlich ist es geschafft. Wenn ich könnte, würde ich meine Existenz selbst auslöschen, aber die Wahrheit ist, dass ich nicht loslassen kann. Für die Leute im Dorf ist es schwer, aber zumindest ehrlich. Ich schätze, das ist der Preis, den wir dafür bezahlen müssen, dass wir uns so sehr an diesen Ort gebunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10224] = { id = 10224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenzen für die Motoren", description = "Als Chefingenieur der X-52 ist es meine Pflicht dafür zu sorgen, dass die Hauptmotoren der Netherrakete tiptop in Schuss sind.\n\nUnglücklicherweise habe ich sie noch nicht gebaut.\n\n{class}, ich bin hier in einer Notlage! Ich habe fast alle Teile. Ich brauche nur noch einen Antriebskern.\n\nZum Glück bin ich der Meinung, dass wir die Essenz der Managespenster in der Nähe nutzen können, um die Motoren zu überbrücken.\n\nIhr findet die Managespenster überall bei diesen komischen leuchtenden Gräben im Norden der Insel. Außer hier in Area 52 natürlich.", sourceObjective = "Sammelt 7 Essenzen eines Managespensts und bringt sie zu Chefingenieur Trep bei Area 52 im Nethersturm.", progress = "Habt Ihr schon alle Essenzen?", completion = "Wow, das sind viele Essenzen!\n\nGut, schauen wir mal, was passiert, wenn ich sie mit den Astrallithiummatrixkristallen mische.", sourceObjectiveStatus = "unverified-source-field" }
quests[10225] = { id = 10225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung beim Chefingenieur", description = "{name}! Ich möchte, dass Ihr all diese Astrallithiumkristalle zu Chefingenieur Trep, meinem, äh, Ingenieurschef bringt.\n\nEr sollte wissen, was mit ihnen zu tun ist. Und wenn er es nicht weiß, dann sorgt dafür, dass er es herausfindet.", sourceObjective = "Bringt die Astrallithiummatrixkristalle zu Chefingenieur Trep in Area 52 im Nethersturm.", progress = "Äh, hallo. Ich bin hier ein wenig beschäftigt. Was habt Ihr da?", completion = "Oh, Astrallithiummatrixkristalle! Ja, die klingen wichtig.\n\nLasst sie uns dort drüben hinstellen und ich kümmere mich gleich um sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10226] = { id = 10226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarenergieextraktor", description = "Verdammt, das hat nicht geklappt.\n\nOk, ich habe eine andere Idee. Ich habe Xyrol einen Elementarenergieextraktor herstellen lassen. Ich weiß nicht genau, was man mit dieser Energie anfangen kann, aber ich werde schon einen Verwendungszweck für sie finden.\n\nDie zerrissenen Rumpler und Sphärenentartungen auf dem Felsvorsprung der Schwindenden Weite im Süden haben genau das, was wir für die Motoren brauchen!\n\nDer Extraktor wird ihre Energie in eine feste Form bringen, die Ihr aufsammeln könnt, nachdem Ihr sie besiegt habt.", sourceObjective = "Extrahiert 5 Einheiten Elementarenergie und bringt sie zu Chefingenieur Trep in Area 52 im Nethersturm.", progress = "Habt Ihr die Energie von diesen Elementaren schon? Oh, keine Hektik oder so. Hängt ja nur mein Leben und meine Karriere davon ab.", completion = "Das ist besser! Gut, ich glaube, jetzt sind wir im Geschäft.\n\nLasst mich dieses Zeug nur kurz in das Zau-ba-Ding hier tun, und ich bin sicher, dass es gleich einen voll funktionsfähigen Phasenantriebskern ausspuckt.\n\nOh, he, ich sollte Euch vielleicht dafür belohnen, dass Ihr meine Haut gerettet habt. Hehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10227] = { id = 10227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe tote Draenei", description = "Ich sehe tote Draenei. Sie sind überall.\n\nPah, niemand glaubt mir, weil ich ein Kind bin. Nichtmal meine Mama glaubt mir.\n\n<Ha'lei zeigt auf Ramdor.>\n\nEr glaubt mir. Er sieht sie auch. Und er regt sich darüber auf!\n\nIrgendwie ist es lustig. Ich sehe Geister und die Leute lächeln mich nur an und tätscheln mir den Kopf, um mich zu beruhigen. Ramdor sieht Geister und sie halten ihn für verrückt. Ich hoffe echt, dass ich nie erwachsen werde!\n\nVielleicht solltet Ihr erst mit Ramdor reden, bevor Ihr da hinein geht. Er war einst ein Totenpriester.", sourceObjective = "Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta.", completion = "Das Kind hat Recht. Ich war einst ein \"Totenpriester\".\n\n<Ramdor zuckt zusammen.>\n\nWas für ein abstoßender Titel. Innen findet Ihr die Überbleibsel meines Ordens. Sie sind natürlich alle verrückt! Wahnsinnig! Ich denke, ich habe mich sehr hervorgehoben, da ich der letzte von ihnen mit gesundem Menschenverstand war. Natürlich wurde ich wegen meines Glaubens exkommuniziert.\n\nWas, sagtet Ihr, glaube ich noch gleich?", sourceObjectiveStatus = "unverified-source-field" }
quests[10228] = { id = 10228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ezekiel", description = "Ich bin der Meinung, dass die Toten, um die wir uns seit den letzten 500 Jahren gekümmert haben, in Ruhe gelassen werden sollten. Aber Maladaar hat andere Pläne. Er hat sich in die Krypta des Gedenkens zurückgezogen, um seine Experimente zu beginnen... Nekromantie.\n\nIch hoffe, Ihr hattet nicht vor, dorthin zu gehen... nicht bevor Ihr mir geholfen habt, diese verdammten Geister loszuwerden. Ich weiß, wo sie ihre Schätze aufbewahren, {race}. Jetzt habe ich Eure Aufmerksamkeit, was?\n\nBringt mir das Buch der Toten, das sich im Besitz des Aldors Ezekiel von Shattrath befindet.", sourceObjective = "Sprecht mit Ezekiel von Shattrath in Shattrath.", completion = "Buch der Toten? Nie davon gehört... Worum geht es überhaupt? Wer hat Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10229] = { id = 10229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Folianten entziffern", description = "Dieser Foliant scheint eine Art Geschichtsbuch zu sein, das in einer Geheimschrift der Allianz geschrieben wurde. Althen der Historiker im Rückenbrecherposten hat die Unerschütterlichen eine Zeit lang studiert. Vielleicht kann er die Geheimschrift der Allianz entziffern und das Buch lesen.", sourceObjective = "Bringt den geheimnisvollen Folianten zu Althen dem Historiker im Rückenbrecherposten.", progress = "Was ist das? Ein Buch von einem unerschütterlichen Geist? Wie merkwürdig. Lasst es mich anschauen, vielleicht kann ich mehr über die Geschichte der Unerschütterlichen erfahren.", completion = "Ich habe mein ganzes Unleben lang alte Geschichte studiert, doch nie zuvor etwas wie dieses Buch gesehen. Er erzählt die gesamte Geschichte des Rüstlagers, sogar die Ereignisse nach seiner Zerstörung.\n\nDie Unerschütterlichen haben ihre Geschichte aufgeschrieben, sogar nach ihrem Tod in der Schlacht. Mit diesem Buch können wir die Unerschütterlichen verstehen und sie sicher davon überzeugen, sich uns anzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10230] = { id = 10230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kampfhorn", description = "Vielleicht haben wir uns ganz falsch an diese \"Unerschütterlichen\" herangewagt.\n\nDieser Foliant sagt, dass das Expeditionsrüstlager der Allianz vor langer Zeit von den Orcs und den Todesrittern zerstört wurde. Die Unerschütterlichen wurden dort als rachedurstige Geister in einer ewigen Schlacht gegen die Klans der Höllenorcs gefangen.\n\nSie denken nur an Rache. Wir müssen ihnen die Chance geben, ihre meist verhassten Feinde zu besiegen. Kehrt noch einmal in die Ruinen des Rüstlagers zurück und sucht Feldkommandant Thalvos. Er trägt ein Kampfhorn, das die Unerschütterlichen rufen kann. Bringt es mir.", sourceObjective = "Besorgt Euch das Kampfhorn der Unerschütterlichen von Feldkommandant Thalvos und bringt es zu Althen dem Historiker im Rückenbrecherposten.", progress = "Wir müssen den Unerschütterlichen bald helfen. Wenn wir sie davon überzeugen können, sich uns anzuschließen, hat die Horde einen starken Verbündeten.", completion = "Gut gemacht, {name}. Dieses alte Horn wird uns helfen, die Unerschütterlich zu rufen.\n\nNatürlich nur, wenn sie es möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10231] = { id = 10231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welches Buch? Ich sehe kein Buch.", description = "Ramdor? Hmm, mal überlegen... Ramdor... Oh ja, der Totenpriester. Was will er denn mit dem Buch? Nun, es ist gleichgültig. Ja, ich habe Euch angelogen und nein, ich habe das Buch nicht. Nicht mehr zumindest. Es wurde gestohlen. Wahrscheinlich von einem dieser widerlichen Flüchtlinge.\n\nIm Übrigen existiert Auchindoun nicht mehr. Wir haben keine Verwendung mehr für das Buch. Wenn Ihr es findet, könnt Ihr es behalten.\n\nWie schon gesagt, ich habe ein paar dieser Grobiane letzte Woche um die Terrasse herumschleichen sehen. Fangt mit Eurer Suche bei ihnen an. Wahrscheinlich spielen sie irgendwo im Armenviertel Würfelspiele.", sourceObjective = "Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben.", progress = "Was willsu?", completion = "Ok, Ok! Tut uns nicht weh. Wir hatten das Buch, aber wir haben es verkauft...", sourceObjectiveStatus = "unverified-source-field" }
